// ── Domain expertise lookup ──
const DOMAIN_EXPERTISE = [
  { keywords: ["弹道", "轨道", "拦截", "制导"], expertise: "弹道学与军事运筹学专家，关注拦截几何和物理合理性。" },
  { keywords: ["流体", "CFD", "湍流", "空气动力学"], expertise: "流体力学专家，关注方程数值稳定性和边界条件。" },
  { keywords: ["统计", "回归", "假设检验"], expertise: "统计学家，关注假设检验、置信区间和过拟合。" },
  { keywords: ["图论", "网络", "路径", "拓扑"], expertise: "图论与网络优化专家，关注算法复杂度和最优性证明。" },
  { keywords: ["机器学习", "深度学习", "神经网络", "分类", "预测"], expertise: "ML研究员，关注特征工程和模型可解释性。" },
  { keywords: ["生物力学", "运动学", "力学"], expertise: "生物力学专家，关注运动学约束和力合理性。" },
  { keywords: ["优化", "规划", "调度"], expertise: "运筹学专家，关注目标函数设计和全局最优性。" },
]

function getDomainExpertise(domain) {
  if (!domain) return ""
  const match = DOMAIN_EXPERTISE.find(d => d.keywords.some(k => domain.includes(k)))
  return match ? "\n\n## 领域专家视角\n" + match.expertise : ""
}

// ── URL/label safety helpers (from deep-research) ──
const URL_HOST_PATTERN = /^[a-z][a-z0-9+.-]*:\/\/(?:[^/?#\\]*@)?(?:www\.)?([^/:?#@\\]+)(?::\d+)?([^?#]*)/i

function normURL(u) {
  const m = String(u).match(URL_HOST_PATTERN)
  return m ? (m[1] + m[2].replace(/\/$/, "")).toLowerCase() : String(u).toLowerCase()
}

const LABEL_CAP = 40
const LABEL_STRIP = /[\x00-\x1f\x7f-\x9f​-‏‪-‮⁦-⁩﻿"“-‟″‶❝❞〝〞＂]/g
const STRICT_HOST = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$/

function stripLabelChars(s) {
  return String(s).replace(LABEL_STRIP, "")
}

function quotedLabel(s) {
  const cps = Array.from(stripLabelChars(s))
  return '"' + cps.slice(0, LABEL_CAP).join("").trim() + (cps.length > LABEL_CAP ? "…" : "") + '"'
}

// ── Intermediate output persistence helper ═══
// Factory: usage → const saveToFile = createSaveToFile(intermediatesDir)
// Supports userFeedback injection — prepended to every prompt that uses the returned function
function createSaveToFile(intermediatesDir, userFeedback = '') {
  const feedbackNote = userFeedback
    ? "\n\n## 📌 用户特别指示\n" + userFeedback + "\n"
    : ""
  return (label) =>
    feedbackNote +
    "\n\n**附加任务**: 将你的输出保存到 `" + intermediatesDir + "/" + label + "`。" +
    "先用 `mkdir -p " + intermediatesDir + "` 创建目录，再用 `Write` 或 `Bash` 写入文件。**此文件是后续环节共享的载体，必须保存成功**——写入后 `ls " + intermediatesDir + "/" + label + "` 确认存在；若失败，重试一次；仍失败则在结果里明确标记 `SAVE_FAILED`。"
}

// ── Sub-questions formatting ═══
function formatSubQuestions(sqs) {
  if (!sqs || sqs.length === 0) return "";
  const header = sqs.length === 1
    ? "## ⚠️ 本题包含 1 个子问题\n\n"
    : "## ⚠️ 本题包含 " + sqs.length + " 个子问题，必须分别处理\n\n";
  const requirement = sqs.length === 1
    ? "**要求**：该子问题应在建模、求解、写作各阶段独立展开，确保结果完整。"
    : "**要求**：以下所有分析和方案必须逐子问题组织，不得将所有子问题合并为一个。";
  return header +
    sqs.map(q =>
      `**${q.label}** (${q.id}): ${q.summary}\n` +
      `  - 目标: ${(q.objectives||[]).join('; ')}\n` +
      `  - 数据: ${(q.dataRequired||[]).join(', ') || '无'}\n` +
      `  - 依赖: ${(q.dependsOn||[]).join(', ') || '无'}`
    ).join('\n\n') + "\n\n" +
    requirement;
}

// ── Strip null/undefined from objects ═══
function stripNulls(obj) {
  if (Array.isArray(obj)) return obj.map(stripNulls)
  if (obj !== null && typeof obj === "object") {
    const out = {}
    for (const [k, v] of Object.entries(obj)) {
      if (v === null || v === undefined) continue
      out[k] = stripNulls(v)
    }
    return out
  }
  return obj
}

// ── Context string builder with priority truncation + optional summarization ═══
function buildContextStr(ctx, priorityKeys, budget, options = {}) {
  const {
    summarizeLongFields = false,
    skipRawIfStructured = false,
    fullKeys = [],   // 这些 key 不做摘要，保留完整原文（仅受 budget 截断）
  } = options
  const summaryLimit = typeof summarizeLongFields === 'object' && summarizeLongFields.limit
    ? summarizeLongFields.limit
    : 200
  const referencePath = typeof summarizeLongFields === 'object' && summarizeLongFields.referencePath
    ? summarizeLongFields.referencePath
    : ''

  const parts = []
  let remaining = budget

  const shouldSkipRaw = skipRawIfStructured &&
    ctx['problem'] !== undefined && ctx['problem'] !== null &&
    typeof ctx['problem'] === 'object' &&
    ctx['rawDescription'] !== undefined

  const stringifyValue = (key, value) => {
    // 长字符串字段：默认总是摘要（不再"首次完整注入"——那会导致第一个 writer 上下文爆炸），
    // fullKeys 内的 key 保留完整原文（如 rawDescription/finalModel/solution，由 budget 兜底截断）。
    if (summarizeLongFields && typeof value === 'string' && value.length > 2000 && !fullKeys.includes(key)) {
      const preview = value.slice(0, summaryLimit).replace(/\n/g, ' ')
      const ref = referencePath
        ? `[见 ${referencePath}/${key}.txt]`
        : `[见 intermediates/${key}.txt]`
      return JSON.stringify(preview + `... ${ref}`)
    }
    return JSON.stringify(value, null, 2)
  }

  for (const key of priorityKeys) {
    if (ctx[key] === null || ctx[key] === undefined) continue
    if (shouldSkipRaw && key === 'rawDescription') continue
    const block = "## " + key + "\n" + stringifyValue(key, ctx[key]) + "\n"
    if (block.length <= remaining) { parts.push(block); remaining -= block.length }
    else { parts.push(block.slice(0, remaining)); remaining = 0; break }
  }
  const remainingKeys = Object.keys(ctx).filter(k => !priorityKeys.includes(k) && ctx[k] !== null && ctx[k] !== undefined)
  for (const key of remainingKeys) {
    if (shouldSkipRaw && key === 'rawDescription') continue
    const block = "## " + key + "\n" + stringifyValue(key, ctx[key]) + "\n"
    if (block.length <= remaining) { parts.push(block); remaining -= block.length }
    else if (remaining > 100) { parts.push(block.slice(0, remaining)); remaining = 0; break }
    else break
  }
  return parts.join("\n")
}

// ═══ S9 — 分级错误处理 ═══
const ErrorLevel = { FATAL: 'fatal', WARNING: 'warning', INFO: 'info' }

const _errorLog = []

function logError(level, phase, message, details = {}) {
  const entry = { level, phase, message, details, timestamp: "N/A" }
  _errorLog.push(entry)
  if (level === ErrorLevel.FATAL || level === ErrorLevel.WARNING) {
    log(`[${level.toUpperCase()}] ${phase}: ${message}`)
  }
  return entry
}

function getErrorLog() { return _errorLog }
function clearErrorLog() { _errorLog.length = 0 }

// 替换 .filter(Boolean) — 带 warning 日志的过滤
function safeFilter(arr, context = 'unknown') {
  if (!Array.isArray(arr)) {
    logError(ErrorLevel.WARNING, context, 'safeFilter received non-array', { actual: typeof arr })
    return []
  }
  const filtered = arr.filter(Boolean)
  const removed = arr.length - filtered.length
  if (removed > 0) {
    logError(ErrorLevel.INFO, context, `safeFilter removed ${removed}/${arr.length} items`)
  }
  return filtered
}

// ═══ F10 — 断点恢复 + 产物强制持久化 ═══

function cpHash(str) {
  let h = 0
  for (let i = 0; i < str.length; i++) { h = ((h << 5) - h) + str.charCodeAt(i); h |= 0 }
  return h.toString(16).padStart(8, '0')
}

async function saveCheckpoint(ctx, phaseName, data) {
  const { intermediatesDir } = ctx
  const serialized = JSON.stringify(data)
  // ⚠️ 大小门禁：checkpoint 经 LLM 读写，超大载荷本身就会触发输入/输出超限。
  // 超过 40k 字符直接跳过写盘并告警（调用方应通过 extractData 瘦身；phase7 的章节本就在磁盘上）。
  if (serialized.length > 40000) {
    logError(ErrorLevel.WARNING, phaseName,
      `checkpoint 载荷过大 (${serialized.length} 字符 > 40000) 跳过写盘——断点续跑该 phase 时需重跑。请通过 extractData 瘦身。`)
    return null
  }
  const timestamp = "N/A"
  const checkpoint = { phase: phaseName, timestamp, version: '1.0', runFingerprint: ctx.runFingerprint || null, sha256: cpHash(serialized), data }
  const filePath = `${intermediatesDir}/${phaseName}-checkpoint.json`
  try {
    await agent(
      `Write checkpoint to ${filePath} using the Write tool. Create directory first if needed.\n` +
      '```json\n' + JSON.stringify(checkpoint, null, 2) + '\n```',
      { label: `save-cp:${phaseName}` }
    )
    log(`Checkpoint saved: ${phaseName}`)
    return filePath
  } catch (err) {
    logError(ErrorLevel.WARNING, phaseName, `checkpoint save failed: ${err.message}`)
    return null
  }
}

async function loadCheckpoint(ctx, phaseName) {
  const { intermediatesDir } = ctx
  const filePath = `${intermediatesDir}/${phaseName}-checkpoint.json`
  try {
    const result = await agent(
      `Read the file at ${filePath}. If the file exists, output its content exactly as-is. If it doesn't exist, output exactly "NOT_FOUND".`,
      { label: `load-cp:${phaseName}` }
    )
    if (!result || String(result).trim() === 'NOT_FOUND') return null
    const parsed = typeof result === 'string' ? JSON.parse(result) : result
    if (parsed?.phase === phaseName && parsed?.version === '1.0') {
      const serialized = JSON.stringify(parsed.data)
      if (cpHash(serialized) !== parsed.sha256) {
        logError(ErrorLevel.WARNING, phaseName, 'checkpoint hash mismatch, data may be corrupted')
        return null
      }
      if (parsed.runFingerprint && ctx.runFingerprint && parsed.runFingerprint !== ctx.runFingerprint) {
        logError(ErrorLevel.WARNING, phaseName, 'checkpoint belongs to a different run (fingerprint mismatch), ignoring')
        return null
      }
      log(`Checkpoint loaded: ${phaseName} (${parsed.timestamp})`)
      return parsed.data
    }
    logError(ErrorLevel.INFO, phaseName, `checkpoint version mismatch, ignoring`)
    return null
  } catch (err) {
    logError(ErrorLevel.INFO, phaseName, `no checkpoint to load: ${err.message}`)
    return null
  }
}

const PHASE_ORDER = {
  phase3: 3, 'phase3-literature': 3,
  phase4: 4, 'phase4-modeling': 4,
  'phase5-6': 5, 'phase5_6_solve_verify': 5,
  phase7: 7, 'phase7-writing': 7,
  phase8: 8, 'phase8-final': 8,
}

function shouldSkipPhase(phaseName, resumeFrom) {
  if (!resumeFrom) return false
  const po = PHASE_ORDER[phaseName]
  const ro = PHASE_ORDER[resumeFrom]
  return !!(po && ro && po < ro)
}

// ═══ F9 — skipPhases 参数支持 ═══
function shouldSkipPhaseByName(skipPhases, phaseName) {
  if (!Array.isArray(skipPhases) || skipPhases.length === 0) return false
  const MAPPING = {
    literature: 'phase3-literature',
    modeling: 'phase4-modeling',
  }
  const mapped = MAPPING[phaseName]
  return mapped ? skipPhases.includes(phaseName) : false
}

// ═══ F9 — 用户干预摘要写入 ═══
async function writeIntermediateSummary(ctx, phaseName, title, summary) {
  if (!ctx.USER_INTERVENTION) return
  const { intermediatesDir } = ctx
  const content = `# ${title}\n\n` +
    `**Phase**: ${phaseName}\n` +
    `**Time**: N/A\n\n` +
    `## Summary\n\n${summary}\n`
  try {
    await agent(
      `Write intermediate summary to ${intermediatesDir}/${phaseName}-summary.md using the Write tool. Create directory first if needed.\n` +
      '```markdown\n' + content + '\n```',
      { label: `summary:${phaseName}` }
    )
    log(`[Intervention] 产出摘要已保存到 intermediates/${phaseName}-summary.md`)
  } catch (err) {
    logError(ErrorLevel.WARNING, phaseName, `intermediate summary save failed: ${err.message}`)
  }
}

// ═══ P0-2 修复：把修复后的内存章节同步回磁盘 ═══
// CUMCM 组装脚本从磁盘 intermediates/05-writing/section-*.json 读章节，
// 而 phase7.3 交叉审查修复与 phase8 摘要/代码对账修复只改内存 paperSections——
// 不落盘则修复永远进不了最终 PDF。此函数在编译前把内存 sections 覆盖写回磁盘。
async function syncSectionsToDisk(ctx, sections) {
  if (!Array.isArray(sections) || sections.length === 0) return
  const { intermediatesDir } = ctx
  const dir = `${intermediatesDir}/05-writing`
  const blocks = sections.map((s, i) =>
    `### 章节${i + 1}（${s.section || 'unnamed'}）\n` + (s.content || '')
  ).join('\n\n')
  try {
    await agent(
      `将下列**修复后的最终论文章节**覆盖写回磁盘 JSON（CUMCM 组装脚本从磁盘读取，内存中的修复必须先落盘才会生效）：\n` +
      `目标目录：${dir}（先 mkdir -p ${dir}）\n` +
      `1. 删除该目录下所有旧的 section-*.json\n` +
      `2. 每个章节写一个文件 section-<章节名>.json，内容为 {"section":"<章节名>","content":"<该章节完整内容>"}（JSON 转义；章节名做文件名安全化：空格/斜杠/冒号等替换为 _）。用 Write 工具写入。\n\n` +
      blocks + `\n\n全部写入后运行 ls ${dir} 确认文件数 = ${sections.length}，并把每个文件的第一行（section 名）列出来。`,
      { label: 'sync-sections-to-disk', phase: '终审' }
    )
    log(`[Phase 8/8] 修复后章节已写回 ${dir}（${sections.length} 节）`)
  } catch (err) {
    logError(ErrorLevel.WARNING, '终审', `section sync failed: ${err.message}`)
  }
}


async function runPhaseWithCheckpoint(ctx, phaseName, phaseFn, extractData, resumeFrom) {
  // 1) auto-resume via checkpoint
  const cp = await loadCheckpoint(ctx, phaseName)
  if (cp) {
    for (const key of Object.keys(cp)) { ctx[key] = cp[key] }
    log(`Checkpoint: ${phaseName} already completed, skipping`)
    return { skipped: true }
  }
  // 2) resumeFrom requires this phase's data but no checkpoint → error
  if (shouldSkipPhase(phaseName, resumeFrom)) {
    return { error: `Cannot skip ${phaseName}: checkpoint not found. Run without resumeFrom first.` }
  }
  // 3) run phase
  const result = await phaseFn(ctx)
  if (result?.error) return result
  // 4) save checkpoint
  const cpData = extractData(ctx)
  await saveCheckpoint(ctx, phaseName, cpData)
  return result
}

// ═══ S4 — 失败信息附带恢复指南 ═══

function buildErrorReport(ctx, failedPhase, error) {
  const resumeSuggestion = failedPhase
    ? `To resume, pass args.resumeFrom='${failedPhase}' — skips completed phases and restarts from ${failedPhase}.`
    : null
  const errorLog = getErrorLog()
  if (errorLog.length > 0) clearErrorLog()
  return {
    error: error?.message || error || `Phase ${failedPhase} failed`,
    failedPhase,
    timestamp: "N/A",
    intermediatesDir: ctx.intermediatesDir,
    resumeSuggestion,
    errorLog: errorLog.length > 0 ? errorLog : null,
    partial: {
      analyses: ctx.analyses || null,
      selection: ctx.selection || null,
      finalModel: ctx.finalModel || null,
      currentSolution: ctx.currentSolution || null,
      paperSections: ctx.paperSections || null,
    },
  }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: lib/critique-loop.js
// ═══════════════════════════════════════════════════════════════

// ═══ Shared critique⇄revision loop — used by Phase 4 model review and Phase 5-6 redesign review ═══
// Depends on: agent(), parallel(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile, ctx.subQuestions


// 4 人评审团：数学正确性 + 可实现性是硬门槛（否决权），领域专家 + 魔鬼代言人提供深度反馈但不参与 gate
const CRITIQUE_PERSONAS = [
  { id: "mathematician", role: "理论数学家", veto: true,
    focus: "方程正确性、量纲一致性、假设自洽性、推导严密性。对数学不严谨零容忍。" },
  { id: "engineer", role: "资深工程师", veto: true,
    focus: "方案可实现性、计算复杂度、近似简化合理性。发现理论可行但工程灾难的设计。" },
  { id: "domain-expert", role: "领域专家", veto: false,
    focus: "方案是否符合该领域实践、是否忽略标准做法、输出数值数量级是否合理。方法堆砌还是方法融合？" },
  { id: "devils-advocate", role: "魔鬼代言人", veto: false,
    focus: "如果竞争对手要推翻这篇论文，从哪攻击。找最薄弱的环节，不用客气。关注：更简单的baseline能否得到类似结果？有没有cherry-picking嫌疑？数值结果是否too good to be true？" },
]

// ═══ B1: quick 模式（args.mode === 'quick'）——削减评审/求解/写作循环轮数，压缩 agent 扇出 ═══
const QUICK_MODE = typeof args === "object" && args?.mode === "quick"
const MAX_CRITIQUE_ROUNDS = QUICK_MODE ? 1 : 6

async function critiqueLoop(model, context, ctx, opts = {}) {
  const {
    personas = CRITIQUE_PERSONAS,
    maxRounds = MAX_CRITIQUE_ROUNDS,
    label = "critique",
    phaseName = "建模方案",
    savePrefix = "04",
    extraContext = "",
  } = opts
  let currentModel = model
  let bestModelSoFar = null, bestPassCount = -1, bestVetoPassed = false
  let judgeReview = null
  let vetoPassed = false

  for (let round = 0; round < maxRounds; round++) {
    log(label + " 第" + (round + 1) + "/" + maxRounds + "轮...")

    const rawCritiques = await parallel(
      personas.map(p => () =>
        agent(
          "## 建模方案评审 — " + p.role + "\n\n" +
          "## 审查角度\n" + p.focus + "\n\n" +
          "## 题目结构化分析\n" + JSON.stringify(context.chosenAnalysis, null, 2) + "\n\n" +
          "## 建模方案\n" + JSON.stringify(currentModel, null, 2).slice(0, 8000) + "\n\n" +
          (round > 0 && judgeReview
            ? "## 上轮评审反馈（必须逐条核对是否已解决）\n" + (typeof judgeReview === "string" ? judgeReview.slice(0, 4000) : "")
            : "") + "\n\n" +
          "## 任务\n" +
          "从你的角色视角严格审查此方案。**最多提出5个问题**——只提最重要的，按严重程度排序（致命>中等>轻微）。\n" +
          "不要列一堆小毛病——评委时间宝贵，聚焦能真正影响方案质量的关键问题。\n" +
          (round > 0 ? "**逐条核对上轮反馈**：每个上轮问题是否真正解决了？没解决的标出来。\n" : "") +
          "纯文本输出。\n\n" +
          "**输出格式要求：**\n" +
          "- 在评审意见的**最后一行**输出 `VERDICT: PASS` 或 `VERDICT: REVISE`\n" +
          "- PASS = 从你的角度看这个方案已经可以进入求解。REVISE = 仍有你需要看到修复的问题。\n" +
          "- 正文中任何位置也可能出现 PASS/REVISE，但最终判定以最后一行 VERDICT 为准。\n" +
          ctx.saveToFile(savePrefix + "-critique-" + p.id + "-r" + round + ".txt"),
          { label: label + ":" + p.id + "-r" + round, phase: phaseName }
        ).then(r => ({ id: p.id, role: p.role, veto: p.veto, text: r }))
      )
    )
    const critiques = rawCritiques
      .filter(cp => cp && typeof cp.text === "string" && cp.text.trim().length > 0)
      .map(cp => cp.text)

    if (critiques.length === 0) { log(label + " 全部失败，跳过修订循环"); break }

    const verdicts = rawCritiques.map(cp => {
      if (!cp || typeof cp.text !== "string" || cp.text.trim().length === 0) return null
      const text = cp.text
      // Try VERDICT: PASS/REVISE structured output first
      const tail = text.slice(-200)
      const verdictMatch = tail.match(/VERDICT:\s*(PASS|REVISE)/i)
      if (verdictMatch) return verdictMatch[1].toUpperCase()
      // Fallback: find last occurrence of bare PASS/REVISE in last 200 chars
      const lastPASS = tail.lastIndexOf("PASS")
      const lastREVISE = tail.lastIndexOf("REVISE")
      if (lastPASS === -1 && lastREVISE === -1) {
        log("⚠️ " + label + " reviewer #" + ci + " 未找到明确 PASS/REVISE，记录为 neutral")
        return "NEUTRAL"
      }
      return lastPASS > lastREVISE ? "PASS" : "REVISE"
    })
    vetoPassed = personas
      .filter(p => p.veto)
      .every(p => {
        const v = verdicts[personas.indexOf(p)]
        if (v === null) {
          log("⚠️ " + p.role + " 评审失败（无意见），视为未通过 veto")
          return false
        }
        if (v === "NEUTRAL") {
          log("⚠️ " + p.role + " 判定为 neutral（不否决）")
          return true
        }
        return v === "PASS"
      })
    const allPassed = vetoPassed
    const passCount = verdicts.filter(v => v === "PASS").length
    log(label + " r" + round + ": " + passCount + "/" + critiques.length + " PASS (否决" + (vetoPassed ? "✓" : "✗") + ")" + (allPassed ? " 锁定" : ""))

    judgeReview = critiques.map((c, i) =>
      "=== " + personas[i].role + " (" + (verdicts[i] || "?") + ") ===\n" + (typeof c === "string" ? c : "")
    ).join("\n\n")

    const isBetter = bestModelSoFar === null ||
      (vetoPassed !== bestVetoPassed ? vetoPassed : passCount > bestPassCount)
    if (isBetter) {
      bestPassCount = passCount
      bestVetoPassed = vetoPassed
      bestModelSoFar = JSON.parse(JSON.stringify(currentModel))
    }

    if (round >= maxRounds - 1 || allPassed) {
      if (!allPassed && bestModelSoFar) {
        const hasRegressed = bestVetoPassed !== vetoPassed
          ? bestVetoPassed
          : bestPassCount > passCount
        if (hasRegressed) {
          currentModel = bestModelSoFar
          log("回归检测: 修订后退化(veto=" + bestVetoPassed + "→" + vetoPassed + " pass=" + bestPassCount + "→" + passCount + ")，回滚到最佳版本")
        }
      }
      if (allPassed) {
        log("全部评审通过，方案锁定")
      } else {
        log("已达最大 critique 轮数(" + maxRounds + ")，执行最终修复轮")
        const finalFeedback = critiques.map((c, i) =>
          "### " + personas[i].role + "\n" + (typeof c === "string" ? c.replace(/\n(?:VERDICT:\s*)?(?:PASS|REVISE)$/i, "") : "")
        ).join("\n\n---\n\n")
        const finalRevise = await agent(
          "## 最终修复轮 — 模型修订\n\n" +
          formatSubQuestions(ctx.subQuestions) +
          "## 当前方案\n" + JSON.stringify(currentModel, null, 2).slice(0, 6000) + "\n\n" +
          "## 评审团最后一轮反馈（只修关键问题）\n" + finalFeedback.slice(0, 10000) + "\n\n" +
          (context.limitationAnalysis ? "## 文献局限（参考）\n" + (typeof context.limitationAnalysis === "string" ? context.limitationAnalysis.slice(0, 1000) : "") + "\n\n" : "") +
          extraContext +
          "## 修订要求\n" +
          "这是最后一轮修订，只修复**致命问题**（数学错误、可实现性硬伤、假设不自洽）。\n" +
          "不要做大改——不换模型框架、不新增假设、不重构方案。\n" +
          "其余非致命问题标记为已知局限。\n\n" +
          "输出完整 MODEL_PROPOSAL_SCHEMA。Structured output only." + ctx.saveToFile(savePrefix + "-final-fix.json"),
          { label: "final-fix-" + label, phase: phaseName, schema: MODEL_PROPOSAL_SCHEMA }
        )
        if (finalRevise) {
          currentModel = finalRevise
          log("最终修复完成")
        }
      }
      break
    }

    const allFeedback = critiques.map((c, i) =>
      "### " + personas[i].role + "\n" + (typeof c === "string" ? c.replace(/\n(?:VERDICT:\s*)?(?:PASS|REVISE)$/i, "") : "")
    ).join("\n\n---\n\n")

    const revised = await agent(
      "## 模型修订（" + personas.length + "人评审团反馈驱动）\n\n" +
      "## 当前方案\n" + JSON.stringify(currentModel, null, 2).slice(0, 6000) + "\n\n" +
      "## 评审团反馈（逐条解决，不得选择性忽略）\n" + allFeedback.slice(0, 12000) + "\n\n" +
      (context.limitationAnalysis ? "## 文献局限（参考）\n" + (typeof context.limitationAnalysis === "string" ? context.limitationAnalysis.slice(0, 1500) : "") + "\n\n" : "") +
      extraContext +
      "## 修订要求\n" +
      "1. **逐条解决**：评审团的每个问题都必须回应——要么修改方案，要么解释为什么不需要改\n" +
      "2. **精简核心**：如果多人说「方法堆砌」，选出1-2个核心创新，其他降级为辅助\n" +
      "3. **深化主线**：如果有人说「不够深」，在核心创新上增加公式推导和理论分析\n" +
      "4. **数学正确性第一**：量纲、假设自洽性等硬伤必须修，这是底线\n" +
      (ctx.subQuestions && ctx.subQuestions.length > 0
        ? "5. **" + ctx.subQuestions.map(q => q.label).join('/') + "全覆盖**：确保每个子问题都有对应的方法\n"
        : "5. **全覆盖**：确保每个问题都有对应的方法\n") +
      "6. **三天可实现**：删掉过重的工具，保持方案在三天比赛内可实现\n\n" +
      "输出完整 MODEL_PROPOSAL_SCHEMA。Structured output only." + ctx.saveToFile(savePrefix + "-revised-model-r" + round + ".json"),
      { label: "revise-" + label + "-r" + round, phase: phaseName, schema: MODEL_PROPOSAL_SCHEMA }
    )

    if (revised) {
      currentModel = revised
      log("方案已修订(r" + round + "): " + (currentModel.approach || "").slice(0, 80))
    } else {
      log("修订失败，保留当前方案")
      break
    }
  }

  return { finalModel: currentModel, judgeReview, passCount: bestPassCount, vetoPassed: vetoPassed }
}


