// INLINED: lib/phase3-literature.js
// ═══════════════════════════════════════════════════════════════

// ═══ Phase 3: 文献调研 — search → fetch → limitation analysis ═══
// Depends on: agent(), parallel(), pipeline(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile


async function phase3_literature(ctx) {
  const { cfg, chosenAnalysis, selection, currentYear } = ctx

  phase("文献调研")
  log("[Phase 3/8] 文献调研开始 — 预计 8-12 分钟")

  // 收集所有子问题的 objectives 作为搜索关键词（无子问题则用全局 objectives）
  const allSearchObjectives = (() => {
    const subQuestions = ctx.subQuestions || []
    if (subQuestions.length > 0) {
      const merged = [...new Set(subQuestions.flatMap(q => q.objectives || []))]
      if (merged.length > 0) return merged
    }
    return chosenAnalysis.objectives || []
  })()

  const SEARCH_ANGLES = [
    { label: "前沿学术", query: chosenAnalysis.domain + " recent advances mathematical model arxiv " + (currentYear - 1) + " " + currentYear, rationale: "前沿学术成果（arXiv/Google Scholar）" },
    { label: "海外方法", query: chosenAnalysis.domain + " " + allSearchObjectives.slice(0, 3).join(" ") + " state-of-the-art methods review", rationale: "海外最新方法论（英文优先）" },
    { label: "中文核心", query: chosenAnalysis.domain + " " + (chosenAnalysis.mathType || []).join(" ") + " 数学建模 论文", rationale: "国内竞赛相关文献" },
    { label: "开源代码", query: (chosenAnalysis.mathType || ["optimization"])[0] + " modeling solution github python " + (currentYear - 2) + " " + currentYear, rationale: "可复现的代码实现" },
    // 第5搜索角度(数据方法)已删：cfg.searchAngles=4 固定，slice(0,4) 永远取不到。需要时 bump cfg.searchAngles 并恢复此条目。

  ].slice(0, cfg.searchAngles)

  const SEARCH_PROMPT = (angle) =>
    "## 文献搜索: " + angle.label + "\n\n" +
    formatSubQuestions(ctx.subQuestions) +
    "研究题目: " + selection.selected + " — " + chosenAnalysis.domain + "\n" +
    "目标: " + allSearchObjectives.join("; ") + "\n\n" +
    "搜索角度: **" + angle.label + "** — " + angle.rationale + "\n" +
    "搜索词: `" + angle.query + "`\n\n" +
    "用 WebSearch 搜索（可优化搜索词），返回 4-6 条最相关结果。优先学术论文、技术博客、GitHub。跳过 SEO 垃圾。\n\nStructured output only." + ctx.saveToFile("03-search-" + angle.label.replace(/[^a-zA-Z一-龥]/g, "_") + ".json")

  const seenUrls = new Map()
  const relRank = { high: 0, medium: 1, low: 2 }
  let fetchSlots = cfg.maxFetch

  const searchResults = await pipeline(
    SEARCH_ANGLES,
    angle => agent(SEARCH_PROMPT(angle), {
      label: "search:" + angle.label, schema: SEARCH_SCHEMA,
    }).then(r => {
      if (!r) return null
      const resultsArr = Array.isArray(r) ? r : (r.results || [])
      log(angle.label + ": " + resultsArr.length + " 条")
      return { angle: angle.label, results: resultsArr }
    }),
    searchResult => {
      if (!searchResult) return []
      const results = Array.isArray(searchResult) ? searchResult : (searchResult.results || [])
      const sorted = [...results].sort((a, b) => relRank[a.relevance] - relRank[b.relevance])
      const novel = sorted.filter(r => {
        const key = normURL(r.url)
        if (seenUrls.has(key)) return false
        if (fetchSlots <= 0 && relRank[r.relevance] >= 1) return false
        seenUrls.set(key, { angle: searchResult.angle, title: r.title })
        fetchSlots--
        return true
      })
      return parallel(novel.map(source => () => {
        const capturedHost = String(source.url).match(URL_HOST_PATTERN)?.[1] ?? ""
        const host = capturedHost.toLowerCase()
        const cleanHost = stripLabelChars(host)
        const isClean = cleanHost === host && host !== "" && Array.from(host).length <= LABEL_CAP && STRICT_HOST.test(host)
        const hostLabel = cleanHost === "" ? "" : isClean ? host : quotedLabel(host)
        const sourceLabel = hostLabel || (stripLabelChars(source.title).trim() && quotedLabel(source.title)) || "unknown"
        return agent(
          "## 文献精读\n\n研究题目: " + selection.selected + "\n搜索角度: " + searchResult.angle + "\n\n" +
          "**URL:** " + source.url + "\n**标题:** " + source.title + "\n\n" +
          "## 任务\n" +
          "1. 用 WebFetch 获取页面内容\n" +
          "2. 评估来源质量: primary/secondary/blog/forum/unreliable\n" +
          "3. 提取 2-5 条与建模相关的 claim，附原文引用\n" +
          "4. 提取可复用的数学模型（公式、参数、算法、预处理方法）\n" +
          "5. 无法访问/付费墙/不相关 → claims:[], sourceQuality:'unreliable'\n\nStructured output only." + ctx.saveToFile("03-fetch-" + (sourceLabel || "unknown") + ".json"),
          { label: "fetch:" + sourceLabel, schema: EXTRACT_SCHEMA }
        ).then(ext => ext ? { ...ext, url: source.url, title: source.title, angle: searchResult.angle } : null)
          .catch(e => { logError(ErrorLevel.WARNING, "文献调研", "fetch failed: " + source.url, { error: e.message, url: source.url }); return { url: source.url, title: source.title, angle: searchResult.angle, sourceQuality: "unreliable", claims: [], models: [] } })
      }))
    }
  )

  const allSources = safeFilter(searchResults.reduce(function(acc, val) { return acc.concat(val); }, []), "文献调研-allSources")
  const allModels = allSources.flatMap(s => (s.models || []))
  const allClaims = allSources.flatMap(s => (s.claims || []).map(c => ({ ...c, sourceUrl: s.url, sourceQuality: s.sourceQuality })))
  log("[Phase 3/8] 文献调研完成 ✓ — " + allSources.length + " 篇文献, " + allModels.length + " 个模型, " + allClaims.length + " 条关键信息")

  // ── Phase 3.5: 标准解法局限分析 —— 创新的合法来源 ──
  let limitationAnalysis = null
  if (allModels.length > 0 || allClaims.length > 0) {
    limitationAnalysis = await agent(
      "## 标准解法局限分析\n\n" +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
      "## 文献调研结果\n" + JSON.stringify({
        sources: allSources.length,
        models: allModels.slice(0, 10),
        claims: allClaims.slice(0, 12),
      }, null, 2) + "\n\n" +
      formatSubQuestions(ctx.subQuestions) +
      "## 任务\n" +
      "你是一位资深审稿人，专门找现有方法的局限性。创新必须有根有据，不能凭空编造——以下分析是后续建模方案的依据。\n\n" +
      (ctx.subQuestions && ctx.subQuestions.length > 0 ? "请逐子问题分析现有方法的局限性，每个子问题列出 2-3 个关键局限。\n\n" : "") +
      "从以下角度逐一分析标准/主流方法的局限：\n" +
      "1. **假设过强**: 标准方法做了什么不现实的假设？放宽它会发生什么？\n" +
      "2. **精度瓶颈**: 标准方法在什么条件下精度不够？为什么？\n" +
      "3. **计算代价**: 有没有效率问题？高维/大规模时如何处理？\n" +
      "4. **泛化缺陷**: 标准方法在本题目特定约束下是否失效？哪里不匹配？\n" +
      "5. **方法冲突**: 不同文献给出的方法之间有没有矛盾？为什么？\n\n" +
      "每个局限按以下结构输出：「局限描述 → 为什么是问题 → 可能的改进方向」\n" +
      "输出纯文本，不需 JSON。不要泛泛而谈，要引用文献中的具体方法来支撑。" + ctx.saveToFile("03-limitation-analysis.txt"),
      { label: "limitation-analysis", phase: "文献调研" }
    )
    if (limitationAnalysis) {
      log("[Phase 3/8] 标准解法局限分析完成 — " + (typeof limitationAnalysis === "string" ? limitationAnalysis.slice(0, 80).replace(/\n/g, " ") : "..."))
    }
  } else {
    log("[Phase 3/8] 文献较少，跳过局限分析")
  }

  // directionContext — 精简版上下文，给提案/综合用
  let directionContext =
    "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) +
    "\n\n## 文献模型参考\n" + JSON.stringify(allModels.slice(0, 10), null, 2) +
    "\n\n## 文献关键发现\n" + JSON.stringify(allClaims.slice(0, 15), null, 2)
  if (limitationAnalysis) {
    directionContext += "\n\n## 标准解法局限\n" + (typeof limitationAnalysis === "string" ? limitationAnalysis : JSON.stringify(limitationAnalysis))
  }

  // Store results in ctx
  ctx.allSources = allSources
  ctx.allModels = allModels
  ctx.allClaims = allClaims
  ctx.limitationAnalysis = limitationAnalysis
  ctx.directionContext = directionContext

  return { allSources, allModels, allClaims, limitationAnalysis, directionContext }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: lib/phase4-modeling.js
// ═══════════════════════════════════════════════════════════════

// ═══ Phase 4: 建模方案 — gap → 提案 → 综合 → critique⇄修订 loop → 适配性预检 ═══
// Depends on: agent(), parallel(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile, ctx.formatSubQuestions, ctx.subQuestions


async function phase4_modeling(ctx) {
  const { chosenAnalysis, limitationAnalysis, allModels, allClaims, directionContext, cfg, subQuestions, innovationThresholds, innovationStrictness, attachments, figuresDir, outputDir } = ctx
  // Innovation necessity threshold from ctx config
  const thresh = (innovationThresholds && innovationThresholds.threshold) || 0.05
  const threshPct = Math.round(thresh * 100)
  const threshMedPct = threshPct * 3 // auxiliary improvement threshold
  // Thresholds for agent prompts
  const NOT_SIG = '差 < ' + threshPct + '% → 这不是有意义的创新'
  const SIG_RANGE = '差 ' + threshPct + '-' + threshMedPct + '% → 辅助改进'
  const CORE_INNOV = '差 > ' + threshMedPct + '% → 核心创新'

  phase("建模方案")
  log("[Phase 4/8] 建模方案开始 — 预计 10-15 分钟")

  // ── Step 4.0a: 数据需求评估 + 外部数据收集（题目无附件 / 附件不足 / 明确要求查数据时）──
  // 真实比赛（尤其国赛）常有「数据需自行收集」的题（交通/经济/环境/地理等），或附件数据不足。
  // 旧 pipeline 只认附件，无附件就让建模 agent「自行构造数据」——那是编造，评委查来源必挂。
  // 这里：先评估是否需要外部数据；需要则搜权威源 → 下载 → 清洗 → 落盘 data/external/，
  // 每条记录来源 URL + 获取日期；找不到就标 NOT_FOUND 并明说，禁止编造数字。
  let externalData = ctx.externalData || null   // { needsExternalData, dataNeeds, sources: [{id,purpose,status,filePath,sourceUrl,sourceTitle,fetchedAt,fields}] }
  if (!externalData) {
    const dataAssessment = await agent(
      "## 数据需求评估（判断是否需要自行收集外部数据）\n\n" +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
      formatSubQuestions(subQuestions) +
      "## 任务\n" +
      "判断本题是否需要**自行收集外部数据**（国赛/美赛常见：题目不给附件但要求基于真实数据建模，或附件不足以支撑结论）。\n\n" +
      "判定规则：\n" +
      "1. **有附件且数据充分**（dataSufficiency 为 high/medium，题目结论可直接由附件得出）→ needsExternalData=false。\n" +
      "2. **无附件但纯机理/几何/物理推导题**（所有参数题目已给出，如板凳龙、定日镜场）→ needsExternalData=false。\n" +
      "3. **无附件且题目需要真实数据**（如流量、经济指标、天气、地理、人口、行业价格等，题目原文有「查找/收集/查阅/获取数据」「根据实际数据」等字样）→ needsExternalData=true。\n" +
      "4. **附件不足**（dataSufficiency 为 low/insufficient，题目结论需要附件外的补充数据）→ needsExternalData=true。\n\n" +
      "若需要外部数据，列出每条数据需求：\n" +
      "- id：简短标识（如 traffic_flow / gdp_city）\n" +
      "- purpose：用于回答哪个子问题、什么用途\n" +
      "- fields：需要的字段/维度（如 小时级车流量、城市GDP、日气温）\n" +
      "- preferredSources：优先数据源建议（国家统计局、气象局、交通部门、世界银行、公开数据集等）\n\n" +
      "Structured output only." + ctx.saveToFile("04-data-needs.json"),
      {
        label: "data-needs", phase: "建模方案",
        schema: { type: "object", required: ["needsExternalData", "reason"], properties: {
          needsExternalData: { type: "boolean" },
          reason: { type: "string" },
          dataNeeds: { type: "array", items: { type: "object", properties: { id: { type: "string" }, purpose: { type: "string" }, fields: { type: "string" }, preferredSources: { type: "string" } } } },
        } }
      }
    )
    if (dataAssessment && dataAssessment.needsExternalData) {
      log("[Phase 4/8] 数据需求评估：需要外部数据 — " + (dataAssessment.dataNeeds?.length || 0) + " 项")
      const collection = await agent(
        "## 外部数据收集（权威真实数据，禁止编造）\n\n" +
        "## 数据需求\n" + JSON.stringify(dataAssessment.dataNeeds || [], null, 2) + "\n\n" +
        "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" +
        "## 任务\n" +
        "为每条数据需求收集**真实、可验证**的数据，保存到 `" + outputDir + "/data/external/` 目录。\n\n" +
        "### 逐条处理（每条数据需求）：\n" +
        "1. 用 WebSearch 查找权威数据源（优先：国家统计局/地方统计局、气象局、交通部门、世界银行、WHO、政府开放数据平台、权威行业报告；次选：知名公开数据集）\n" +
        "2. 用 python3（requests/pandas/curl）下载数据文件，保存为 `" + outputDir + "/data/external/{id}_{简述}.csv/xlsx/json`\n" +
        "3. 读取确认结构（shape/列名/前几行），必要时做轻量清洗（去表头杂质、统一列名、编码 utf-8），把清洗后的最终文件留在 data/external/ 下\n" +
        "4. 记录：filePath、sourceUrl（精确到页面的真实 URL）、sourceTitle、fetchedAt（今天日期）、fields（字段清单）、notes（口径/单位/范围说明）\n\n" +
        "### ⚠️ 铁律（合规关键，违反会毁掉论文）：\n" +
        "- **数据必须是真实下载/抓取自可验证来源**；禁止凭空构造、近似、抄写论文里的示例数字\n" +
        "- 某个需求找不到可靠来源 → status=NOT_FOUND，写明尝试过哪些源、为什么没有；**绝不伪造数据替代**\n" +
        "- 下载失败重试 1 次；仍失败标 NOT_FOUND\n" +
        "- 每条成功数据必须给精确 sourceUrl（评委/支撑材料会核对）\n\n" +
        "Structured output only." + ctx.saveToFile("04-data-collection.json"),
        {
          label: "data-collector", phase: "建模方案",
          schema: { type: "object", required: ["sources"], properties: {
            sources: { type: "array", items: { type: "object", properties: {
              id: { type: "string" }, purpose: { type: "string" },
              status: { type: "string", enum: ["OK", "NOT_FOUND"] },
              filePath: { type: "string" }, sourceUrl: { type: "string" },
              sourceTitle: { type: "string" }, fetchedAt: { type: "string" },
              fields: { type: "string" }, notes: { type: "string" },
            } } },
          } }
        }
      )
      externalData = {
        needsExternalData: true,
        dataNeeds: dataAssessment.dataNeeds || [],
        sources: (collection && Array.isArray(collection.sources)) ? collection.sources : [],
      }
      log("[Phase 4/8] 外部数据收集完成 — " + externalData.sources.filter(s => s.status === "OK").length + " 份成功, " + externalData.sources.filter(s => s.status === "NOT_FOUND").length + " 份未找到")
    } else {
      externalData = { needsExternalData: !!(dataAssessment && dataAssessment.needsExternalData), dataNeeds: [], sources: [] }
      log("[Phase 4/8] 数据需求评估：无需外部数据" + (dataAssessment && dataAssessment.reason ? "（" + (typeof dataAssessment.reason === "string" ? dataAssessment.reason.slice(0, 80) : "") + "）" : ""))
    }
    ctx.externalData = externalData
  } else {
    log("[Phase 4/8] 外部数据（已评估）：" + (externalData.needsExternalData ? (externalData.sources?.filter(s => s.status === "OK").length || 0) + " 份成功" : "无需"))
  }
  // 外部数据文件列表（供 EDA/问题分析/求解/写作共用）
  const externalDataFiles = (externalData && externalData.sources || []).filter(s => s.status === "OK" && s.filePath).map(s => s.filePath)
  const externalDataStr = externalDataFiles.length > 0
    ? "\n\n## 外部数据文件（自行收集，必须读取使用；来源见 `" + intermediatesDir + "/04-data-collection.json`）\n" +
      externalData.sources.filter(s => s.status === "OK").map((s, i) => (i + 1) + ". `" + s.filePath + "` （来源: " + (s.sourceUrl || "?") + "，获取日期: " + (s.fetchedAt || "?") + "）").join("\n")
    : ""

  // ── Step 4.0: 问题分析（逐问深度分析）—— 优秀获奖论文第2章的内容来源，也是后续建模的依据 ──
  // 每篇优秀论文都有独立的「问题分析」章：逐问给出机理推理→难点→建模思路草图→数据要点。
  // 当前 pipeline 曾把问题分析压进"问题重述"一句话导致写作时展开不了——这里显式产出并存储。
  let problemAnalysis = null
  {
    problemAnalysis = await agent(
      "## 问题分析（逐问深度分析）\n\n" +
      formatSubQuestions(subQuestions) +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
      (limitationAnalysis ? "## 标准解法局限（供分析参考）\n" + (typeof limitationAnalysis === "string" ? limitationAnalysis.slice(0, 1500) : "") + "\n\n" : "") +
      "## 任务\n" +
      "你是数学建模竞赛审题与建模专家。逐子问题撰写**问题分析**（这是优秀获奖论文的标准第2章，也是后续建模的直接依据）：\n\n" +
      "对每个子问题（用「对于问题N」分段）给出：\n" +
      "1. **机理/业务推理**：这个子问题背后的物理/几何/业务机制是什么？为什么题目这样设问？\n" +
      "2. **难点识别**：该问最大的难点具体在哪？（数据陷阱/机理复杂/求解困难）\n" +
      "3. **建模思路草图**：打算用什么模型解决？先做什么、再做什么？如何逐层递进？若该问依赖前置问题，说明如何复用前置结果。\n" +
      "4. **数据要点**：该问用到哪些数据/附件、需要怎样的预处理？（无附件且无外部数据则说明所需数据应从何处获取；有外部数据则说明如何使用已收集数据）\n\n" +
      "要求：分析要有机理深度（可引用领域知识/文献），不能泛泛而谈；**不写完整公式推导**（那是建模章的事），但要给出清晰的思路路线；中文。\n\n" +
      (externalDataStr ? "## 已收集的外部数据（可用于支撑建模，勿忽略）\n" + externalDataStr + "\n\n" : "") +
      "输出纯文本。" + ctx.saveToFile("04-problem-analysis.txt"),
      { label: "problem-analysis", phase: "建模方案" }
    )
    if (problemAnalysis) {
      log("[Phase 4/8] 问题分析完成 — " + (typeof problemAnalysis === "string" ? problemAnalysis.slice(0, 80).replace(/\n/g, " ") : ""))
    }
  }

  // ── Step 4.0b: 数据探索（EDA）—— 数据题的「数据预处理+探索性分析」整章来源，并驱动建模选择 ──
  // 优秀数据题论文（如2023 C228、2024 C038）都是先数据预处理+探索性分析（分布/趋势/相关性/关联规则/统计检验），
  // 再用数据发现驱动建模选择（如 FP-Growth 发现品类关联→做联合定价；ACF 发现周期→做时序分解）。
  // 当前 pipeline 的建模由"文献+Gap"驱动、数据只在求解阶段被读入——这里是补上"数据驱动"环节。
  let edaReport = null
  if (attachments && attachments.length > 0 || externalDataFiles.length > 0) {
    edaReport = await agent(
      "## 数据探索（EDA）—— 清洗 + 统计检验 + 可视化 + 发现报告\n\n" +
      formatSubQuestions(subQuestions) +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (attachments && attachments.length > 0 ? "## 附件文件（必须读取处理）\n" + attachments.map((a, ai) => (ai + 1) + ". `" + a + "`").join("\n") + "\n\n" : "") +
      (externalDataStr ? "## 外部数据文件（自行收集，必须读取处理）\n" + externalDataStr + "\n\n" : "") +
      "## 任务（优秀数据题获奖论文的标配：先数据预处理，再探索性分析，让数据驱动建模）\n\n" +
      "### 第1步 数据预处理（运行 Python 实际操作）\n" +
      "1. 读取所有附件，检查 shape/缺失/类型/重复\n" +
      "2. 清洗：缺失值处理（删除/插补并记录数量）、异常值处理（3σ 或业务规则，如利润率>2、负销量、量程外读数，记录剔除数量）、无关数据剔除（记录规则与数量）、单位/口径统一、多表关联（自然连接）与聚合规则（如按日/周聚合的销量加权公式）\n" +
      "3. 每步清洗都要输出：处理规则 + 处理前后数量对比\n\n" +
      "### 第2步 探索性统计分析（运行 Python）\n" +
      "针对题目目标做探索：\n" +
      "1. 分布规律：总值/分类别/分单品的量级与占比（生成占比图/条形图）\n" +
      "2. 时间规律：时序图观察趋势；ACF 自相关检验周期性；必要时时间序列分解（趋势/季节/残差）\n" +
      "3. 关系规律：Spearman/偏相关分析（控制总量影响）、分组对比；适合时做关联规则（FP-Growth/卡方/Fisher 精确检验）\n" +
      "4. 统计检验：给出检验方法、统计量、p 值、样本量（如 Fisher 精确检验、t 检验、卡方检验）\n" +
      "⚠️ 使用库函数（scipy.stats / statsmodels / mlxtend），禁止手写统计公式\n\n" +
      "### 第3步 生成 EDA 图表\n" +
      "图表保存到 `" + figuresDir + "/`，命名 `fig_eda_<内容描述>.png`（如 fig_eda_各类占比.png、fig_eda_总销量时序与ACF.png、fig_eda_相关热力图.png）。CJK 字体配置与命名规范同求解阶段。每个图要能回答一个数据问题。\n\n" +
      "### 第4步 输出《数据发现报告》（Structured output）\n" +
      "1. datasetFacts: 各数据集事实（行数、时间范围、缺失/异常/剔除数量）\n" +
      "2. cleaningDecisions: 清洗决策列表（{step, rule, removedCount, rationale}）\n" +
      "3. findings: 探索发现列表（{finding, method, evidence(实际数字/统计量/p值), implicationForModeling(对后续建模的含义——最重要)}），至少 3 条\n" +
      "4. recommendedModelingDirections: 基于数据发现推荐的建模方向（EDA 如何驱动模型选择）\n\n" +
      "**必须实际运行代码并报告真实结果**，禁止只写不跑。\n\nStructured output only." + ctx.saveToFile("04-eda-report.json"),
      { label: "eda-explore", phase: "建模方案",
        schema: { type: "object", required: ["datasetFacts", "cleaningDecisions", "findings", "recommendedModelingDirections"], properties: {
          datasetFacts: { type: "array", items: { type: "object", properties: { dataset: { type: "string" }, facts: { type: "string" } } } },
          cleaningDecisions: { type: "array", items: { type: "object", properties: { step: { type: "string" }, rule: { type: "string" }, removedCount: { type: "string" }, rationale: { type: "string" } } } },
          findings: { type: "array", items: { type: "object", properties: { finding: { type: "string" }, method: { type: "string" }, evidence: { type: "string" }, implicationForModeling: { type: "string" } } } },
          recommendedModelingDirections: { type: "array", items: { type: "string" } },
        } } }
    )
    if (edaReport) {
      log("[Phase 4/8] EDA 数据探索完成 — " + (edaReport.findings?.length || 0) + " 条发现")
    }
  }

  // 将问题分析 + EDA 发现注入后续建模上下文（gap 分析 / 提案 / 综合）
  let directionContext2 = directionContext
  if (problemAnalysis) {
    directionContext2 += "\n\n## 问题分析（逐问深度分析）\n" + (typeof problemAnalysis === "string" ? problemAnalysis : JSON.stringify(problemAnalysis))
  }
  if (edaReport) {
    directionContext2 += "\n\n## 数据探索发现（EDA）\n" + JSON.stringify(edaReport, null, 2).slice(0, 5000)
  }

  // ── Step 4.1: Gap analysis —— 总是运行，将局限转化为可操作的切入点 ──
  let gapContext = directionContext2
  let gapAnalysis = null
  {
    const gapInput = limitationAnalysis
      ? (typeof limitationAnalysis === "string" ? limitationAnalysis : JSON.stringify(limitationAnalysis))
      : "## 基于题目分析推断的潜在局限\n" + JSON.stringify(chosenAnalysis?.keyChallenges || [], null, 2) +
        "\n\n（文献调研未找到足够参考资料，以下局限分析基于题目本身的关键挑战推断。求解和验证阶段应特别关注这些方向。）"

    gapAnalysis = await agent(
      "## 创新机会分析 (Gap Analysis)\n\n" +
      formatSubQuestions(subQuestions) +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
      "## 标准解法局限\n" + gapInput + "\n\n" +
      "## 文献模型参考\n" + JSON.stringify(allModels.slice(0, 8), null, 2) + "\n\n" +
      "## 任务\n" +
      "将上述局限转化为**具体可操作的创新切入点**。每个切入点必须包含：\n" +
      "- 在哪个环节改进？（建模/求解/后处理/数据预处理？）\n" +
      "- 用什么替代什么？（具体技术路径，如「用 P-spline 替代三次多项式解决 Runge 振荡」）\n" +
      "- 预期提升是什么？（精度/效率/稳健性的哪个指标？）\n\n" +
      "**排序规则（优先级从高到低）**：\n" +
      "1. 正确性/可行性第一：核心假设是否有文献支撑？无先例的全新框架 → 高风险\n" +
      "2. 简洁性第二：能用更简单方法达到相近效果吗？简单方案优先\n" +
      "3. 创新性第三：只有正确性和简洁性满足时才加分，不要为了创新而创新\n\n" +
      "输出 3-5 个具体创新切入点，按以上优先级排序。" +
      (limitationAnalysis ? "" : "\n\n⚠️ 文献不足，请基于题目本身的 keyChallenges 和你的领域知识推断合理的局限和改进方向。") +
      "\n\n纯文本输出。" + ctx.saveToFile("04-gap-analysis.txt"),
      { label: "gap-analysis", phase: "建模方案" }
    )
    if (gapAnalysis) {
      gapContext = directionContext + "\n\n## 创新机会分析 (Gap Analysis)\n" + (typeof gapAnalysis === "string" ? gapAnalysis : "")
      log("Gap分析: " + (typeof gapAnalysis === "string" ? gapAnalysis.slice(0, 80).replace(/\n/g, " ") : "..."))
    }
  }

  // ── Step 4.2: 单一建模方案 agent（三维自查内化 + 必要性测试）──
  // 旧版 3 角度并行提案+综合：3-4 个 agent 产 3 份高度重叠的完整方案，上下文大量重复。
  // 新版 1 个 agent 直接产出完整方案（gapContext 已含 问题分析 + EDA 数据发现），评审团不变。
  let finalModel = await agent(
    "## 建模方案设计（完整建模路线）\n\n" +
    formatSubQuestions(subQuestions) +
    "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
    "## 创新机会（Gap 分析，含问题分析与 EDA 数据发现）\n" + gapContext + "\n\n" +
    (allModels && allModels.length > 0 ? "## 文献模型参考\n" + JSON.stringify(allModels.slice(0, 8), null, 2) + "\n\n" : "") +
    (limitationAnalysis ? "## 标准解法局限\n" + (typeof limitationAnalysis === "string" ? limitationAnalysis : "") + "\n\n" : "") +
    "## 设计要求（三维自查，最终只产出一个完整方案）\n" +
    "1. **方法维度**：从方法层面改进标准流程中的关键步骤——能加一项修正解决的就不要替换整个方法；若标准方法已够好，就是「选标准方法+解释为什么不需要改」——这不叫没有创新，这叫正确。\n" +
    "2. **模型维度**：选择对这个具体问题最贴切的数学框架（正确性>简洁性>新颖性）。每个假设必须有文献或常识支撑，超过 1 个无支撑假设 → 方案不可行。\n" +
    "3. **求解维度**：优先成熟算法库（scipy/numpy/sklearn）；只在标准方法不适用时才设计新算法，并给出复杂度分析。若改进算法与标准算法结果差异 < " + threshPct + "%，改用标准算法——复杂度更低、更可靠，评委不会因此扣分。\n\n" +
    "## ⚠️ 硬性要求（正确性第一，创新是锦上添花）\n" +
    "1. **必要性测试**：如果去掉「创新」改用该领域最标准的方法，核心结果会差多少？" + NOT_SIG + "，降级为辅助或不采用。" + SIG_RANGE + "，不作为主创新叙事。" + CORE_INNOV + "。\n" +
    "2. **假设自检**：超过 1 个未经文献/常识支撑的假设 → 不可行。\n" +
    "3. **可验证性**：你的改进能在 Phase 5-6 用数据（baseline 对比）量化证明吗？不能 → 不可作为主创新。\n" +
    "4. 创新必须解决 gap analysis 中发现的具体局限，不能凭空创造。\n" +
    (subQuestions && subQuestions.length > 0 ? "5. **子问题全覆盖**：为每个子问题设计完整方案；有依赖的子问题明确基于前序输出。\n" : "") +
    "6. **方案叙事设计**：如有改进点，附在 approach 字段末尾（用 `\\n\\n【方案亮点】` 分隔）：解决了哪个具体局限、改进效果如何、如何在论文中展开。若所有候选改进都不过必要性测试 → 诚实地写「采用标准方法」并解释为何它对本题已足够好——这不丢分，硬贴创新才丢分。\n\n" +
    "⚠️ 这个方案会立即接受 4 人评审团严格审查——数学家(数学正确性，否决权)+工程师(可实现性，否决权)+领域专家+魔鬼代言人。确保经得起推敲。\n\n" +
    "输出一个完整的、可实现的建模方案（涵盖所有子问题）。Structured output only." + ctx.saveToFile("04-final-model.json"),
    { label: "model-design", schema: MODEL_PROPOSAL_SCHEMA }
  )
  const innovationProposals = finalModel ? [finalModel] : []
  if (!finalModel) {
    return { error: "建模方案设计失败——agent 未返回结果。" }
  }
  log("初始方案: " + (finalModel.approach || "").slice(0, 60))

  // ── Critique loop ──
  let earlyJudgeReview = null
  const result = await critiqueLoop(finalModel, { chosenAnalysis, limitationAnalysis }, ctx, {
    personas: CRITIQUE_PERSONAS, maxRounds: MAX_CRITIQUE_ROUNDS,
    label: "critique", phaseName: "建模方案", savePrefix: "04",
  })
  finalModel = result.finalModel
  earlyJudgeReview = result.judgeReview

  // ── Phase 4.5: 模型适配性预检 —— 在投入大量 agent 求解前验证模型是否适合这道题 ──
  const fitnessCheck = await agent(
    "## 模型适配性预检\n\n" +
    "你是数学建模竞赛资深评委，在不运行代码的情况下快速判断建模方案是否适合这道题。\n\n" +
    formatSubQuestions(subQuestions) +
    (subQuestions && subQuestions.length > 0 ? "请分别评估每个子问题的模型适配性，逐问打分。\n\n" : "") +
    "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
    "## 建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 6000) + "\n\n" +
    (limitationAnalysis ? "## 标准解法局限\n" + (typeof limitationAnalysis === "string" ? limitationAnalysis.slice(0, 1500) : "") + "\n\n" : "") +
    "## 评估维度（每个 0-3 分）\n" +
    "1. **问题-方法匹配度**: 这个数学框架是处理此类问题的标准/合理选择吗？\n" +
    "2. **假设支撑度**: 每个假设有文献或常识支撑吗？有无超过 1 个无支撑假设？\n" +
    "3. **求解可行性**: 算法复杂度可控吗？能在三天内用 Python 实现吗？\n" +
    "4. **改进合理性**: 方案中的改进点是否解决真实局限？必要性能通过吗？\n\n" +
    "输出 JSON：{\"scores\":{\"methodFit\":0-3,\"assumptions\":0-3,\"feasibility\":0-3,\"innovation\":0-3},\"totalScore\":0-12,\"verdict\":\"GO\"|\"WARN\"|\"STOP\",\"riskSummary\":\"一句话总结最大风险\"}\n\n" +
    "GO = 总分≥9，方案可靠 → 进入求解\n" +
    "WARN = 总分6-8，有风险但可尝试 → 进入求解但标记 warning\n" +
    "STOP = 总分<6，方案有结构性问题 → 建议打回 Phase 4 重新设计\n\n" +
    "Structured output only.",
    { label: "fitness-check", phase: "建模方案",
      schema: { type: "object", required: ["scores", "totalScore", "verdict"], properties: {
        scores: { type: "object", properties: { methodFit: { type: "integer" }, assumptions: { type: "integer" }, feasibility: { type: "integer" }, innovation: { type: "integer" } } },
        totalScore: { type: "integer" }, verdict: { enum: ["GO", "WARN", "STOP"] }, riskSummary: { type: "string" },
      } }
    }
  )
  if (fitnessCheck) {
    log("模型适配性: " + fitnessCheck.totalScore + "/12 — " + fitnessCheck.verdict + " | " + (fitnessCheck.riskSummary || ""))
    if (fitnessCheck.verdict === "STOP") {
      log("⚠️ 模型适配性检查: STOP — 方案有结构性问题，本次运行终止。")
      return { error: "模型适配性预检 STOP (score " + fitnessCheck.totalScore + "/12)：方案有结构性问题，本次运行终止，不进入求解阶段。建议：换一个建模方向重新设计后重跑；或用 args.innovationStrictness='loose' 放宽创新阈值后重试；不要用 resumeFrom 续跑（模型未建立，无 checkpoint 可用）。" }
    } else if (fitnessCheck.verdict === "WARN") {
      log("⚠️ 模型适配性检查: WARN — 方案有风险但可尝试求解")
    }
  }

  log("[Phase 4/8] 建模方案完成 ✓ — " + innovationProposals.length + " 个建模方案, 适配性评分 " + (fitnessCheck?.totalScore ?? '?') + "/12")

  // Store results in ctx
  ctx.gapAnalysis = gapAnalysis
  ctx.innovationProposals = innovationProposals
  ctx.finalModel = finalModel
  ctx.earlyJudgeReview = earlyJudgeReview
  ctx.fitnessCheck = fitnessCheck
  ctx.problemAnalysis = problemAnalysis
  ctx.edaReport = edaReport

  return { finalModel, innovationProposals, gapAnalysis, fitnessCheck, earlyJudgeReview, problemAnalysis, edaReport }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: lib/phase5-6-solve-verify.js
// ═══════════════════════════════════════════════════════════════

// ═══ Phase 5 ⇄ 6 Loop: 求解 → 验证 → 修 → 再验 ═══
// Depends on: agent(), parallel(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile, ctx.formatSubQuestions, ctx.subQuestions


async function phase5_6_solve_verify(ctx) {
  const { cfg, chosenAnalysis, finalModel, allModels, allClaims, limitationAnalysis,
          outputDir, codeDir, figuresDir, attachments, subQuestions, edaReport } = ctx
  const earlyJudgeReview = ctx.earlyJudgeReview || null

  // EDA 报告：文档为唯一权威，求解/验证 agent 直接 Read 完整报告（不另塞摘要）
  const edaCtx = edaReport
    ? "\n\n## ⚠️ EDA 数据发现（数据题）\n" +
      "完整数据发现报告已保存到 `" + outputDir + "/intermediates/04-eda-report.json`，**开写前必须 `Read` 它**（数据清洗规则/聚合口径/统计检验/数据事实的唯一权威，你的求解必须与其一致）。"
    : ""

  // 外部数据（Phase 4.0a 自行收集）：求解阶段同样需要读取
  const extData = ctx.externalData || null
  const extFiles = (extData && extData.sources || []).filter(s => s.status === "OK" && s.filePath).map(s => s.filePath)
  const extCtx = extFiles.length > 0
    ? "\n\n## 外部数据文件（自行收集，必须读取使用；来源见 `" + outputDir + "/intermediates/04-data-collection.json`）\n" +
      extData.sources.filter(s => s.status === "OK").map((s, i) => (i + 1) + ". `" + s.filePath + "` （来源: " + (s.sourceUrl || "?") + "，获取日期: " + (s.fetchedAt || "?") + "）").join("\n") + "\n\n"
    : ""

  log("[Phase 5-6/8] 求解⇄验证开始 — 预计 15-25 分钟")

  let iteration = 0, dry = 0, prevNewCount = Infinity, worseningStreak = 0,
      currentSolution = null, baselineResult = null, needsBaseline = true
  let allIssues = [], refutedIssues = [], iterationLog = [],
      allAdversarialFindings = [], allRethinkResults = []
  let redesignHistory = []
  let redesignCount = 0
  let overallRobustness = "acceptable"
  const MAX_REDESIGNS = 2

  while (dry < cfg.dryThreshold && iteration < cfg.maxIterations) {
    iteration++
    const iterPhase = "求解-第" + iteration + "轮"
    phase(iterPhase)

    // ── Solve ──
    const prevIssues = allIssues.filter(i => i.severity === "critical" || i.severity === "moderate")
    const fixContext = prevIssues.length > 0
      ? "\n\n## ⚠️ 上轮验证问题 (必须修复)\n" + JSON.stringify(prevIssues, null, 2) : ""

    const algoAgent = await agent(
      (iteration === 1
        ? "## 算法设计\n\n" +
          formatSubQuestions(subQuestions) +
          (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
          (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
          edaCtx + extCtx + "\n\n" +
          "## 建模方案\n" + JSON.stringify(finalModel, null, 2) + "\n\n" +
          (attachments.length > 0 ? "## 附件文件\n" + attachments.map((a, ai) => (ai + 1) + ". `" + a + "`").join("\n") + "\n\n**先读取附件确认数据格式**，然后设计算法。\n\n" : "") +
          "## 任务\n" +
          "设计完整求解算法，**给出可直接翻译为 Python 代码的实现细节**。\n" +
          "1. 每个子问题的输入/输出明确定义\n" +
          "2. 关键公式写清楚计算顺序（不是伪代码概述，是「第1步: np.linalg.solve(A,b)，其中A=..., b=...」这种级别）\n" +
          "3. 数值方法的具体参数（迭代次数、步长、收敛判据等）\n" +
          "4. 附件数据处理流程（pandas读取→清洗→输入模型）\n" +
          "5. 可视化输出设计\n\n" +
          "**禁止说「可以用 xxx 方法」——直接选定一个并给出实现细节。**" +
          (earlyJudgeReview ? "\n\n## 评委反馈\n" + (typeof earlyJudgeReview === "string" ? earlyJudgeReview.slice(0, 2000) : "") + "\n\n算法设计时注意评委点出的风险点。" : "")
        : "## 算法改进 (第" + iteration + "轮)\n\n" +
          formatSubQuestions(subQuestions) +
          "## 方案\n" + JSON.stringify(finalModel, null, 2) + "\n\n## 上次结果\n" + JSON.stringify(currentSolution?.results || {}, null, 2)
      ) + fixContext + "\n\n" +
      "## 任务\n" +
      (iteration === 1
        ? ""
        : "针对验证发现的问题修改算法。不要重新设计——只修改出问题的部分。给出修改后的具体实现细节。") + "\n\n输出纯文本（不要 structured output）。",
      { label: "algo-r" + iteration, phase: iterPhase }
    )
    if (!algoAgent) { log("算法设计失败"); break }

    // Inject domain-matched code template
    const templateMatch = getTemplateForDomain(chosenAnalysis?.domain || "")
    const codeTemplateBlock = templateMatch
      ? "\n## ⚠️ 代码骨架模板（" + templateMatch.key + "）\n直接复制以下骨架到你的 .py 文件，替换占位符即可。不要改变 import 选择和 metrics 输出格式。\n\n### skeleton\n```python\n" + templateMatch.template.skeleton + "\n```\n\n### 标准化指标输出（追加到脚本末尾）\n```python\n" + templateMatch.template.metricsOutput + "\n```\n"
      : ""

    let solution = await agent(
      "## 代码实现与执行 (第" + iteration + "轮)\n\n" +
      (SKILL_DOCS ? "> ⚠️ 规范真源：完整图表/数值规范在 `" + SKILL_DOCS + "` 的「§二 图表生成规范」（CJK 字体/单位/附录浮动），需要完整要求时先 `Read` 对应章节；本 prompt 已列出关键配置。\n\n" : "") +
      formatSubQuestions(subQuestions) +
      // 迭代 2+ 不再重发全文/数据画像（上轮已给），只带算法变更+待修问题，省大量 token
      (iteration === 1 && chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      (iteration === 1 && chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      edaCtx + "\n\n" +
      "## 算法设计\n" + algoAgent + "\n\n" +
      "## 建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, iteration === 1 ? 24000 : 8000) + "\n\n" +
      (fixContext ? "## ⚠️ 本轮必须修复的问题\n" + fixContext + "\n\n" : "") +
      (attachments.length > 0 ? "## 附件文件（必须读取处理）\n" + attachments.map((a,ai) => (ai+1) + ". `" + a + "`").join("\n") + "\n\n" : "") +
      (extCtx ? extCtx + "\n" : "") +
      (codeTemplateBlock ? codeTemplateBlock + "\n" : "") +
      "## ⚠️ 强制要求：你必须实际运行代码并报告真实结果，不允许只写代码不运行。\n\n" +
      "## ⚠️ 创新 vs 基线对比要求（dual-path）\n" +
      "在一个 Python 文件中同时实现创新方法和标准基线（baseline）方法：\n" +
      "1. 使用一个 `METHOD` 变量切换（`METHOD = 'innovative'` 或 `METHOD = 'baseline'`），或用 `--method baseline` 命令行参数切换\n" +
      "2. 创新方法和基线方法必须共用完全相同的：数据加载、预处理、后处理、评价指标计算、输出格式\n" +
      "3. 基线方法使用该领域最经典/最标准的方法（教科书级别）——不要用任何 Phase 4 中的创新\n" +
      "4. 在脚本末尾、METHOD 输出之前，打印对比表格到 stdout：\n" +
      "   ```\n" +
      "   | 指标 | 创新方法 | 标准方法 | 提升 |\n" +
      "   |------|---------|---------|------|\n" +
      "   | RMSE | 0.023   | 0.047   | 51.1% ↓ |\n" +
      "   ```\n" +
      "   提升为负值时标注 ↓（越小越好），正值标注 ↑（越大越好）\n\n" +
      "## ⚠️ 数值自检清单（必须逐条落实）\n" +
      "1. **优先使用权威库函数**：使用 sklearn、statsmodels、scipy 等库函数，禁止手写 R²/AIC/OLS 等统计公式（除非库函数不存在对应实现）\n" +
      "2. **线性系统条件数**：如果涉及线性方程组求解，必须打印 condition number：`print('cond(A)=', np.linalg.cond(A))`\n" +
      "3. **回归分析诊断**：打印残差范数（`np.linalg.norm(residuals)`）和 R²\n" +
      "4. **物理合理性 assert**：对每个关键输出做 assert（如 `assert 0 <= r2 <= 1.0`, `assert thickness > 0`）\n" +
      "5. **量纲注释**：代码中每步关键计算标注物理量纲（`# [m]`, `# [kg/m^3]`）\n" +
      "6. **中间值审计**：`results.keyValues` 中包含关键中间值（如 SS_res、SS_tot、logL、condition number）以便审计\n\n" +
      "## 执行步骤\n" +
      "1. `mkdir -p " + outputDir + "` 创建输出目录\n" +
      "2. **matplotlib 中文字体配置**（生成任何图表之前必须先做）：\n" +
      "   先检测系统可用中文字体：\n" +
      "   ```bash\n" +
      "   python3 -c \"\n" +
      "   import matplotlib.font_manager as fm\n" +
      "   fonts = [f.name for f in fm.fontManager.ttflist if any(k in f.name.lower() for k in ['hei','song','ming','kai','cjk','noto','wenquan','fang','droid']))]\n" +
      "   print('Available CJK fonts:', list(set(fonts)) if fonts else 'NONE')\n" +
      "   \"\n" +
      "   ```\n" +
      "   然后在所有 Python 绘图脚本开头写入（用上面检测到的字体名替换占位符）：\n" +
      "   ```python\n" +
      "   import matplotlib\n" +
      "   matplotlib.use('Agg')\n" +
      "   import matplotlib.pyplot as plt\n" +
      "   # ⚠️ 关键：必须同时设置 font.sans-serif（字体列表+回退）和 font.family\n" +
      "   plt.rcParams['font.sans-serif'] = ['Noto Sans CJK SC', 'DejaVu Sans', 'Noto Sans']\n" +
      "   plt.rcParams['font.family'] = 'sans-serif'         # 必须设置，否则 font.sans-serif 无效\n" +
      "   plt.rcParams['axes.unicode_minus'] = False         # 修复负号显示\n" +
      "   plt.rcParams['mathtext.default'] = 'regular'       # LaTeX math 用 regular 字体\n" +
      "   print('CJK font configured: Noto Sans CJK SC + DejaVu Sans fallback')\n" +
      "   ```\n" +
      "   ⚠️ **常见错误（曾导致图表中文全部变成方框）**：\n" +
      "   - 只设 `font.sans-serif = [font]` 而不设 `font.family = 'sans-serif'` → 字体不生效\n" +
      "   - 用 ASCII 文本 `'test'` 测试字体 → 不触发 CJK 字形检测，误以为配置成功\n" +
      "   - 用 `warnings.filterwarnings('ignore')` 吞掉 Glyph 警告 → 问题隐藏\n" +
      "   - 测试方法：生成含中文标签的图 → 检查 stderr 无 `Glyph.*missing from font` 警告\n" +
      "3. **图表标签规范**（避免 Unicode 上下标渲染为方框）：\n" +
      "   - ✅ 单位用 LaTeX math：`ax.set_xlabel('Wavenumber (cm$^{-1}$)')`\n" +
      "   - ❌ 禁止 Unicode 上下标：不要写 `'波数 (cm⁻¹)'`（⁻ 是 U+207B），不要写 `'A₂/A₁'`（₂ 是 U+2082）\n" +
      "   - ✅ 下标用 LaTeX math：`'A$_2$/A$_1$ (%)'`\n" +
      "   - 原因：Noto Sans CJK SC 等中文字体不含 U+207B, U+00B9, U+2081-2089 等 Unicode 上下标字形\n" +
      "4. 将所有 Python 代码写入 `" + codeDir + "/solution_v" + iteration + ".py`\n" +
      "5. **如果有附件数据**，先用 `python3 -c \"import pandas; print(pandas.read_excel('附件路径').head())\"` 检查数据结构\n" +
      "5. 用 `run_in_background: true` 在后台运行 Python：\n" +
      "   ```bash\n" +
      "   cd " + outputDir + " && python3 code/solution_v" + iteration + ".py > logs/solution_v" + iteration + ".log 2>&1\n" +
      "   ```\n" +
      "   然后每隔 10 秒检查 `logs/solution_v" + iteration + ".log` 是否完成，最长等待 15 分钟。\n" +
      "   完成后读取日志文件获取结果。如果 15 分钟后仍未完成，报告已产生的文件和部分结果。\n" +
      "6. **如果运行报错**：读取错误信息 → 修改代码 → 重新运行，直到跑通为止\n" +
      "7. 对题目中的**每一个子问题**分别运行并记录结果\n" +
      "8. 生成关键图表并保存到 `" + figuresDir + "/`，命名规范：\n" +
      "   - 格式：`fig_{子问题ID}_{图表具体做了什么}.png`\n" +
      "   - 子问题ID：Q1, Q2, Q3...（对应题目中的问题编号），跨问题综合图用 `fig_cross_`\n" +
      "   - ⚠️ 文件名必须描述图表的具体内容，让人不看图就知道图里有什么\n" +
      "   - 好的命名：「fig_Q2_sic_detrended_oscillation_vs_wavenumber.png」——知道是去趋势振荡信号随波数变化\n" +
      "   - 好的命名：「fig_Q2_thickness_comparison_three_methods.png」——知道是三种方法的厚度对比\n" +
      "   - 差的命名：「fig_Q2_result.png」「fig_Q2_plot1.png」——不知道图里是什么\n" +
      "   - 差的命名：「fig_Q2_fft.png」——太简略，看不出是原始FFT还是去趋势后的FFT，有没有标注峰值\n" +
      "   - 命名即 caption：论文中 `\\includegraphics{fig_Q2_sic_detrended_oscillation_vs_wavenumber}` → caption 写「去趋势振荡信号」\n\n" +
      "## 报告要求\n" +
      "- results.summary: 每个子问题的**具体数值结果**（不能写「待实现」或「见代码」）\n" +
      "- results.keyValues: 关键变量的数值列表\n" +
      "- testPassed: 所有子问题代码均已跑通 → true\n" +
      "- concerns: 运行中遇到的任何问题\n\n" +
      "**如果你只写了代码没有运行，这个任务就是失败的。**\n\n" +
      "Structured output only.",
      { label: "impl-r" + iteration, phase: iterPhase, schema: SOLUTION_SCHEMA }
    )
    if (!solution) { log("代码实现失败"); break }
    currentSolution = solution

    // Hard check: agent must have actually run the code
    if (!solution.testPassed || !solution.results || !solution.results.summary || solution.results.summary.includes("待实现")) {
      log("⚠️ agent 未实际运行代码，强制重试...")
      const forcedRetry = await agent(
        "## ⚠️ 强制重试：你必须运行代码\n\n" +
        "上次你返回的结果表明你没有实际运行 Python 代码。\n" +
        "现在重新执行以下步骤，**每一步都必须完成**：\n\n" +
        "1. 检查 `" + codeDir + "/solution_v" + iteration + ".py` 是否存在？如果不存在，重新写入完整代码\n" +
        "2. 用 `run_in_background: true` 在后台运行：`cd " + outputDir + " && python3 code/solution_v" + iteration + ".py > logs/solution_v" + iteration + "_retry.log 2>&1`，每 10 秒检查，最长等 15 分钟。\n" +
        "3. 如果报错：读错误 → 修代码 → 重跑，直到跑通\n" +
        "4. 复制终端中的**实际输出**到 results.summary\n" +
        "5. testPassed 只有在你亲眼看到代码跑通时才设为 true\n\n" +
        "## 上次返回（无效）\n" + JSON.stringify(solution, null, 2).slice(0, 3000) + "\n\n" +
        "Structured output only.",
        { label: "impl-retry-r" + iteration, phase: iterPhase, schema: SOLUTION_SCHEMA }
      )
      if (forcedRetry) {
        currentSolution = forcedRetry
        solution = forcedRetry
        log("强制重试完成")
      }
    }

    log("第" + iteration + "轮求解" + (!currentSolution.testPassed ? "(运行错误)" : "完成"))

    // ── Baseline comparison (after first successful solve, or after redesign) ──
    if (needsBaseline && currentSolution && currentSolution.testPassed !== false) {
      if (ctx.skipBaseline) {
        log("[skipPhases] baseline 对比已跳过 — 复用已有基线结果")
        needsBaseline = false
      } else {
        needsBaseline = false
        const baselineAgent = await agent(
          "## 标准基线求解（单脚本 dual-path）\n\n" +
          formatSubQuestions(subQuestions) +
          (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
          (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "") +
          edaCtx + extCtx + "\n\n" +
          "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
          "## 任务\n" +
          "运行已有求解脚本的基线模式（`METHOD=baseline`）以获取标准方法结果。\n" +
          "注意：创新方案和基线已在同一个脚本中实现，共用完全相同的数据加载/预处理/后处理/评价流程——对比公平性有保障。\n\n" +
          "1. 检查 `" + codeDir + "/solution_v" + iteration + ".py` 是否存在\n" +
          "2. 运行基线模式：\n" +
          "   ```bash\n" +
          "   cd " + outputDir + " && METHOD=baseline python3 " + codeDir + "/solution_v" + iteration + ".py > logs/baseline_v" + iteration + ".log 2>&1\n" +
          "   ```\n" +
          "   用 `run_in_background: true` 后台跑，每 10 秒检查日志，最长等 15 分钟\n" +
          "3. 读取日志，提取基线方法的指标数值（脚本应已输出包含创新和基线对比的表格）\n" +
          "4. **如果脚本中尚无双实现**：读取脚本内容 → 在已有代码中添加基线方法实现（遵循 dual-path 模式：METHOD 切换 + 共享数据加载/预处理/评价）→ 重新运行\n\n" +
          "输出：标准方法的结果描述 + 核心指标数值。纯文本。" + ctx.saveToFile("05-baseline-result.txt"),
          { label: "baseline", phase: "求解-第1轮" }
        )

        if (baselineAgent) {
          const comparison = await agent(
            "## 创新 vs 标准基线 量化对比\n\n" +
            "## 创新方案结果\n" + JSON.stringify(currentSolution.results, null, 2) + "\n\n" +
            "## 标准基线结果\n" + (typeof baselineAgent === "string" ? baselineAgent.slice(0, 5000) : JSON.stringify(baselineAgent, null, 2)) + "\n\n" +
            "## 任务\n" +
            "量化对比两种方法。这是论文最有说服力的一段——用数据说话。\n\n" +
            "- metrics: 至少3个对比维度（如精度、效率、稳定性）\n" +
            "- 每个 metric 给出 baseline 值、improved 值、improvement 百分比\n" +
            "- 每个 metric 标注 `isLowerIsBetter`：true = 该指标越小越好（如误差、耗时），false = 越大越好（如精度、R²）\n" +
            "- summary: 一句话总结创新带来的提升（用于摘要）\n" +
            "- significance: 提升是否显著\n" +
            "- weaknessExposed: 对比暴露了创新方案的什么弱点？（诚实，这也应该在论文中讨论）\n\n" +
            "Structured output only." + ctx.saveToFile("05-baseline-comparison.json"),
            { label: "baseline-compare", phase: "求解-第1轮", schema: BASELINE_COMPARISON_SCHEMA }
          )
          if (comparison) {
            baselineResult = comparison
            log("创新 vs 基线: " + (comparison.summary || "").slice(0, 80))
          }
        }
      }
    }

    // ── Verify ──
    const dctx = getDomainExpertise(chosenAnalysis?.domain) || "\n\n## 领域专家视角\n资深工程师，关注计算结果的工程合理性。"
    const actx = (attachments.length > 0 || extFiles.length > 0)
      ? ("\n\n## 附件/外部数据验证\n" +
         (attachments.length > 0 ? attachments.map((a,ai) => (ai+1)+". `"+a+"`").join("\n") + "\n" : "") +
         (extFiles.length > 0 ? extData.sources.filter(s => s.status === "OK").map((s,i) => (i+1)+". `"+s.filePath+"` (来源: "+s.sourceUrl+")").join("\n") + "\n" : "") +
         "用 Python/pandas 读取数据，对比求解输出与参考值。差异>10% → critical severity。") : ""
    const edaCtxVerifiers = edaReport
      ? "\n\n## EDA 数据发现（验证时与其交叉核验）\n" +
        "完整数据发现报告已保存到 `" + outputDir + "/intermediates/04-eda-report.json`，**核验前必须 `Read` 它**。"
      : ""
    const problemCtx = ""
      + formatSubQuestions(subQuestions)
      + (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "")
      + (chosenAnalysis._dataProfile ? "## 附件数据画像\n" + PROBLEM_READ_HINT + "\n\n" : "")
      + edaCtxVerifiers + "\n\n"
      + "## 题目结构化分析\n" + JSON.stringify(chosenAnalysis, null, 2)
    const verifiers = [
      {
        dimension: "sensitivity",
        prompt: "## 灵敏度分析\n\n" + problemCtx + "\n\n## 模型\n" + JSON.stringify(finalModel, null, 2) + "\n\n## 求解结果\n" + JSON.stringify(solution.results || {}, null, 2) + "\n\n" +
          "## 已有数据文件（先 `ls " + outputDir + "/data/` 和 `ls " + outputDir + "/figures/` 检查，再决定要不要补跑）\n" +
          "求解阶段可能已生成数据文件和图表。先列出目录内容，如果有数据文件则读取分析；如果没有或不足，才补跑轻量脚本。\n\n" +
          "## 任务\n" +
          "1. **先读已有数据**分析关键参数 (±10%/±20%) 扰动对结果的影响，识别最敏感参数\n" +
          "2. **仅当已有数据不足时**，写一个小型 Python 脚本（≤50 行）做针对性测试——不允许重跑完整求解 pipeline\n" +
          "3. 如果写脚本跑代码：轻量脚本用 `timeout 300 python3 <script>.py 2>&1`；如果预计超 5 分钟，用 `run_in_background: true` 后台跑+每10秒检查日志，最长等 15 分钟。超时后基于已有数据报告，不重试。\n" +
          "每个发现标注 severity。\n\nStructured output only." + dctx + actx,
      },
      {
        dimension: "edge_cases",
        prompt: "## 边界条件测试\n\n" + problemCtx + "\n\n## 模型\n" + JSON.stringify(finalModel, null, 2) + "\n\n## 结果\n" + JSON.stringify(solution.results || {}, null, 2) + "\n\n" +
          "根据题目原文中定义的约束和边界条件，测试极端/边界情况：输入极值、数据缺失、约束边界、不同初始条件。每个发现标注 severity。\n\nStructured output only." + dctx + actx,
      },
      {
        dimension: "adversarial",
        prompt: "## 对抗审查\n\n" + problemCtx + "\n\n## 模型\n" + JSON.stringify(finalModel, null, 2) + "\n\n## 结果\n" + JSON.stringify(solution.results || {}, null, 2) + "\n\n" +
          "对照题目原文，试图找到模型崩溃场景：假设是否成立？是否有更优解？输出物理上合理吗？有没有更简单的 benchmark？每个发现标注 severity。\n\nStructured output only." + dctx + actx,
      },
      ...(attachments.length > 0 || extFiles.length > 0 ? [{
        dimension: "data_validation",
        prompt: "## 硬数据验证\n\n" + problemCtx + "\n\n" +
          "## 附件\n" + attachments.map((a,ai) => (ai+1)+". `"+a+"`").join("\n") + "\n\n" +
          (extCtx ? "## 外部数据文件\n" + extCtx + "\n\n" : "") +
          "**硬数据检查，不依赖主观判断。**\n" +
          "1. 用 Python pandas 读取附件/外部数据 xlsx/csv\n" +
          "2. 运行求解代码，将输出与数据参考值逐项对比\n" +
          "3. 报告数值差异百分比和格式匹配情况\n" +
          "4. 差异>10% → critical severity。差异<5% → minor\n\nStructured output only." + dctx
      }, {
        dimension: "statistical",
        prompt: "## 统计显著性审查\n\n" + problemCtx + "\n\n" +
          "## 模型\n" + JSON.stringify(finalModel, null, 2) + "\n\n## 求解结果\n" + JSON.stringify(solution.results || {}, null, 2) + "\n\n" +
          "## 任务\n" +
          "审查结论的统计显著性（优秀数据题论文的常规武器：统计检验支撑结论）：\n" +
          "1. 声称的差异/提升/规律是否有统计检验支撑（置信区间、p 值、样本量）？\n" +
          "2. 样本量是否足以支撑结论？小样本结论是否被过度外推？\n" +
          "3. 关键估计是否报告了置信区间/不确定性（如最优参数的灵敏度带）？\n" +
          "4. 分类/分组/关联结论是否做过显著性检验（卡方/Fisher/t 检验/相关系数检验）？\n" +
          "5. 时间序列类结论是否做过平稳性/周期性检验（ACF/ADF）？\n" +
          "每个发现标注 severity。\n\nStructured output only." + dctx + actx,
      }] : []),
      {
        dimension: "devils_advocate",
        prompt: "## 魔鬼代言人审查\n\n" +
          "你是这篇**建模方案和求解结果**的竞争对手，要在评委面前证明这套方法和结论不可信。\n" +
          "⚠️ 注意：论文还没写——你审查的是下面的模型设计+数值结果+baseline对比，不是一篇已完成的论文。\n\n" +
          problemCtx + "\n\n" +
          "## 建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 5000) + "\n\n" +
          "## 求解结果\n" + JSON.stringify(solution.results || {}, null, 2).slice(0, 3000) + "\n\n" +
          (baselineResult ? "## Baseline对比\n" + JSON.stringify(baselineResult, null, 2).slice(0, 3000) + "\n\n" : "") +
          "## 审查维度\n" +
          "1. 找到模型最依赖的单个假设——如果它不成立，整个结论崩溃\n" +
          "2. 用更简单的 baseline 方法能否得到类似结果？如果能，复杂模型没带来额外价值\n" +
          "3. 是否存在 cherry-picking（只展示有利数据）？\n" +
          "4. 有更近期方法/数据可以推翻当前结论吗？\n" +
          "5. 数值结果有没有看起来太好的？（too good to be true）\n" +
          "不要客气。每个发现标注 severity。\n\nStructured output only." + ctx.saveToFile("06-devils-advocate.json") + dctx
      },
    ]

    const findings = safeFilter(await parallel(
      verifiers.map(v => () =>
        agent(v.prompt, { label: "verify:" + v.dimension, phase: "验证-第" + iteration + "轮", schema: VERIFICATION_SCHEMA })
      )
    ), "验证-findings")

    // 聚合 modelRobustness：取最差评分作为整体鲁棒性
    const ROBUSTNESS_RANK = { robust: 2, acceptable: 1, fragile: 0 }
    const iterRobustness = findings.length > 0
      ? findings.reduce((worst, f) => {
          const rank = ROBUSTNESS_RANK[f.modelRobustness] ?? 1
          return rank < worst.rank ? { rank, value: f.modelRobustness } : worst
        }, { rank: 2, value: "robust" }).value
      : "acceptable"
    if (iterRobustness !== "robust") {
      log("本轮鲁棒性: " + iterRobustness + " (来自" + findings.length + "个验证维度)")
    }
    if (ROBUSTNESS_RANK[iterRobustness] < ROBUSTNESS_RANK[overallRobustness]) {
      overallRobustness = iterRobustness
    }

    let verifiedFindings = findings.flatMap(f => (f.findings || []).map(fi => ({ ...fi, _dimension: f.dimension })))

    // 魔鬼代言人 findings 跨迭代累积
    const roundAdversarial = verifiedFindings.filter(f => f._dimension === "devils_advocate")
    for (const af of roundAdversarial) {
      if (!allAdversarialFindings.some(ex => ex.issue === af.issue)) {
        allAdversarialFindings.push(af)
      }
    }

    // Voting on findings
    if (verifiedFindings.length > 0) {
      const BATCH_SIZE = 4
      const batches = []
      for (let i = 0; i < verifiedFindings.length; i += BATCH_SIZE) {
        batches.push(verifiedFindings.slice(i, i + BATCH_SIZE))
      }
      const votedFindings = safeFilter(await parallel(
        batches.map((batch, bi) => () =>
          agent(
            "## 批量发现验证 (" + batch.length + " 个发现)\n\n" +
            batch.map((f, fi) => "### 发现 #" + fi + " (index=" + fi + ")\n" + JSON.stringify(f, null, 2)).join("\n\n") + "\n\n" +
            "## 题目\n" + JSON.stringify(chosenAnalysis, null, 2) + "\n\n" +
            "## 任务\n" +
            "对每个发现，判断 refuted=true（误报/不重要）还是 refuted=false（有效问题）。不确定倾向于 false。\n" +
            "输出 JSON 数组，每个元素对应一个发现：{\"index\": 0, \"refuted\": false, \"evidence\": \"...\", \"confidence\": \"high/medium/low\"}\n\n" +
            "Structured output only.",
            { label: "vf-batch-" + (bi + 1), phase: "验证-第" + iteration + "轮",
              schema: { type: "object", required: ["verdicts"], properties: { verdicts: { type: "array", items: { type: "object", required: ["index", "refuted"], properties: { index: { type: "integer" }, refuted: { type: "boolean" }, evidence: { type: "string" }, confidence: { enum: ["high", "medium", "low"] } } } } } } }
          ).then(result => {
            const verdicts = (result && result.verdicts) ? result.verdicts : (Array.isArray(result) ? result : [])
            if (!Array.isArray(verdicts) || verdicts.length === 0) {
              logError(ErrorLevel.WARNING, "验证-第" + iteration + "轮", "投票批次 " + (bi + 1) + " 无有效裁决（投票 agent 失败），本批 " + batch.length + " 条发现标记为未验证（confirmed=null），不计入问题清单")
              return batch.map(f => ({ ...f, confirmed: null, voteSummary: "unverified" }))
            }
            return batch.map((finding, fi) => {
              const v = verdicts.find(v => v && v.index === fi)
              const refuted = v ? v.refuted : false
              return { ...finding, confirmed: !refuted, voteSummary: refuted ? "refuted" : "confirmed", refuteReasons: refuted && v.evidence ? [v.evidence] : [] }
            })
          })
      )), "验证-votedFindings")
      const flatFindings = votedFindings.reduce(function(acc, val) { return acc.concat(val); }, [])
      const refutedThisRound = flatFindings.filter(f => f.confirmed === false)
      for (const f of refutedThisRound) {
        refutedIssues.push({ issue: f.issue, refuteReasons: f.refuteReasons || [] })
      }
      verifiedFindings = flatFindings.filter(f => f.confirmed)
    }

    // Dedup phase 1: 精确字符串匹配
    let newIssues = verifiedFindings.filter(
      f => !allIssues.some(ex => ex.issue === f.issue) && !refutedIssues.some(rf => rf.issue === f.issue)
    )

    // Dedup phase 2: 语义去重
    if (allIssues.length > 5) {
      const dupReport = await agent(
        "## 语义去重\n\n## 已有问题列表 (" + allIssues.length + "个)\n" +
        JSON.stringify(allIssues.map(i => ({ issue: i.issue, severity: i.severity })), null, 2).slice(0, 8000) +
        "\n\n## 本轮新增 (" + newIssues.length + "个)\n" +
        JSON.stringify(newIssues.map(i => ({ issue: i.issue, severity: i.severity })), null, 2) +
        "\n\n## 任务\n" +
        "识别语义重复：不同措辞描述同一底层问题的情况。\n" +
        "输出 JSON：{\"groups\": [[0,5,\"原因\"],[2,7,\"原因\"]]}，每个 group 是应合并为一组的问题索引列表。\n" +
        "只合并真正相同的问题。误解不算重复。",
        { label: "dedup-r" + iteration, phase: "验证-第" + iteration + "轮",
          schema: { type: "object", required: ["groups"], properties: { groups: { type: "array", items: { type: "array", items: { type: "string" } } } } } }
      )
      if (dupReport && Array.isArray(dupReport.groups)) {
        const groups = dupReport.groups
        const mergeCount = groups.length
        const mergedIndices = new Set()
        for (const group of groups) {
          if (Array.isArray(group) && group.length > 1) {
            for (let gi = 1; gi < group.length; gi++) {
              mergedIndices.add(Number(group[gi]))
            }
          }
        }
        if (mergedIndices.size > 0) {
          newIssues = newIssues.filter((_, i) => !mergedIndices.has(i))
          log("语义去重: 合并 " + mergeCount + " 组 → 移除 " + mergedIndices.size + " 条重复")
        }
      }
    }

    // ── 模型反思 checkpoint ──
    const criticalNew = newIssues.filter(f => f.severity === "critical")
    if (criticalNew.length >= (cfg.rethinkThreshold || 3)) {
      log("[Phase 5-6/8] 检测到" + criticalNew.length + "个critical问题(第" + iteration + "轮)，触发模型反思...")
      const rethinkResult = await agent(
        "## 模型反思——审视建模路线\n\n" +
        problemCtx + "\n\n" +
        "## 当前建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 4000) + "\n\n" +
        "## 本轮新确认的 critical 问题 (" + criticalNew.length + "个)\n" +
        criticalNew.map(f => "- [" + f.severity + "] " + f.issue).join("\n") + "\n\n" +
        "## 所有已确认问题 (" + allIssues.length + "个)\n" +
        allIssues.slice(-20).map(f => "- [" + f.severity + "] " + f.issue).join("\n") + "\n\n" +
        "## 任务\n" +
        "判断：这些问题是否指向**建模路线的根本缺陷**（核心假设不成立、数学框架选错、数据不支持方法）？\n\n" +
        "输出 JSON：{\"verdict\": \"FUNDAMENTAL_FLAW\" | \"FIXABLE\", \"flawedAssumptions\": [\"...\"], \"reasoning\": \"...\", \"suggestedRedesign\": \"如果判定 FLAW，简述应改用哪种建模路线\"}\n\n" +
        "FUNDAMENTAL_FLAW = 核心假设/数学框架需要换，不是调参能解决的\n" +
        "FIXABLE = 问题在实现层面，修代码/改参数可以搞定\n\n" +
        "Structured output only.",
        { label: "model-rethink", phase: "求解-第" + iteration + "轮",
          schema: { type: "object", required: ["verdict", "reasoning"], properties: { verdict: { enum: ["FUNDAMENTAL_FLAW", "FIXABLE"] }, flawedAssumptions: { type: "array", items: { type: "string" } }, reasoning: { type: "string" }, suggestedRedesign: { type: "string" } } } }
      )

      if (rethinkResult && rethinkResult.verdict === "FUNDAMENTAL_FLAW") {
        redesignCount++
        if (redesignCount > MAX_REDESIGNS) {
          log("[Phase 5-6/8] 已达最大重新设计次数(" + MAX_REDESIGNS + ")，以当前方案继续求解")
          allIssues.push(...criticalNew.map(i => ({ ...i, severity: "moderate", issue: "[未解决] " + i.issue })))
          continue
        }
        log("[Phase 5-6/8] 判定: 建模路线根本缺陷 → 打回 Phase 4 重新建模 (#" + redesignCount + "/" + MAX_REDESIGNS + ")")
        log("[Phase 5-6/8] 缺陷假设: " + (rethinkResult.flawedAssumptions || []).join("; ").slice(0, 200))

        log("[Phase 5-6/8] ⚠️ 建模路线根本缺陷! 自动启动重新设计流程。")
        await agent(
          "## 写警报文件\n\n" +
          "将以下内容写入 `" + outputDir + "/logs/MODEL_RETHINK_ALERT.txt`：\n\n" +
          "建模路线根本缺陷检测报告\n" +
          "========================\n" +
          "时间: 第" + iteration + "轮验证后\n" +
          "缺陷假设:\n" + (rethinkResult.flawedAssumptions || []).map(a => "  - " + a).join("\n") + "\n\n" +
          "分析:\n" + (rethinkResult.reasoning || "") + "\n\n" +
          "建议方向:\n" + (rethinkResult.suggestedRedesign || "") + "\n\n" +
          "---\n" +
          "Workflow 将自动进行模型重新设计并由4人评审团审查。\n" +
          "用户可在任何时候通过 /workflows 查看进度。\n\n" +
          "Use Write tool to create this file. Create dir first if needed.",
          { label: "write-alert", phase: "求解-第" + iteration + "轮" }
        )

        // 重新建模
        const redesignContext = "## 原始方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 3000) +
          "\n\n## 验证暴露的问题\n" + JSON.stringify(allIssues.filter(f => f.severity === "critical").slice(-15), null, 2) +
          "\n\n## 模型反思结论\n" + JSON.stringify(rethinkResult, null, 2)

        let redesignApproach = await agent(
          "## 建模路线重新设计\n\n" + problemCtx + "\n\n" + redesignContext + "\n\n" +
          "## 文献上下文\n" + JSON.stringify({ models: allModels.slice(0, 8), claims: allClaims.slice(0, 10) }, null, 2) + "\n\n" +
          "## 任务\n" +
          "根据验证暴露的根本问题，重新设计建模路线。不要改参数——换思路。\n" +
          "比如：生存分析不行→换贝叶斯分层模型？PAVA过拟合→换正则化回归？AFT随机→换决策树ensemble？\n" +
          "给出完整的重新设计方案：假设→符号→方程→求解策略。\n\n" +
          "Structured output only." + ctx.saveToFile("04-redesign-r" + iteration + ".json"),
          { label: "redesign-model", phase: "求解-第" + iteration + "轮", schema: MODEL_PROPOSAL_SCHEMA }
        )

        if (redesignApproach) {
          const extraCtx = "\n## 原方案致命缺陷\n" + JSON.stringify(rethinkResult.flawedAssumptions || [], null, 2) +
            "\n## 原方案验证暴露的问题\n" + JSON.stringify(allIssues.filter(f => f.severity === "critical").slice(-10), null, 2)
          const redesignResult = await critiqueLoop(redesignApproach, { chosenAnalysis, limitationAnalysis }, ctx, {
            personas: CRITIQUE_PERSONAS, maxRounds: 2,
            label: "redesign-critique", phaseName: "求解-第" + iteration + "轮", savePrefix: "04-redesign",
            extraContext: extraCtx,
          })
          redesignApproach = redesignResult.finalModel
          if (redesignResult.vetoPassed) {
            redesignHistory.push({ iteration, approach: JSON.parse(JSON.stringify(redesignApproach)), reason: rethinkResult?.reasoning })
            // Update finalModel in ctx
            ctx.finalModel = redesignApproach
            const legacyIssues = allIssues.filter(f => f.severity === "critical").slice(-10)
            currentSolution = null; dry = 0; baselineResult = null; needsBaseline = true
            allIssues = []; refutedIssues = []
            if (legacyIssues.length > 0) {
              allIssues.push(...legacyIssues.map(i => ({ ...i, severity: "moderate", issue: "[原方案遗留] " + i.issue })))
            }
            log("重新设计通过4人审查! 新方案: " + (redesignApproach.approach || "").slice(0, 80))
          } else {
            log("重新设计审查未通过，保留原方案继续")
          }
        }
      } else if (rethinkResult && rethinkResult.verdict === "FIXABLE") {
        log("[Phase 5-6/8] 判定: 问题可修复 — 继续求解迭代")
      }
      if (rethinkResult) {
        allRethinkResults.push({ iteration, verdict: rethinkResult.verdict, flawedAssumptions: rethinkResult.flawedAssumptions, reasoning: rethinkResult.reasoning, suggestedRedesign: rethinkResult.suggestedRedesign })
      }
    }

    // ── Dry/Convergence logic + Trend exit ──
    if (newIssues.length === 0) {
      const criticalRemaining = allIssues.filter(i => i.severity === "critical").length
      if (criticalRemaining === 0 && findings.length > 0) {
        dry++
      log("[Phase 5-6/8] 第" + iteration + "轮: 无新问题,无critical遗留 (dry=" + dry + "/" + cfg.dryThreshold + ")")
      } else if (findings.length === 0) {
        logError(ErrorLevel.WARNING, "求解-第" + iteration + "轮", "本轮全部验证 agent 失败，验证产出为空，不累计 dry（防止假收敛）")
      } else {
        log("第" + iteration + "轮: 无新问题但仍有 " + criticalRemaining + " 个 critical 未修复 (dry不变=" + dry + "/" + cfg.dryThreshold + ")")
      }
    } else {
      dry = 0
      allIssues.push(...newIssues)
      const criticalNow = newIssues.filter(f => f.severity === "critical").length
      log("第" + iteration + "轮: +" + newIssues.length + " 问题 (critical=" + criticalNow + " total=" + allIssues.length + "), dry 重置")
    }

    if (prevNewCount !== Infinity) {
      if (newIssues.length > prevNewCount * 1.1) { worseningStreak++; }
      else { worseningStreak = 0; }
      if (worseningStreak >= 2) {
        log("[Phase 5-6/8] 求解趋势恶化(连续" + worseningStreak + "轮新问题数超过上轮1.1倍)→ 退出迭代")
        break
      }
    }
    prevNewCount = newIssues.length

    if (allIssues.length > 50) {
      log("累积问题超50个(allIssues=" + allIssues.length + ")→ 取critical+top20修复后退出")
      break
    }

    iterationLog.push({ iteration, newIssues: newIssues.length, dry, totalIssues: allIssues.length })
  }

  // ── 最终修复轮 ──
  const currentCriticalCount = allIssues.filter(i => i.severity === "critical").length
  const solveConverged = dry >= cfg.dryThreshold && currentCriticalCount === 0
  if (!solveConverged && currentSolution && allIssues.length > 0) {
    const unfixedCritical = allIssues.filter(i => i.severity === "critical").slice(0, 5)
    if (unfixedCritical.length > 0) {
      log("[Phase 5-6/8] 求解未收敛(dry=" + dry + "/" + cfg.dryThreshold + ", critical=" + currentCriticalCount + ")，执行最终修复 (unfixed=" + unfixedCritical.length + ")")
      const finalFixAlgo = await agent(
        "## 最终修复 — 算法修正\n\n" +
        "## 建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 4000) + "\n\n" +
        "## 上一轮求解结果\n" + JSON.stringify(currentSolution?.results || {}, null, 2).slice(0, 2000) + "\n\n" +
        "## 待修复的 critical 问题（只修这些）\n" + unfixedCritical.map(i => "- [" + i.severity + "] " + i.issue).join("\n") + "\n\n" +
        "## 任务\n" +
        "只修复以上列出的 critical 问题。不做大改——不换算法框架、不重构代码。\n" +
        "给出修改后的具体实现细节。输出纯文本。",
        { label: "final-fix-algo", phase: "求解-最终修复" }
      )
      if (finalFixAlgo) {
        const finalFixImpl = await agent(
          "## 最终修复 — 代码实现\n\n" +
          "## 算法修正\n" + finalFixAlgo + "\n\n" +
          "## 上一轮求解结果\n" + JSON.stringify(currentSolution?.results || {}, null, 2).slice(0, 2000) + "\n\n" +
          "## 任务\n" +
          "将算法修正写入代码并运行。\n" +
          "1. 将修改后的代码写入 `" + codeDir + "/solution_final_fix.py`\n" +
          "2. 用 `run_in_background: true` 后台运行：`cd " + outputDir + " && python3 code/solution_final_fix.py > logs/solution_final_fix.log 2>&1`，每10秒检查，最长等15分钟\n" +
          "3. 报告实际运行结果。\n\n" +
          "Structured output only.",
          { label: "final-fix-impl", phase: "求解-最终修复", schema: SOLUTION_SCHEMA }
        )
        if (finalFixImpl) {
          currentSolution = finalFixImpl
          log("求解最终修复完成")
          for (const ci of unfixedCritical) {
            ci.severity = "moderate"
            ci.issue = "[最终修复] " + ci.issue
          }
        }
      }
    }
  }

  log("[Phase 5-6/8] 求解⇄验证完成 ✓ — " + iteration + " 轮迭代, " + allIssues.length + " 个问题, " + allIssues.filter(i => i.severity === "critical").length + " 个严重, dry=" + dry + "/" + cfg.dryThreshold)

  // ── 稳健性分析报告 —— 聚合灵敏度/边界/统计/对抗发现 → 「灵敏度与稳健性分析」章的数据来源 ──
  // 优秀论文的灵敏度/稳健性章（如2024 C038 鲁棒优化+动态调参、2023 C228 加噪鲁棒性检验）都是
  // 多方法+扰动表+明确结论；这里把验证阶段散落的发现聚合为结构化报告，写作章直接引用。
  let robustnessReport = null
  if (currentSolution && (allIssues.length > 0 || (allAdversarialFindings && allAdversarialFindings.length > 0))) {
    const sensitivityIssues = allIssues.filter(f => !f._dimension || ["sensitivity", "edge_cases", "statistical"].includes(f._dimension))
    robustnessReport = await agent(
      "## 稳健性分析报告（灵敏度与稳健性章的数据来源）\n\n" +
      formatSubQuestions(subQuestions) +
      (chosenAnalysis._rawDescription ? "## 题目原文\n" + PROBLEM_READ_HINT + "\n\n" : "") +
      "## 建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 3000) + "\n\n" +
      "## 最终求解结果\n" + JSON.stringify(currentSolution?.results || {}, null, 2).slice(0, 3000) + "\n\n" +
      "## 验证发现（灵敏度/边界/统计/对抗，全部来自验证阶段真实产出）\n" + JSON.stringify(allIssues.slice(-25), null, 2) + "\n\n" +
      (baselineResult ? "## Baseline 对比\n" + JSON.stringify(baselineResult, null, 2).slice(0, 1500) + "\n\n" : "") +
      "## 任务\n" +
      "把验证发现汇总成结构化稳健性分析报告（优秀论文的「灵敏度/稳健性」章数据来源）：\n" +
      "1. perturbationResults: 参数扰动对关键结果的影响（基于灵敏度发现整理，{parameter, perturbation, effectOnResult, sensitivityLevel}）\n" +
      "2. robustnessStatements: 明确的稳健性结论（{statement, supportingEvidence, boundary}），至少 3 条——模型在什么范围内可靠、什么条件下会失效\n" +
      "3. weakestPoints: 模型最脆弱的地方（基于 adversarial/edge 发现）\n" +
      "4. statisticalChecks: 统计稳健性（置信区间/样本量/检验结论）\n" +
      "⚠️ 只基于上面提供的真实发现整理，禁止编造数字或凭空添加扰动实验；若某项无信息写「无」。\n\nStructured output only." + ctx.saveToFile("06-robustness-report.json"),
      { label: "robustness-report", phase: "求解-稳健性",
        schema: { type: "object", required: ["perturbationResults", "robustnessStatements", "weakestPoints", "statisticalChecks"], properties: {
          perturbationResults: { type: "array", items: { type: "object", properties: { parameter: { type: "string" }, perturbation: { type: "string" }, effectOnResult: { type: "string" }, sensitivityLevel: { enum: ["low", "medium", "high"] } } } },
          robustnessStatements: { type: "array", items: { type: "object", properties: { statement: { type: "string" }, supportingEvidence: { type: "string" }, boundary: { type: "string" } } } },
          weakestPoints: { type: "array", items: { type: "string" } },
          statisticalChecks: { type: "array", items: { type: "object", properties: { check: { type: "string" }, result: { type: "string" } } } },
        } } }
    )
    if (robustnessReport) {
      log("[Phase 5-6/8] 稳健性分析报告完成 — " + (robustnessReport.robustnessStatements?.length || 0) + " 条稳健性结论")
    }
  }

  // Store results in ctx
  ctx.currentSolution = currentSolution
  ctx.baselineResult = baselineResult
  ctx.allIssues = allIssues
  ctx.iterationLog = iterationLog
  ctx.allAdversarialFindings = allAdversarialFindings
  ctx.allRethinkResults = allRethinkResults
  ctx.redesignHistory = redesignHistory
  ctx.overallRobustness = overallRobustness
  ctx.robustnessReport = robustnessReport

  return { currentSolution, baselineResult, allIssues, iterationLog, solveConverged, robustnessReport }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: lib/phase7-writing.js
// ═══════════════════════════════════════════════════════════════

// ═══ Phase 7: 写作 — 事实源表 → 叙事大纲 → 顺序主编撰写 → 交叉审查(统一修复) ═══
// Depends on: agent(), parallel(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile, ctx.subQuestions


async function phase7_writing(ctx) {
  const { cfg, chosenAnalysis, selection, finalModel, currentSolution, baselineResult,
          limitationAnalysis, gapAnalysis, fitnessCheck, earlyJudgeReview,
          allSources, allModels, allClaims,
          allIssues, allAdversarialFindings, allRethinkResults, redesignHistory,
          overallRobustness, innovationProposals, outputDir, figuresDir,
          subQuestions, iterationLog, competition, intermediatesDir, attachments,
          problemAnalysis, edaReport, robustnessReport } = ctx
  const isMcm = competition === 'mcm'

  if (!currentSolution) {
    return { error: "求解阶段未产生有效解。" }
  }
  if (!finalModel) {
    return { error: "建模阶段未产生有效方案。" }
  }
  phase("写作")
  log("[Phase 7/8] 写作开始 — 预计 10-15 分钟")

  // ── Step 7.0: 创新追溯矩阵 ──
  let innovationMatrix = null
  innovationMatrix = await agent(
    "## 创新追溯矩阵\n\n" +
    "## 最终建模方案\n" + JSON.stringify(finalModel, null, 2).slice(0, 5000) + "\n\n" +
    "## Gap Analysis 局限\n" + (typeof limitationAnalysis === "string" ? limitationAnalysis.slice(0, 2000) : "") + "\n\n" +
    "## 求解结果\n" + JSON.stringify(currentSolution?.results || {}, null, 2).slice(0, 2000) + "\n\n" +
    (baselineResult ? "## Baseline 对比\n" + JSON.stringify(baselineResult, null, 2).slice(0, 1500) + "\n\n" : "") +
    "## 任务\n" +
    "生成创新追溯表格。每个创新点一行，每行包含：\n" +
    "| 创新点 | 解决的GAP/局限 | 对应方程/算法 | 验证指标 | 基线对比提升 | 摘要位点 | 模型章位点 | 分析章位点 |\n\n" +
    "确保：(1) 每个创新点都有对应的验证数据支撑 (2) 摘要中提到的东西在模型章节有详细展开 (3) 分析章节的结论与baseline对比一致\n\n" +
    "输出纯文本表格。",
    { label: "innovation-matrix", phase: "写作" }
  )
  if (innovationMatrix) log("[Phase 7/8] 创新追溯矩阵完成")

  // ═══ Context builders — per-agent targeted subsets ═══
  const advFindings = allAdversarialFindings || []
  const otherIssues = allIssues ? allIssues.filter(i => !advFindings.some(a => a.issue === i.issue)) : []

  const currentRules = PAPER_RULES[competition] || PAPER_RULES.cumcm

  // problem 清理：剥掉 _rawDescription/_dataProfile/_paperRules（全文统一在 intermediates/00-problem.md，
  // 写作 agent 需要时 Read；这里避免大文本随结构化 problem JSON 重复注入写作上下文）
  const problemForWriting = chosenAnalysis ? { ...chosenAnalysis } : null
  if (problemForWriting) {
    delete problemForWriting._rawDescription
    delete problemForWriting._dataProfile
    delete problemForWriting._paperRules
  }
  // solution 清理：写作不需要完整源码与算法文本，只留结果摘要/关键值/图列表（省 30-40k 字符）
  const solutionForWriting = currentSolution ? {
    summary: currentSolution?.results?.summary || "",
    keyValues: currentSolution?.results?.keyValues || [],
    plots: currentSolution?.results?.plots || [],
    concerns: currentSolution?.concerns || [],
    testPassed: currentSolution?.testPassed,
  } : null

  const allContext = {
    competition,
    problem: problemForWriting, selection,
    finalModel, solution: solutionForWriting,
    problemAnalysis: typeof problemAnalysis === "string" ? problemAnalysis.slice(0, 5000) : null,
    edaReport: edaReport ? JSON.stringify(edaReport, null, 2).slice(0, 6000) : null,
    robustnessReport: robustnessReport ? JSON.stringify(robustnessReport, null, 2).slice(0, 6000) : null,
    adversarialFindings: advFindings.map(f => ({ issue: f.issue, severity: f.severity, evidence: f.evidence })),
    rethinkHistory: (allRethinkResults || []).map(r => ({ iteration: r.iteration, verdict: r.verdict, flawedAssumptions: r.flawedAssumptions, reasoning: (r.reasoning || "").slice(0, 500) })),
    redesignHistory: (redesignHistory || []).map(r => ({ iteration: r.iteration, reason: (r.reason || "").slice(0, 300), approachSummary: (r.approach?.approach || "").slice(0, 500) })),
    innovationMatrix: typeof innovationMatrix === "string" ? innovationMatrix.slice(0, 3000) : null,
    innovation: {
      limitationAnalysis: typeof limitationAnalysis === "string" ? limitationAnalysis.slice(0, 3000) : null,
      gapAnalysis: typeof gapAnalysis === "string" ? gapAnalysis.slice(0, 2000) : null,
      fitnessCheck: fitnessCheck ? { totalScore: fitnessCheck.totalScore, verdict: fitnessCheck.verdict, riskSummary: fitnessCheck.riskSummary, scores: fitnessCheck.scores } : null,
      baselineResult: baselineResult ? { summary: baselineResult.summary, significance: baselineResult.significance, metrics: baselineResult.metrics, weaknessExposed: baselineResult.weaknessExposed } : null,
      earlyJudgeReview: typeof earlyJudgeReview === "string" ? earlyJudgeReview.slice(0, 2000) : null,
    },
    literature: { sources: allSources ? allSources.length : 0, models: (allModels || []).slice(0, 10), keyClaims: (allClaims || []).slice(0, 15) },
    externalData: ctx.externalData ? { needsExternalData: ctx.externalData.needsExternalData, sources: (ctx.externalData.sources || []).map(s => ({ id: s.id, purpose: s.purpose, status: s.status, sourceUrl: s.sourceUrl, fetchedAt: s.fetchedAt, fields: s.fields })) } : null,
    verification: { otherIssues, iterationLog, overallRobustness },
  }

  const cleanContext = stripNulls(allContext)

  const WRITING_PRIORITY = ["competition", "adversarialFindings", "finalModel", "solution", "problem", "problemAnalysis", "edaReport", "robustnessReport", "innovation", "externalData", "rethinkHistory", "redesignHistory", "innovationMatrix", "literature", "verification"]

  const buildNarrativeContext = () => buildContextStr(cleanContext, WRITING_PRIORITY, Math.floor(cfg.contextBudget * 0.8), { summarizeLongFields: true })

  // ── Step 7.1b: 章节上下文裁剪 —— 顺序主编模式下每个章节仍是独立 agent 调用，
  // 只注入该章节真正需要的 key（跨章一致性由 前文注入 + 事实源表 + 风格指南 保证），
  // 根治"每个写作 agent 拿满 10 万字符上下文"的超限问题。
  // key 顺序即优先级：budget 截断时保前面的（每个章节最重要的放最前）。
  // ⚠️ 题目原文/数据画像/论文规则不再作为 key 注入——统一在 `intermediates/00-problem.md`，写作 agent 需要时 Read。
  const SECTION_KEY_NEEDS = {
    abstract:          ['solution', 'finalModel', 'innovation', 'adversarialFindings', 'problem'],
    restatement:       ['problem'],
    problem_analysis:  ['problemAnalysis', 'problem', 'finalModel', 'literature'],
    assumptions:       ['finalModel', 'problem'],
    data_analysis:     ['problem'],
    model:             ['finalModel', 'solution', 'problemAnalysis', 'problem', 'innovation'],
    analysis:          ['solution', 'innovation', 'adversarialFindings', 'verification', 'finalModel'],
    robustness:        ['solution', 'adversarialFindings', 'verification', 'innovation'],
    model_eval:        ['innovation', 'solution', 'finalModel', 'adversarialFindings', 'verification'],
    conclusion:        ['problem', 'solution', 'finalModel', 'innovation', 'adversarialFindings', 'redesignHistory', 'rethinkHistory'],
  }
  // 这些 key 不做摘要保留完整原文（由 budget 兜底截断）；其余长字段一律摘要为 200 字符预览
  const CONTEXT_FULL_KEYS = ['finalModel', 'solution', 'edaReport', 'robustnessReport', 'problemAnalysis']
  // 章节专属预算（字符）：模型章最重，给 40k；其余 25k
  const SECTION_BUDGETS = { model: 40000 }

  function buildSectionContext(sectionId) {
    const keys = SECTION_KEY_NEEDS[sectionId] || []
    const selected = {}
    for (const k of keys) {
      if (cleanContext[k] !== undefined && cleanContext[k] !== null) selected[k] = cleanContext[k]
    }
    return buildContextStr(selected, keys, SECTION_BUDGETS[sectionId] || 25000, {
      summarizeLongFields: true, fullKeys: CONTEXT_FULL_KEYS,
    })
  }

  // ── Step 7.1: 叙事大纲 ──
  let narrativeOutline = null
  narrativeOutline = await agent(
    "## 论文叙事大纲\n\n" +
    formatSubQuestions(subQuestions) +
    (subQuestions && subQuestions.length > 0 ? "请围绕子问题组织叙事弧线，每个子问题形成独立的故事单元，同时保持整体逻辑连贯。\n\n" : "") +
    "## 题面文档（需要题目原文时先 `Read`）\n" + PROBLEM_READ_HINT + "\n\n" +
    "## 建模上下文\n" + buildNarrativeContext() + "\n\n" +
    "## 任务\n" +
    "为" + (isMcm ? "美赛（MCM/ICM）" : "国一") + "论文设计叙事大纲。记住：论文不是技术报告——评委是人，读完要有「这个队有想法」的直觉。\n\n" +
    "设计要点：\n" +
    "1. **方案逻辑为主线**：核心方法如何逐层展开？如有改进点，自然融入推导，不要最后才贴上去。\n" +
    "2. **问题驱动**：每一章回答什么问题？为什么读者想看下一章？\n" +
    "3. **节奏控制**：模型推导(dense)→结果展示(light)→亮点highlight(punch)——张弛有道\n" +
    "4. **记忆点**：哪一段让评委在这100篇论文里记住你的？\n" +
    "5. **摘要先行**：摘要要怎么埋钩子让评委想继续看？\n\n" +
    "输出：各章节的叙事定位、衔接逻辑、创新展示节奏、记忆点设计。" + ctx.saveToFile("07-narrative-outline.txt"),
    { label: "narrative-outline", phase: "写作" }
  )
  if (narrativeOutline) {
    log("[Phase 7/8] 叙事大纲完成")
  }

  // ── Step 7.1b: 风格指南 —— 统一术语、语气、图表格式、数学符号
  let styleGuide = null
  {
    const problemDomain = chosenAnalysis?.domain || ''
    const problemObjectives = (chosenAnalysis?.objectives || []).join('; ').slice(0, 300)
    const problemBackground = (chosenAnalysis?.background || '').slice(0, 300)
    styleGuide = await agent(
      "## 论文写作风格指南\n\n" +
      "你是数模论文写作专家。根据题目信息和领域特征，生成一份写作风格指南，用于指导顺序撰写的主编写作 agent 保持全篇一致的风格（主编后续章节必须遵守，交叉审查与修复同样以本指南为基准）。\n\n" +
      "## 题目信息\n" +
      "- 领域: " + problemDomain + "\n" +
      "- 背景: " + problemBackground + "\n" +
      "- 目标: " + problemObjectives + "\n" +
      "- 竞赛: " + (isMcm ? "MCM/ICM（英文）" : "CUMCM（中文）") + "\n\n" +
      "## 输出要求\n" +
      "生成 JSON，包含以下字段：\n\n" +
      "1. **术语表 (termTable)**: 该领域的核心术语和标准翻译/表达。每项包括术语(term)、标准表达(standard)、禁用表达(avoid)。至少5条。\n" +
      "2. **语气与句式规范 (toneSpec)**: 描述论文应有的语气风格（正式/客观/严谨），给出具体要求。\n" +
      "3. **图表引用格式 (figureFormat)**: 图编号规则、引用写法（如`如图~\\ref{fig:xxx}所示`）。\n" +
      "4. **数学符号规范 (mathNotation)**: 变量命名约定（标量/向量/矩阵）、下标规则、符号一致性要求。\n" +
      "5. **范文段落 (sampleParagraph)**: 一段50-100字的范文，展示正确的风格、公式引用和图表引用写法。\n\n" +
      "Structured output only." + ctx.saveToFile("07-style-guide.json"),
      {
        label: "style-guide",
        phase: "写作",
        schema: {
          type: "object",
          required: ["termTable", "toneSpec", "figureFormat", "mathNotation", "sampleParagraph"],
          properties: {
            termTable: { type: "array", items: { type: "object", properties: { term: { type: "string" }, standard: { type: "string" }, avoid: { type: "string" } } } },
            toneSpec: { type: "string" },
            figureFormat: { type: "string" },
            mathNotation: { type: "string" },
            sampleParagraph: { type: "string" },
          },
        },
      }
    )
    if (styleGuide) {
      log("[Phase 7/8] 风格指南完成 — " + (styleGuide.termTable ? styleGuide.termTable.length + ' 个术语' : ''))
    }
  }

  // ── Step 7.1c: 事实源表（单一事实源，冻结最终结果）──
  // 从最终求解结果/模型方案中提取"论文事实表"：所有关键数字、符号、口径、引用键。
  // 后续所有章节撰写与修复必须以此表为唯一数字来源，杜绝"不同章节用了不同版本数字"。
  let factSheet = null
  {
    const res = currentSolution?.results || {}
    factSheet = await agent(
      "## 论文事实源表构建（单一事实源）\n\n" +
      "你是数字审计员。从以下**最终运行结果**中提取论文将要引用的全部关键事实，输出结构化 JSON。这些事实将作为全篇写作的唯一数字来源——任何章节不得使用本表之外的数字。\n\n" +
      "## 最终求解结果（唯一权威）\n" + JSON.stringify(res, null, 2).slice(0, 8000) + "\n\n" +
      "## 最终模型方案（符号与公式权威）\n" + JSON.stringify(finalModel, null, 2).slice(0, 4000) + "\n\n" +
      (baselineResult ? "## Baseline 对比（唯一权威）\n" + JSON.stringify(baselineResult, null, 2).slice(0, 3000) + "\n\n" : "") +
      "## 输出要求（JSON）\n" +
      "1. **keyNumbers**: 论文将引用的全部关键数字。每项 { number(精确数值), label(如'数据1θ1%'), context(在哪个子问题/场景使用), sourcePath(在results中的路径) }。覆盖：阈值、档位户数、名单数、评分、比例/百分比、负值/截断计数、损失额、Jaccard/相关系数、置信区间、权重（如峰:平:谷=3:1.5:1）、用户数口径（各数据集唯一用户数）等。\n" +
      "2. **symbols**: 核心符号及其含义、LaTeX写法（如 score_u = min(1, 0.8S_self + 0.2S_cross)）。\n" +
      "3. **caliberNotes**: 口径注意事项（如'名单=预算定容30户，非全量高档全集'、'损失为相对损失指数无单位'、'报表1与报表2需分别标注'）。\n" +
      "4. **datasetFacts**: 各数据集的事实（文件数、用户数、时间范围、负值数、截断数等画像数字）。\n\n" +
      "⚠️ 只提取结果数据中**真实存在**的数字；不要补全、不要推测、不要写早期版本的数字。\nStructured output only." + ctx.saveToFile("07-fact-sheet.json"),
      {
        label: "fact-sheet",
        phase: "写作",
        schema: {
          type: "object",
          required: ["keyNumbers", "symbols", "caliberNotes", "datasetFacts"],
          properties: {
            keyNumbers: { type: "array", items: { type: "object", properties: { number: { type: "string" }, label: { type: "string" }, context: { type: "string" }, sourcePath: { type: "string" } } } },
            symbols: { type: "array", items: { type: "object", properties: { symbol: { type: "string" }, meaning: { type: "string" }, latex: { type: "string" } } } },
            caliberNotes: { type: "array", items: { type: "string" } },
            datasetFacts: { type: "array", items: { type: "object", properties: { dataset: { type: "string" }, facts: { type: "string" } } } },
          },
        },
      }
    )
    if (factSheet) log("[Phase 7/8] 事实源表完成 — " + (factSheet.keyNumbers ? factSheet.keyNumbers.length + ' 个关键数字' : ''))
  }

  // ── Step 7.2: 章节定义 ──
  const SECTION_PRESETS = {
    full: [
      { id: "abstract", label: "摘要", prompt: "撰写摘要。按子问题分段：「对于问题1，…对于问题2，…对于问题3，…」每段给出方法+核心结果。300-500字。\n\n**格式要求：**\n① 每个子问题的核心数值用\\bm{}加粗（如$\\bm{d=7.66\\pm0.78~\\mu\\text{m}}$）\n② 只加粗答案关键词和数值，不加粗整句叙述\n③ 禁止使用「创新点：」「关键发现：」「核心结论：」等标签——创新自然融入答案描述\n④ 末段一句话总结核心发现\n⑤ 最后附上**关键词**（3-5个，用分号分隔）" },
      { id: "restatement", label: "问题重述", prompt: "重述问题。背景、已知条件、求解目标（问题逐条列出）。不要复制原题——用自己的话重新组织。背景部分如需引用领域文献（能源/政策/行业背景）用 \\\\cite 标注。**注意：本章只做重述，不做方法分析——「问题分析」由专门一章负责。**" },
      { id: "problem_analysis", label: "问题分析", prompt: "撰写「问题分析」章——优秀获奖论文的标准第2章。对**每个子问题**逐问分析（用「对于问题N」分段）：\n① 机理/业务推理：这个子问题背后的物理/几何/业务机制是什么？为什么题目这样设问？\n② 难点识别：该问最大的难点（数据陷阱/机理复杂/求解困难）具体在哪？\n③ 建模思路草图：打算用什么模型、先做什么后做什么、如何逐层递进？若该问依赖前置问题，说明如何复用前置结果。\n④ 数据要点：该问用到哪些数据/附件、需要怎样的预处理（无附件则说明所需数据如何构造；若已自行收集外部数据，说明使用了哪些外部数据及其作用）。\n要求：有机理深度、给出清晰思路路线，但**不写完整公式推导**（那是模型章的事）；禁止「难点：」「创新点：」等标签，自然融入叙述。可引用下方 context 中的 problemAnalysis 作为原始素材，也可引用领域文献支撑机理判断。" },
      { id: "assumptions", label: "模型假设+符号", prompt: "列出假设条件和符号说明。每个假设说明合理性（为什么可以这样简化）。符号用表格（符号|含义|单位）。" },
      { id: "data_analysis", label: "数据预处理与探索性分析", prompt: "撰写「数据预处理与探索性分析」章——优秀数据题获奖论文的标准章节。先 `Read` `intermediates/04-eda-report.json`（EDA 数据发现报告，含实际运行的数字）作为**唯一数据来源**，分三部分：\n① 数据预处理：数据整合（多表关联/聚合规则与公式）、缺失值处理、异常值剔除（3σ/业务规则）、无关数据剔除——每条给出处理规则、剔除数量与理由（引用 cleaningDecisions 的实际数字）。\n② 探索性分析：用实际生成的图表（fig_eda_*.png，分布/时序/ACF/相关热力图/占比）分析分布规律、趋势、周期性、相关性、关联规则；涉及统计检验时给出检验方法、统计量、p 值、样本量（引用 findings 的 evidence）。\n③ 数据发现对建模的启示：EDA 发现的规律如何驱动后续模型选择（引用 findings.implicationForModeling）。\n⚠️ 数字纪律：只使用 EDA 报告中真实存在的数字，禁止编造；每个图都要在文中 \\\\includegraphics 引用。\n⚠️ **外部数据来源合规（如使用了自行收集的数据）**：`Read` `intermediates/04-data-collection.json`，在章内说明每个外部数据集的**来源名称、URL、获取日期**（以「数据来源」小节或脚注形式），并在参考文献中按 GB/T 7714 标注；没有外部数据则忽略本条。" },
      { id: "model", label: "模型建立与求解", prompt: "核心章节。写出完整模型推导、关键方程(LaTeX)、求解算法、代码逻辑、结果(含图表描述)。**如有需要，先在章首写「模型准备」小节（坐标系建立/符号定义/问题形式化），再进入推导**——优秀机理题论文（如定日镜场）都有这一过渡。**创新点要自然融入推导过程——不是单独一段「我们的创新是……」而是在推导中展示「标准方法在这里有X局限，因此我们引入Y来处理」。**如有baseline对比数据，在这里用表格展示。" },
      { id: "analysis", label: "结果分析与验证", prompt: "分析结果意义、与baseline/文献对比、结果解读（用图表支撑）。如果有baseline对比数据，用图表展示创新vs标准的差异。诚实讨论局限：若求解/验证中确实发现模型在某种条件下失效或精度不足，以论文语言诚实呈现（如「进一步分析表明当X时误差增大」）——**禁止出现「对抗性审查」「模型重设计」「adversarialFindings」「验证器」等内部流程字样，也不得把内部迭代历史写进论文**；把发现转述成\"结果解读/局限讨论\"的论文口吻即可。（模型优劣势与推广由「模型的评价与推广」章负责，本章不重复；灵敏度与稳健性由「灵敏度与稳健性分析」章负责，本章可简要提及但不展开。）" },
      { id: "robustness", label: "灵敏度与稳健性分析", prompt: "撰写「灵敏度与稳健性分析」章——优秀获奖论文的标准章节（如鲁棒优化灵敏度、动态调参灵敏度）。先 `Read` `intermediates/06-robustness-report.json`（稳健性报告，含验证阶段实际发现）作为**数据来源**，展示：\n① 参数扰动分析：关键参数（±10%/±20% 或题目关键参数）扰动对核心结果的影响，识别最敏感参数（用表格/图展示扰动-结果关系，引用 perturbationResults）。\n② 边界与极端情况：边界/极端输入下模型的表现（引用验证发现的 edge_cases 维度）。\n③ 统计稳健性：置信区间、样本量、对假设偏离的容忍度（引用 statisticalChecks）。\n④ 明确结论：模型在什么范围内可靠、什么条件下会失效；若验证确实暴露了脆弱点，以论文语言诚实讨论（如「当X时模型失效」）——**禁止出现「对抗性审查」「adversarialFindings」等内部流程字样**，把发现转述成稳健性结论的论文口吻。\n⚠️ 数字纪律：只使用稳健性报告 / 验证发现中真实存在的数字，禁止编造；若某项无信息写「本项未做专门检验」。每个结论要有实际数字支撑。" },
      { id: "model_eval", label: "模型的评价与推广", prompt: "撰写「模型的评价与推广」章（优秀获奖论文标准章节，如「模型优点/缺点/推广」），分三节：\n① 模型的优点：2-4条，具体到方法/机制层面，与同类标准方法对比说明强在哪（如有 baseline 对比数据，引用量化提升，如精度/效率/稳健性指标）。\n② 模型的缺点：2-3条，诚实——计算代价、假设局限、数据要求、对哪些场景不适用（若验证揭示认知边界，以论文语言说明——**禁止出现「对抗性审查」「adversarialFindings」等内部流程字样**）。\n③ 模型的推广：模型可迁移到哪些领域/场景/其他数据集，迁移需要满足什么条件（数据/假设/参数）。\n⚠️ 禁止「创新点：」等标签；优点要有依据、缺点要具体。实事求是。" },
      { id: "conclusion", label: "结论与改进", prompt: "按子问题逐问总结。每段开头用{\\bfseries 对于问题N——标题：}格式，陈述方法和结果。末尾提改进方向和未来工作。**这一章必须是论文最后一章。**\n\n⚠️ 加粗规则：仅加粗核心数值和答案关键词（如$\\bm{d=7.66\\pm0.78~\\mu\\text{m}}$），不加粗整句。\n⚠️ 禁止使用「创新点：」「关键发现：」「核心结论：」等标签——创新和发现应自然融入答案描述。实事求是。" },
    ],
  }
  // 数据题（有附件或有外部数据）才启用「数据预处理与探索性分析」章；纯机理/无数据时移除该章
  let sectionDefs = SECTION_PRESETS[cfg.sectionPreset] || SECTION_PRESETS.full
  const hasAnyData = (attachments && attachments.length > 0) || !!(ctx.externalData && (ctx.externalData.sources || []).some(s => s.status === "OK"))
  if (!hasAnyData || !ctx.edaReport) {
    sectionDefs = sectionDefs.filter(s => s.id !== "data_analysis")
  }

  const formatGuide = "\n\n## LaTeX 格式要求\n" +
    "输出完整 LaTeX 源码，要求：\n" +
    "- 章节标题：`\\section{...}`、`\\subsection{...}`\n" +
    "- 行内公式：`$...$`，独立公式：`\\begin{equation}...\\end{equation}`\n" +
    "- 表格：`\\begin{table}...\\end{table}` + `\\begin{tabular}...\\end{tabular}`\n" +
    "- 图片：`\\begin{figure}...\\includegraphics{...}...\\end{figure}`\n" +
    "- 引用：`\\cite{...}`（参考文献必须按科技论文规范列出，正文中标注引用位置）\n" +
    "- 列表：`\\begin{itemize}...\\end{itemize}` 或 `\\begin{enumerate}...\\end{enumerate}`\n" +
    (isMcm ? "" : "- 中文字符直接写，不需要转义\n") +
    "- **不要**包含 `\\documentclass`、`\\begin{document}`、`\\maketitle` 等文档级命令\n" +
    "- 仅输出你负责的这一章节的 body 内容\n" +
    "- ⚠️ 文中不要出现参赛者身份、学校、赛区信息（" + (isMcm ? "MCM/ICM" : "CUMC") + " 禁令）"

  const EXPECTED_SECTION_COUNT = sectionDefs.length

  // ── Step 7.2: 各章节顺序撰写（主编视角，详见下方实现）──
  const subQuestionWritingGuide = subQuestions && subQuestions.length > 0
    ? "\n\n## ⚠️ 多子问题结构要求\n本题包含" + subQuestions.length + "个子问题：" +
      subQuestions.map(q => q.label + "：" + q.summary).join("；") + "\n" +
      "请在章节内部用 **「对于" + subQuestions.map(q => q.label).join("」**、「对于") + "」** 等标记分段，每个子问题独立成段。\n" +
      "摘要需分别概括每个子问题的方法和结果。模型章按子问题分段（每段含模型→求解→结果）。结论逐子问题总结。"
    : ""

  const figureLayoutGuide = "\n\n## 图表排版规范\n" +
    "求解阶段已在 `" + figuresDir + "` 目录下生成图表，命名规范为 `fig_{子问题ID}_{内容描述}.png`（如 `fig_Q1_xxx.png`、`fig_Q2_xxx.png`、`fig_cross_xxx.png`），EDA 阶段生成的图命名为 `fig_eda_*.png`。\n" +
    "1. 先 `ls " + figuresDir + "` 列出所有图表文件\n" +
    "2. 根据文件名中的子问题ID（Q1/Q2/Q3），将图表分配到对应的「对于问题N」段落\n" +
    "3. `fig_eda_*` 图表分配到「数据预处理与探索性分析」章（数据题）\n" +
    "4. 文件名中的内容描述即为 caption 依据\n" +
    "5. 跨问题的综合图表（fig_cross_*）放在综合分析章节\n" +
    "6. 确保 `" + figuresDir + "` 中每个文件都在论文中被 `\\includegraphics{...}` 引用；**同时每个 `\\includegraphics` 引用的文件必须真实存在**——禁止空 figure 环境（有 caption 无图）。\n" +
    "7. **本章可以自己画「示意图」**：当本章需要一张图来**帮助读者理解思路**（几何示意/方法流程图/方案示意图/结构图/区域图），而 `" + figuresDir + "` 里没有现成的图时——**不要留空 figure 环境，用 python3 + matplotlib 自己画**并保存：\n" +
    "   - 命名：`fig_{子问题ID}_示意图_{内容描述}.png`（如 `fig_Q2_示意图_碰撞区域几何关系.png`；跨问题用 `fig_cross_示意图_...`；EDA 章用 `fig_eda_...`）\n" +
    "   - 脚本必须先配 CJK 字体（`matplotlib.rcParams['font.sans-serif']=['Noto Sans CJK SC','DejaVu Sans']` + `font.family='sans-serif'` + `axes.unicode_minus=False`），保存用 `plt.savefig('" + figuresDir + "/fig_xxx.png', dpi=200, bbox_inches='tight')`，保存后在终端 `ls " + figuresDir + "` 确认文件真实生成。\n" +
    "   - 在文中用 `\\includegraphics{" + figuresDir + "/fig_xxx.png}` 引用（绝对路径，保证任意目录编译都能找到）。\n" +
    "8. **每张图都要能被一句话解释作用**：文中必须有「如图X所示…」的解读句（读者能从图中看到什么、为什么帮助理解）；图注用 LaTeX math 单位；与思路无关的装饰图不要画。"

  // 写作范式：从国一论文（如 2024 板凳龙 A053）蒸馏的"推导叙事"风格，治 AI 味/术语堆砌/无推导链
  const narrativeStyleGuide =
    "\n\n## 写作范式（必须遵守，治「AI味」——啰嗦、术语堆砌、只贴公式不推导）\n" +
    "你要像**获奖选手写解题手记**，不要像技术白皮书。评委是人，必须让一个外行也能顺着你的思路读下去。\n" +
    "1. **先想后写，一段一意**：每一段先回答「这一小步想解决什么问题、为什么这样想」，再写做法和结果。一段只讲一件事，禁止「首先…其次…再次…」式的罗列腔。\n" +
    "2. **推导要三步走**：每个关键公式必须按「**动机 → 推导 → 含义**」写——先说明为什么这样设（从哪个物理/几何/业务事实出发）、再从定义一步步推到最终式（给出中间步骤，禁止直接甩最终式加一句说明）、最后说这个式子意味着什么、后面怎么用它。参考：优秀论文从「极坐标 → 弧长公式 → 递推关系」一步步来。\n" +
    "3. **术语用人话解释一次**：技术名词首次出现时，用一句大白话说明它是什么、为什么需要它（如「分离轴定理——把两个矩形的碰撞判断拆成各条轴上的投影是否重叠」）；之后直接用。**禁止一段里堆 3 个以上未解释的术语**。\n" +
    "4. **句子短、段落短**：一句一个意思，3-6 行为一段。删掉所有凑字数的话（「值得注意的是」「综上所述」「不难发现」「本文系统地」等），删掉背景科普式铺垫。\n" +
    "5. **摘要/每节开头给「路标」**：像「针对问题一，我们建立 X 模型：先…接着…然后…最后得到…」这样的一句话导读，让读者先知道这一节的路线再读细节。\n" +
    "6. **禁止标签和目录腔**：不得写「创新点：」「关键发现：」「本模型具有以下优势：(1)(2)(3)」；创新和优势融入推导和结果叙述中。\n\n" +
    "### 范文风格（照这个口气写）\n" +
    "「针对问题二，我们建立碰撞检测模型。首先，我们利用反证法证明了整条龙的首次碰撞必然发生在龙头上。接着，根据几何关系表示出各板凳顶点的坐标以划定边界，基于分离轴定理将龙头碰撞问题转化为矩形区域的重叠问题。然后，通过递推法计算出终止时刻为 412.47s，并求得终止时刻处相关把手的位置与速度。」"

  // ── Step 7.2: 各章节顺序撰写（单主编视角：每章可见全部已有章节+事实源表，口径天然统一）──
  // 顺序而非并行：后写章节强制读取前面已写章节，杜绝"不同章节不同口径"；
  // 每个 writer 都是同一"主编"的延续视角（注入全篇+事实表），而非隔离的独立 agent。
  const paperSections = []
  for (let si = 0; si < sectionDefs.length; si++) {
    const s = sectionDefs[si]
    const sectionContextStr = buildSectionContext(s.id)
    const writeOne = (standalone) => agent(
      "## 论文撰写: " + s.label + (standalone ? "（重试：前序章节不可用，独立撰写）" : "") + "\n\n" +
      "## ⚠️ 论文格式规则（必须严格遵守）\n" + currentRules.rules + "\n" +
      "## ⚠️ 题面文档（先 Read 再写）\n题目原文 / 附件数据画像 / 论文规则已落盘到 `" + PROBLEM_DOC + "`。**需要题目原文（问题重述/问题分析/模型章必须读它）、附件数据画像、题目特定论文规则时，开写前先 `Read` 该文件**；本 prompt 不内联全文。\n\n" +
      "## 【最终事实源表】（本论文唯一数字来源，必须逐条遵守）\n" +
      "完整事实源表已保存到 `" + intermediatesDir + "/07-fact-sheet.json`，**开写前必须 `Read` 它**获取全篇数字/符号/口径的权威版本。\n\n" +
      (SKILL_DOCS
        ? "## ⚠️ 规范真源（先 Read 再写）\n完整写作/图表/数字纪律规范在 `" + SKILL_DOCS + "` 的「§一 论文写作规范」「§二 图表生成规范」。**开写前先 `Read` 对应章节**并遵守；以下为本 prompt 的关键约束（Read 失败以此为准）：\n\n"
        : "## ⚠️ 规范真源\n无法定位规范文档（templateDir 未传）：按下述关键约束执行：\n\n") +
      "## 关键约束\n" +
      "- 数字纪律：每个数值声明必须来自你刚 `Read` 的最终事实源表（07-fact-sheet.json）；禁止编造/推算/跨章不一致；缺失写[待定]。\n" +
      "- 摘要按子问题分段（「对于问题1，…」），核心数值用 $\\bm{}$ 加粗；只加粗答案，不加粗整句；禁止「创新点：」等标签。\n" +
      "- 每个子问题独立成段（「对于问题N」）；模型/分析/结论各章覆盖所有子问题。\n" +
      "- 图表单位用 LaTeX math（cm$^{-1}$ 而非 cm⁻¹）；CJK 字体（Noto Sans CJK SC）；附录图用 [H]、正文用 [htbp]。\n\n" +
      "## 叙事大纲\n" + (narrativeOutline ? (typeof narrativeOutline === "string" ? narrativeOutline.slice(0, 2000) : "") : "（无叙事大纲，请自行组织）") + "\n\n" +
      subQuestionWritingGuide +
      figureLayoutGuide + "\n\n" +
      narrativeStyleGuide + "\n" +
      (styleGuide ? "## 写作风格指南（全篇必须遵守）\n" + JSON.stringify(styleGuide, null, 2).slice(0, 1500) + "\n\n" : "") +
      (standalone
        ? "## ⚠️ 独立撰写模式（无法可靠读取前文：请自行从事实源表/叙事大纲保证自洽，写完后仍尽力保存章节文件）\n\n"
        : "## 完整前文（开写前必须 Read 真实落盘文档，不要凭空猜前文）\n" +
          "先前已写章节已保存到 `" + intermediatesDir + "/05-writing/` 目录（每个章节一个文件 `section-<id>.json`）。开写前：\n" +
          "1. `ls " + intermediatesDir + "/05-writing/` 列出所有已存在章节文件\n" +
          "2. 逐个 `Read` 你之前的 `section-*.json`（跳过你自己的 `section-" + s.id + ".json`），读取其中哪个 chapter 的**完整 content**（不要只看开头）\n" +
          "3. 延续所读前文已确定的：符号、数字、口径、术语、章节衔接——数字以【事实源表】为唯一权威\n" +
          "4. 若目录无前文，说明你是首篇/次篇，直接撰写\n" +
          "5. ⚠️ 本章写完后必须把章节保存为 `" + intermediatesDir + "/05-writing/section-" + s.id + ".json`（`{\"section\":\"<章节名>\",\"content\":\"<本章全文>\"}`）——这是后续章节共享前文的载体，保存失败会导致后文断裂。\n\n") +
      "## 本章所需上下文（只含与本章相关的建模与求解信息）\n" + sectionContextStr + "\n\n" +
      "> 所有共享中间文档（EDA 数据发现 / 稳健性 / 问题分析 / 文献等）已落盘到 `" + intermediatesDir + "/` 目录，需要其完整内容时用 `Read` 读取对应 json/txt；本 prompt 只给本章相关的精简摘要。\n\n" +
      "## 任务\n" + s.prompt + formatGuide + "\n\n" +
      "本章节应与先前章节口径完全一致（同一符号、同一数字、同一术语）。\n\nStructured output only." + ctx.saveToFile("05-writing/section-" + s.id + ".json"),
      { label: "write:" + s.id, phase: "写作", schema: PAPER_SECTION_SCHEMA }
    )
    let section = await writeOne(false)
    if (!section) {
      log("[Phase 7/8] 章节 " + s.id + " 首次撰写失败，独立模式重试")
      section = await writeOne(true)
    }
    if (section) {
      paperSections.push(section)
      log("[Phase 7/8] 章节 " + s.id + " (" + s.label + ") 完成 (" + (si + 1) + "/" + sectionDefs.length + ")")
    } else {
      log("[Phase 7/8] ⚠️ 章节 " + s.id + " 撰写失败（两次尝试），跳过")
    }
  }

  log("[Phase 7/8] 完成 " + paperSections.length + "/" + EXPECTED_SECTION_COUNT + " 个章节")

  // ── Step 7.3: 交叉审查 ⇄ 修复 loop ──
  const MAX_WRITING_ROUNDS = QUICK_MODE ? 1 : 3
  let writingRound = 0, writingDry = 0, prevWritingP0Count = Infinity
  let crossSectionReview = null

  while (writingDry < (QUICK_MODE ? 1 : 2) && writingRound < MAX_WRITING_ROUNDS) {
    writingRound++
    log("[Phase 7/8] 写作审查 第" + writingRound + "/" + MAX_WRITING_ROUNDS + "轮...")

    const [crossReview, judgeReview] = safeFilter(await parallel([
      // 交叉审查
      () => agent(
        "## 交叉一致性审查 + 质量门 (第" + writingRound + "轮)\n\n" +
        "## 叙事大纲（预期结构）\n" + (narrativeOutline ? (typeof narrativeOutline === "string" ? narrativeOutline.slice(0, 3000) : "") : "（无）") + "\n\n" +
        "## 各章节内容\n" + paperSections.map(s => "### " + s.section + "\n" + (s.content || "").slice(0, 3000)).join("\n\n---\n\n") + "\n\n" +
        "## 创新追溯矩阵（对照检查）\n" + (typeof innovationMatrix === "string" ? innovationMatrix.slice(0, 2000) : "（无）") + "\n\n" +
        "## 任务：逐项检查以下维度\n\n" +
        "### 一致性检查\n" +
        "1. **符号统一**: 问题重述→模型→结果中的符号是否一致？\n" +
        "2. **数据一致**: 摘要中的数字→正文中的数据→结论中的引用是否匹配？**每个摘要中的数字都必须能在正文中找到出处**，找不到标记为 P0。\n" +
        "3. **逻辑连贯**: 假设→推导→结果→结论是否有逻辑断点？\n" +
        "4. **创新呼应**: 创新点是否在各章节中得到呼应？对照创新追溯矩阵检查。\n" +
        "5. **重复/矛盾**: 不同章节写相同内容？或互相矛盾？\n\n" +
        (writingRound > 1 ? "### ⚠️ 上轮 P0 修复验证\n逐条检查上轮发现的 P0 问题是否真正修复了。没修复的再次标记为 P0。\n\n" : "") +
        "### 质量门检查（硬性指标）\n" +
        "6. **章节数量**: 实际章节数=" + paperSections.length + "，预期=" + EXPECTED_SECTION_COUNT + "。缺失章节→P0。\n" +
        "7. **章节排序**: 结论/改进方向应该是最后一章，不在第1-3节。排序错误→P0。\n" +
        "8. **图表引用**: 先 `ls " + figuresDir + "` 列出所有图表，检查每个文件是否在论文中被 `\\includegraphics` 引用。未引用的图表→P1。**反向检查**：每个 `\\includegraphics` 引用的文件是否真实存在于 `" + figuresDir + "`？找不到文件或空 figure 环境（有 caption 无图）→P0（写作阶段须自己画出示意图或删除该环境）。\n" +
        "8.1. **正文图表数量**: 正文保留 3-5 张最关键图表（如数据总览、FFT演示、方法对比、谐波分析、结果汇总）；其余移至附录。违规→P1。\n" +
        "8.2. **正文页数**: 编译后检查附录首页页码。正文（含摘要）不超过 20 页（CUMCM 规则），超过 20 页→P0。页数超标时优先精简约简非核心段落（未来展望、学术贡献等）而非压缩排版。\n" +
        "8.5. **图表标签验证**: 生成图表的 Python 脚本是否：① 正确配置 CJK 字体（`font.family=\'sans-serif\'`）；② 使用 LaTeX math 而非 Unicode 上下标（`cm$^{-1}$` 而非 `cm⁻¹`，`A$_2$/A$_1$` 而非 `A₂/A₁`）。违规→P0（图表中文或单位将渲染为方框）。\n" +
        "9. **章节长度**: 问题分析/模型章<2000字→P0，其他核心章<500字→P1。\n" +
        "10. **内部流程术语检查**: 正文是否出现「对抗性审查」「模型重设计」「adversarialFindings」「验证器」「重设计历史」等内部流程字样？出现→P1（必须改写为论文语言，如「进一步分析表明…」）。\n" +
        "11. **推导链检查**: 模型/分析章的关键公式是否是「动机→推导→含义」三步（从定义/事实出发、有中间步骤、说明式子含义），还是直接甩最终公式加一句说明？发现「定义式」写法→P1。\n" +
        "12. **术语堆砌/可读性**: 段落中是否堆砌未解释的术语（一段超过 3 个）、句子是否冗长绕口、是否有凑字数铺垫（「值得注意的是」「综上所述」「本文系统地」等）？违规→P1（要求精简改写）。\n" +
        (subQuestions && subQuestions.length > 0 ? "13. **逐问覆盖**: 问题分析/模型/分析/结论各章是否都覆盖了所有子问题？每个子问题的机理分析/模型/求解/结果是否都有呈现？缺失→P0。\n\n" : "\n") +
        "输出格式：每个问题一行 `[severity:P0/P1/P2] [章节名] 问题描述 | 修复建议`。\n纯文本。" + ctx.saveToFile("05-writing/cross-review-r" + writingRound + ".txt"),
        { label: "cross-review-r" + writingRound, phase: "写作" }
      ),
      // 评委视角审查
      ...(writingRound < MAX_WRITING_ROUNDS ? [() => agent(
        "## 评委视角审查 (第" + writingRound + "轮)\n\n" +
        "你是数模评委，读了100篇同题论文。快速扫读以下论文后回答：\n\n" +
        "## 论文\n" + paperSections.map(s => "## " + s.section + "\n" + (s.content || "").slice(0, 2500)).join("\n\n") + "\n\n" +
        "## 评估\n" +
        "1. **结构**: 章节顺序合理吗？有没有前言不搭后语？结论放对位置了吗？\n" +
        "2. **可读性**: 读完知道创新是什么吗？还是得自己找？**是否像技术白皮书/说明书（术语堆砌、直接甩公式、啰嗦铺垫）？**是→P1。\n" +
        "3. **数字可信度**: 摘要/正文里的数字有推导支撑吗？还是看起来像编的？\n" +
        "4. **最大弱点**: 哪个问题最影响评分？（具体说，不要废话）\n" +
        "5. **一句话建议**: 改什么最提升竞争力？\n\n" +
        "输出纯文本，坦诚直接。每行一个问题格式：`[severity] 问题 | 建议`。" + ctx.saveToFile("05-writing/judge-review-r" + writingRound + ".txt"),
        { label: "judge-review-r" + writingRound, phase: "写作" }
      )] : []),
    ]), "写作-review")

    const crossText = typeof crossReview === "string" ? crossReview : ""
    const judgeText = typeof judgeReview === "string" ? judgeReview : ""

    const p0Matches = (crossText + "\n" + judgeText).match(/\[P0\]/g) || []
    const allIssueLines = (crossText + "\n" + judgeText).split("\n").filter(l => /\[P[0-2]\]/.test(l))
    const currentP0Count = p0Matches.length
    crossSectionReview = crossText + "\n\n=== 评委视角 ===\n" + judgeText

    const reviewProduced = (crossText + judgeText).trim().length > 0
    if ((allIssueLines.length === 0 || (currentP0Count === 0 && writingRound > 1)) && reviewProduced) {
      writingDry++
      log("[Phase 7/8] 审查 r" + writingRound + ": 0 个新问题 (dry=" + writingDry + "/2)")
    } else if (!reviewProduced) {
      logError(ErrorLevel.WARNING, "写作", "审查 r" + writingRound + " 无有效产出（审查 agent 失败），不累计 dry（防止假收敛）")
    } else {
      if (currentP0Count >= prevWritingP0Count) {
        writingDry = 0
      }
      prevWritingP0Count = currentP0Count
      log("[Phase 7/8] 审查 r" + writingRound + ": " + allIssueLines.length + " 个问题 (P0=" + currentP0Count + ")")
    }

    if (writingDry >= 2 || (allIssueLines.length === 0 && writingRound >= 2)) {
      log("[Phase 7/8] 写作审查收敛 (dry=" + writingDry + ")，跳过修复")
      break
    }
    if (writingRound >= MAX_WRITING_ROUNDS) {
      log("[Phase 7/8] 已达最大写作审查轮数(" + MAX_WRITING_ROUNDS + ")，执行最终 P0 修复")
      const combinedIssues = crossText + "\n" + judgeText
      const p0Lines = combinedIssues.split("\n").filter(l => /\[P0\]/.test(l))
      if (p0Lines.length > 0) {
        const p0Only = p0Lines.join("\n")
        let fixedCount = 0
        for (let fi = 0; fi < paperSections.length; fi++) {
          const s = paperSections[fi]
          const allCurrent = paperSections.map(ps => "### " + ps.section + "\n" + (ps.content || "").slice(0, 1200)).join("\n\n")
          const fixed = await agent(
            "## 最终 P0 修复: " + s.section + "\n\n" +
            "## 【最终事实源表】（数字唯一权威，修复前先 `Read` `" + intermediatesDir + "/07-fact-sheet.json`）\n\n" +
            "## 你的章节内容\n" + (s.content || "").slice(0, 5000) + "\n\n" +
            "## ⚠️ 只修复这些 P0 问题（其他忽略）\n" +
            p0Only.slice(0, 6000) + "\n\n" +
            "## ✅ 全篇其他章节当前内容（修复时保持与全篇一致）\n" +
            allCurrent.slice(0, 12000) + "\n\n" +
            "## 修复要求\n" +
            "只修复 P0 问题。这是最后一轮，不做大改——精准修复，不重写章节。\n" +
            "数字以事实源表为准，其他章节已统一的口径不得破坏。\n" +
            "输出修改后的完整 content。Structured output only.",
            { label: "final-fix:" + s.id, phase: "写作", schema: PAPER_SECTION_SCHEMA }
          )
          if (fixed) { paperSections[fi] = fixed; fixedCount++ }
        }
        log("最终 P0 修复完成: " + fixedCount + "/" + paperSections.length + " 个章节已顺序更新")
      }
      break
    }

    // 修复 —— 顺序主编统一修复（单主编视角：每个修复 agent 看到全篇+事实源表+全部问题，
    // 且能查看前面已修复章节的最新内容，保证跨章节同步修改、杜绝"这章改了那章没改"的版本分叉）
    const combinedIssues = crossText + "\n" + judgeText
    let fixedCount = 0
    for (let fi = 0; fi < paperSections.length; fi++) {
      const s = paperSections[fi]
      const allCurrent = paperSections.map(ps => "### " + ps.section + "\n" + (ps.content || "").slice(0, 1500)).join("\n\n")
      const fixed = await agent(
        "## 章节统一修复: " + s.section + " (第" + writingRound + "轮, " + (fi + 1) + "/" + paperSections.length + ")\n\n" +
        "## 【最终事实源表】（数字的唯一权威；修复前先 `Read` `" + intermediatesDir + "/07-fact-sheet.json`，若发现你的章节数字与它不符，以它为准）\n\n" +
        "## 你要修复的章节（当前内容）\n" + (s.content || "").slice(0, 5000) + "\n\n" +
        "## 审查发现的问题（全文问题列表，只处理与你章节相关的；涉及其他章节的问题由对应轮次处理）\n" +
        combinedIssues.slice(0, 8000) + "\n\n" +
        "## ✅ 全篇所有章节当前内容（含此前已修复的章节——修复你这一章时必须与全篇保持一致：同一符号、同一数字、同一口径；若发现其他章节与事实源表冲突，在回复的 keyPoints 中报告，不要代改）\n" +
        allCurrent.slice(0, 14000) + "\n\n" +
        "## 修复要求\n" +
        "- 只修改审查报告中指出的问题（符号、数字、逻辑衔接、创新呼应、图表引用、结构排序、**可读性/推导链/术语堆砌**）\n" +
        "- 不要重写整个章节——精准手术，不是开膛\n" +
        "- 如果某个问题不涉及你的章节，忽略它\n" +
        "- **特别注意**：如果问题涉及摘要数字无出处，要么补推导，要么删数字\n" +
        "- **数字纪律**：你的章节中所有数字必须与事实源表一致（number 字段精确匹配）；不一致的以事实源表修正\n" +
        "- **可读性问题修复口径**：术语堆砌→每个术语首次出现补一句大白话解释并精简；只贴公式→补「动机→推导→含义」；啰嗦铺垫→删除；禁止把「对抗性审查/模型重设计」等内部流程字样写进论文\n" +
        "输出修改后的完整 content。Structured output only.",
        { label: "fix:" + s.id + "-r" + writingRound, phase: "写作", schema: PAPER_SECTION_SCHEMA }
      )
      if (fixed) {
        paperSections[fi] = fixed
        fixedCount++
      }
    }
    log("修复完成 r" + writingRound + ": " + fixedCount + "/" + paperSections.length + " 个章节已顺序更新")
  }

  log("[Phase 7/8] 写作完成 ✓ — " + paperSections.length + "/" + EXPECTED_SECTION_COUNT + " 个章节, " + (narrativeOutline ? "叙事大纲 ✓" : "") + (innovationMatrix ? ", 创新矩阵 ✓" : "") + (crossSectionReview ? ", 交叉审查 ✓" : ""))

  // Store results in ctx
  ctx.paperSections = paperSections
  ctx.narrativeOutline = narrativeOutline
  ctx.innovationMatrix = innovationMatrix
  ctx.crossSectionReview = crossSectionReview
  ctx.styleGuide = styleGuide

  return { paperSections, narrativeOutline, innovationMatrix, styleGuide }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: lib/phase8-final.js
// ═══════════════════════════════════════════════════════════════

// ═══ Phase 8: 终审 — 摘要数字溯源 → 评委自评 → LaTeX 编译 ═══
// Depends on: agent(), log(), phase() — workflow globals
// Depends on: ctx.saveToFile, ctx.subQuestions


async function phase8_final(ctx) {
  const { cfg, chosenAnalysis, selection, finalModel, currentSolution, baselineResult,
          limitationAnalysis, allSources, allModels, allClaims,
          allIssues, iterationLog, innovationProposals, outputDir, codeDir, figuresDir,
          narrativeOutline, innovationMatrix, crossSectionReview,
          earlyJudgeReview, allRethinkResults, redesignHistory, allAdversarialFindings,
          subQuestions, competition, intermediatesDir } = ctx
  const currentRules = PAPER_RULES[competition] || PAPER_RULES.cumcm
  const isMcm = competition === 'mcm'

  phase("终审")
  log("[Phase 8/8] 终审开始 — 预计 8-12 分钟")

  // ── paperSections 重建：phase7 checkpoint 不存全文（太大），写作 agent 已逐节落盘，
  // 断点续跑或 phase7 checkpoint 缺失时从 intermediates/05-writing/section-*.json 重建 ──
  let paperSections = ctx.paperSections || []
  if (!paperSections || paperSections.length === 0) {
    const restored = await agent(
      "## 从磁盘重建论文章节\n\n" +
      "phase7 的章节已由写作 agent 逐节落盘到 `" + intermediatesDir + "/05-writing/` 目录。\n" +
      "1. 先 `ls " + intermediatesDir + "/05-writing/` 列出所有 section-*.json 文件\n" +
      "2. 逐个 `Read` 读取，每个文件是 {\"section\":\"章节名\",\"content\":\"...\"}\n" +
      "3. 按论文顺序排序：摘要/问题重述/问题分析/模型假设与符号说明/数据预处理与探索性分析/模型建立与求解/结果分析与验证/灵敏度与稳健性分析/模型的评价与推广/结论与改进（只取存在的）\n" +
      "4. 输出 JSON 数组 [{\"section\":\"...\",\"content\":\"...\"}, ...]，content 完整保留、不截断\n\nStructured output only.",
      { label: "restore-sections", phase: "终审",
        schema: { type: "array", items: PAPER_SECTION_SCHEMA } }
    )
    if (restored && Array.isArray(restored) && restored.length > 0) {
      paperSections = restored
      ctx.paperSections = paperSections
      log("[Phase 8/8] 从磁盘重建 " + paperSections.length + " 个章节（phase7 checkpoint 不含全文）")
    } else {
      logError(ErrorLevel.WARNING, "终审", "从磁盘重建章节失败——phase7 产出丢失，写作需要重跑（resumeFrom='phase7-writing' 或去掉 resumeFrom 重新运行）")
    }
  }

  const ABSTRACT_IDS = ["摘要", "Abstract", "Summary"]
  const abstractSection = paperSections.find(s => ABSTRACT_IDS.includes(s.section))
  let polishedAbstract = abstractSection?.content || ""
  const bodyText = paperSections.filter(s => !ABSTRACT_IDS.includes(s.section)).map(s => s.content || "").join("\n")

  // ── Step 8.0: 摘要数字溯源验证 ──
  {
    const abstractVerify = await agent(
      "## 摘要数字溯源验证\n\n" +
      formatSubQuestions(subQuestions) +
      (subQuestions && subQuestions.length > 0 ? "请逐子问题验证摘要中的每个数值声明，确认在对应子问题的章节中有出处。\n\n" : "") +
      "## 摘要\n" + polishedAbstract + "\n\n" +
      "## 正文全文\n" + bodyText.slice(0, 30000) + (bodyText.length > 30000 ? "\n（正文超过 3 万字符，以上为前 3 万字符，数字可能位于截断区之外，请结合事实源表判断）\n" : "") + "\n\n" +
      "## 任务\n" +
      "1. 从摘要中提取所有**具体数字**（百分比、数值、时间等），忽略序号和年份\n" +
      "2. 逐一在正文中搜索每个数字的出处/推导过程\n" +
      "3. 输出 JSON：{\"claims\": [{\"number\": \"11.1%\", \"context\": \"...\", \"foundInBody\": true/false, \"bodyLocation\": \"第X节 或 未找到\"}]}\n" +
      "4. 如果 foundInBody=false → 这个数字是凭空编造的，必须删除或补推导\n\n" +
      "Structured output only.",
      { label: "abstract-verify", phase: "终审",
        schema: { type: "object", required: ["claims"], properties: { claims: { type: "array", items: { type: "object", required: ["number", "foundInBody"], properties: { number: { type: "string" }, context: { type: "string" }, foundInBody: { type: "boolean" }, bodyLocation: { type: "string" } } } } } } }
    )
    if (abstractVerify) {
      const unverifiable = (abstractVerify.claims || []).filter(c => !c.foundInBody)
      if (unverifiable.length > 0) {
        log("[Phase 8/8] 摘要数字验证: " + unverifiable.length + " 个数字在正文中找不到出处! 修复...")
        const fixedAbstract = await agent(
          "## 摘要数字修复\n\n" +
          "## 当前摘要\n" + polishedAbstract + "\n\n" +
          "## 以下数字在正文中找不到出处，必须删除或替换为正文中已有的数据：\n" +
          unverifiable.map(c => "- **" + c.number + "**: " + (c.context || "无上下文")).join("\n") + "\n\n" +
          "## 正文中可用的数据（从正文提取的可靠数字）\n" +
          "如果某个数字在正文中不存在，请从以下正文片段中找最接近的可靠数据替换，或者直接删除那句声称。\n\n" +
          bodyText.slice(0, 20000) + "\n\n" +
          "输出修复后的完整摘要（纯文本，300-500字）。只删除/替换不可溯源的数字，不重写其他部分。" + ctx.saveToFile("06-final/abstract-fixed.txt"),
          { label: "abstract-fix", phase: "终审" }
        )
        if (fixedAbstract) { polishedAbstract = fixedAbstract; log("[Phase 8/8] 摘要已修复: 移除/替换了 " + unverifiable.length + " 个不可溯源数字") }
      } else {
        log("[Phase 8/8] 摘要数字验证: 全部 " + (abstractVerify.claims || []).length + " 个数字可溯源 ✓")
      }
    }
  }

  // ── Step 8.0b: 代码 stdout 数字对账 ──
  // 将摘要中的数字与代码实际运行输出的数字对比，防止 LLM 编造数字
  {
    const codeValidationResult = await agent(
      "## 代码数字对账 — 验证摘要数值来源\n\n" +
      formatSubQuestions(subQuestions) +
      "## 摘要\n" + polishedAbstract + "\n\n" +
      "## 代码目录\n`" + codeDir + "/`\n\n" +
      "## 输出目录\n`" + outputDir + "/`\n\n" +
      "## 任务\n\n" +
      "### 步骤 1: 查找并运行代码\n" +
      "1. 列出 `" + codeDir + "/` 目录中的 .py 文件\n" +
      "2. 优先使用 `solution_final_fix.py`，没有则使用最新的 `solution_v*.py`（按版本号排序取最大）\n" +
      "3. 如果找到代码，运行：\n" +
      "   ```bash\n" +
      "   cd " + outputDir + " && python3 <代码文件> > logs/stdout_for_validation.log 2>&1\n" +
      "   ```\n" +
      "   用 `run_in_background: true` 后台跑，每 10 秒检查日志，最长等 15 分钟。\n" +
      "4. 读取 `logs/stdout_for_validation.log` 获取 stdout 内容\n\n" +
      "### 步骤 2: 提取数值\n" +
      "从 stdout 中提取所有数值（正则模式：`=?\s*-?\d+\.?\d*[eE]?[+-]?\d*`）\n" +
      "记录每个数值的上下文（它前面的 30 个字符用于标识）\n\n" +
      "### 步骤 3: 与摘要对比\n" +
      "从摘要中提取所有数值（排除序号如 1. 2. 3. 和年份如 2025）\n" +
      "逐一检查：\n" +
      "- 该数值是否出现在代码 stdout 中？\n" +
      "- 出现在 stdout 中但值不同？\n" +
      "- 未出现在 stdout 中？\n\n" +
      "### 步骤 4: 输出差异报告\n" +
      "输出 JSON：{\n" +
      '  "codeStdoutNumbers": ["数值列表"],\n' +
      '  "abstractNumbers": [{"number": "...", "context": "..."}],\n' +
      '  "mismatches": [{"abstractNumber": "...", "codeNumber": "...", "fixAction": "use_stdout|verify_in_body"}],\n' +
      '  "missingInStdout": ["摘要中有但 stdout 中没有的数值"],\n' +
      '  "diffReportPath": "' + outputDir + '/logs/abstract-vs-code-diff.json"\n' +
      "}\n\n" +
      "### 步骤 5: 处理差异\n" +
      "- 对于摘要中存在但 stdout 中不存在的数字 → fixAction='verify_in_body'，标记为 suspicious\n" +
      "- 对于摘要和 stdout 都存在但值不一致的数字 → fixAction='use_stdout'，以 stdout 为准\n\n" +
      "### 错误处理\n" +
      "- 如果代码文件不存在或运行失败（依赖缺失、语法错误等），输出 {\"error\": \"代码无法运行\", \"fallback\": true} 并使用纯文本溯源结果\n\n" +
      "Structured output only.",
      { label: "code-number-audit", phase: "终审",
        schema: { type: "object", required: ["codeStdoutNumbers", "abstractNumbers", "mismatches", "missingInStdout"],
          properties: {
            codeStdoutNumbers: { type: "array", items: { type: "string" } },
            abstractNumbers: { type: "array", items: { type: "object", properties: { number: { type: "string" }, context: { type: "string" } } } },
            mismatches: { type: "array", items: { type: "object", properties: { abstractNumber: { type: "string" }, codeNumber: { type: "string" }, fixAction: { enum: ["use_stdout", "verify_in_body"] } } } },
            missingInStdout: { type: "array", items: { type: "string" } },
            error: { type: "string" },
            fallback: { type: "boolean" },
            diffReportPath: { type: "string" },
          }
        }
      }
    )

    if (codeValidationResult && !codeValidationResult.fallback) {
      if (codeValidationResult.mismatches && codeValidationResult.mismatches.length > 0) {
        const fixInstructions = []
        for (const m of codeValidationResult.mismatches) {
          if (m.fixAction === "use_stdout") {
            fixInstructions.push("- 摘要中的 " + m.abstractNumber + " 与代码 stdout 中的 " + m.codeNumber + " 不一致，已修正为 " + m.codeNumber)
          } else if (m.fixAction === "verify_in_body") {
            fixInstructions.push("- 摘要中的 " + m.abstractNumber + " 未在代码 stdout 中出现，请在正文中找推导过程")
          }
        }

        if (fixInstructions.length > 0) {
          const fixedAbstract = await agent(
            "## 摘要数字修正（基于代码 stdout 对账）\n\n" +
            "## 当前摘要\n" + polishedAbstract + "\n\n" +
            "## 修正清单\n" + fixInstructions.join("\n") + "\n\n" +
            (codeValidationResult.missingInStdout && codeValidationResult.missingInStdout.length > 0
              ? "## 以下数字在代码 stdout 中未找到，请基于正文中可用的数据替换或删除\n" +
                "正文片段（供参考）：\n" + bodyText.slice(0, 15000) + "\n\n"
              : "") +
            "输出修复后的完整摘要（纯文本，300-500字）。" + ctx.saveToFile("06-final/abstract-code-verified.txt"),
            { label: "abstract-code-fix", phase: "终审" }
          )
          if (fixedAbstract) { polishedAbstract = fixedAbstract; log("[Phase 8/8] 摘要已根据代码 stdout 修正") }
        }
      } else {
        log("[Phase 8/8] 代码数字对账: 全部摘要数值与 stdout 一致 ✓")
      }
    } else if (codeValidationResult && codeValidationResult.fallback) {
      log("[Phase 8/8] 代码数字对账降级：代码无法运行，使用纯文本溯源结果")
    }
  }

  // ── Step 8.1: 替换 paperSections 中的摘要 → 构建全文 ──
  if (abstractSection) {
    abstractSection.content = polishedAbstract
  }
  const fullPaperMdBody = paperSections.map(s => "## " + s.section + "\n\n" + (s.content || "")).join("\n\n---\n\n")

  // ── Step 8.2: 评委终审 ──
  const judgeFinalReview = await agent(
    "## 评委视角终审\n\n" +
    "你是数学建模竞赛评委，已读了100篇同题论文。读完以下论文后回答：\n\n" +
    "## 论文\n" + fullPaperMdBody.slice(0, 25000) + "\n\n" +
    (subQuestions && subQuestions.length > 0 ? "本题包含" + subQuestions.length + "个子问题。评估时检查每个子问题是否都得到了充分解答。\n\n" : "") +
    "## 问题\n" +
    "1. 这篇和另外100篇摆在一起，我为什么会对它**有印象**？（找不到就说无，建议在哪里做深/做奇创造记忆点）\n" +
    "2. 创新是否真实可信？还是看起来像硬贴的？\n" +
    "3. 最大弱点是什么？（不能是废话，要具体的）\n" +
    "4. 修改**哪一个**东西能最大程度提升竞争力？\n\n" +
    "返回纯文本，坦诚直接。" + ctx.saveToFile("06-final/judge-review.txt"),
    { label: "judge-review", phase: "终审" }
  )

  // ── C4 修复：评委最大弱点 → 一次限定的最终修复轮（1 轮，防无界）──
  if (judgeFinalReview && paperSections && paperSections.length > 0) {
    const judgeFix = await agent(
      "## 评委意见最终修复（限 1 轮）\n\n" +
      "## 评委意见\n" + String(judgeFinalReview).slice(0, 4000) + "\n\n" +
      "## 任务\n" +
      "针对评委指出的最大弱点与提升建议，对**相关章节**做最小改动修复。硬性约束：\n" +
      "- 数字必须以最终事实源表为准，**不得新造或改写数字**；只改表述、结构、遗漏的推导\n" +
      "- 只输出实际改动的章节，未改的不要输出\n\n" +
      "输出 JSON：{\"sections\":[{\"section\":\"<章节名，与现有一致>\",\"content\":\"<修复后完整章节内容>\"}]}\n\n" +
      "Structured output only.",
      { label: "judge-fix", phase: "终审",
        schema: { type: "object", required: ["sections"], properties: { sections: { type: "array", items: { type: "object", required: ["section", "content"], properties: { section: { type: "string" }, content: { type: "string" } } } } } } }
    )
    if (judgeFix && Array.isArray(judgeFix.sections) && judgeFix.sections.length > 0) {
      let applied = 0
      for (const fix of judgeFix.sections) {
        const idx = paperSections.findIndex(s => s.section === fix.section)
        if (idx >= 0) { paperSections[idx].content = fix.content; applied++ }
      }
      const absIdx = paperSections.findIndex(s => ABSTRACT_IDS.includes(s.section))
      if (absIdx >= 0 && paperSections[absIdx].content !== polishedAbstract) {
        polishedAbstract = paperSections[absIdx].content
      }
      log("[Phase 8/8] 评委修复已应用 " + applied + "/" + judgeFix.sections.length + " 个章节")
    } else {
      log("[Phase 8/8] 评委未给出可应用修复（或无需改动）")
    }
  }

  // ═══ P0-2 修复：CUMCM 组装前把内存中的修复（交叉审查/摘要/代码对账）写回磁盘 ═══
  // MCM 路径从内存拼接 tex，无需落盘。
  if (!isMcm && paperSections && paperSections.length > 0) {
    await syncSectionsToDisk(ctx, paperSections)
  }

  // ═══ LaTeX 编译与输出 ═══
  let finalTex = ""
  let texFilePath = ""
  let pdfFilePath = ""

  // ═══ Return-value builders ═══
  const buildMetadata = (format) => ({
    problem: selection?.selected, approach: finalModel?.approach,
    iterations: iterationLog ? iterationLog.length : 0,
    totalIssues: allIssues ? allIssues.length : 0,
    criticalIssues: allIssues ? allIssues.filter(i => i.severity === "critical").length : 0,
    sections: paperSections.length,
    format,
    baselineComparison: baselineResult ? { significance: baselineResult.significance, summary: baselineResult.summary } : null,
  })
  const buildDetails = () => ({
    analyses: ctx.analyses, selection,
    sources: allSources ? allSources.map(s => ({ url: s.url, quality: s.sourceQuality, modelCount: (s.models || []).length })) : [],
    finalModel, solution: currentSolution, allIssues, iterationLog,
    limitationAnalysis: typeof limitationAnalysis === "string" ? limitationAnalysis : null,
    baselineResult,
    narrativeOutline: typeof narrativeOutline === "string" ? narrativeOutline : null,
    crossSectionReview: typeof crossSectionReview === "string" ? crossSectionReview : null,
    earlyJudgeReview: typeof earlyJudgeReview === "string" ? earlyJudgeReview : null,
    consistencyIssues: [],
    formatNotes: null,
    judgeReview: typeof judgeFinalReview === "string" ? judgeFinalReview : null,
  })
  const buildStats = () => ({
    problemsAnalyzed: ctx.analyses ? ctx.analyses.length : 0,
    sourcesFetched: allSources ? allSources.length : 0,
    modelsReferenced: allModels ? allModels.length : 0,
    proposalsGenerated: innovationProposals ? innovationProposals.length : 0,  // 现为单一建模方案（length 恒 1）
    solveIterations: iterationLog ? iterationLog.length : 0,
    issuesFound: allIssues ? allIssues.length : 0,
    sectionsWritten: paperSections.length,
    baselineMetrics: baselineResult?.metrics?.length || 0,
  })

  // ── LaTeX 路径 ──
  const TITLE = selection?.selected
    ? (isMcm
      ? "MCM/ICM Problem " + selection.selected
      : "全国大学生数学建模竞赛" + selection.selected + "题")
    : (isMcm ? "MCM/ICM Mathematical Modeling Paper" : "数学建模论文")

  const preamble = isMcm
    ? [
        "\\documentclass[12pt,letterpaper]{article}",
        "\\usepackage{amsmath,amssymb,amsthm}",
        "\\usepackage{graphicx,float}",
        "\\usepackage{booktabs,array,multirow}",
        "\\usepackage{geometry}",
        "\\geometry{top=1in,bottom=1in,left=1in,right=1in}",
        "\\usepackage{fancyhdr}",
        "\\pagestyle{fancy}",
        "\\fancyhf{}",
        "\\fancyfoot[C]{\\thepage}",
        "\\renewcommand{\\headrulewidth}{0pt}",
        "\\usepackage{hyperref}",
        "\\hypersetup{colorlinks=true,linkcolor=black,citecolor=black,urlcolor=black}",
        "\\usepackage{cite}",
        "\\usepackage{listings}",
        "\\lstset{basicstyle=\\ttfamily\\small,breaklines=true,frame=single,numbers=left}",
        "\\usepackage[titletoc]{appendix}",
        "",
        "\\date{}",
        "",
        "\\begin{document}",
        "",
        "% --- CUMC 2025: 摘要专用页为第一页，标题+摘要+关键词（无需英文翻译）---",
        "\\setcounter{page}{1}",
        "\\begin{center}",
        "{\\large \\textbf{" + TITLE + "}}",
        "\\end{center}",
        "\\vspace{0.5cm}",
        "",
      ].join("\n")
    : [
        "\\documentclass[12pt,a4paper]{ctexart}",
        "\\usepackage{amsmath,amssymb,amsthm}",
        "\\usepackage{graphicx,float}",
        "\\usepackage{booktabs,array,multirow}",
        "\\usepackage{geometry}",
        "\\geometry{top=2.5cm,bottom=2.5cm,left=2.5cm,right=2.5cm}",
        "\\usepackage{fancyhdr}",
        "\\pagestyle{fancy}",
        "\\fancyhf{}",
        "\\fancyfoot[C]{\\thepage}",
        "\\renewcommand{\\headrulewidth}{0pt}",
        "\\usepackage{hyperref}",
        "\\hypersetup{colorlinks=true,linkcolor=black,citecolor=black,urlcolor=black}",
        "\\usepackage{cite}",
        "\\usepackage{listings}",
        "\\lstset{basicstyle=\\ttfamily\\small,breaklines=true,frame=single,numbers=left}",
        "\\usepackage[titletoc]{appendix}",
        "",
        "\\date{}",
        "",
        "\\begin{document}",
        "",
        "% --- CUMC 2025: 摘要专用页为第一页，标题+摘要+关键词（无需英文翻译）---",
        "\\setcounter{page}{1}",
        "\\begin{center}",
        "{\\large \\textbf{" + TITLE + "}}",
        "\\end{center}",
        "\\vspace{0.5cm}",
        "",
      ].join("\n")

  const bodySections = paperSections
    .filter(s => !ABSTRACT_IDS.includes(s.section))
    .map(s => s.content || "")
    .join("\n\n")

  const kwMatch = polishedAbstract.match(/关键词[：:]\s*(.+?)(?:\n|$)/s)
  const keywords = isMcm ? "" : (kwMatch ? kwMatch[1].trim() : "")
  const abstractBody = (keywords && !isMcm) ? polishedAbstract.replace(/关键词[：:]\s*.+$/s, "").trim() : polishedAbstract

  let texContent
  let abstractBlock
  let appendixHeader
  let texPreambleBody

  if (isMcm) {
    abstractBlock = (
      "\\section*{Summary}\n" + abstractBody + "\n\n" +
      "\\textbf{Note:} This paper is limited to 25 pages (excluding Summary Sheet, references, and appendix).\n\n"
    )
    appendixHeader = (
      "\n\n\\newpage\n" +
      "\\begin{appendices}\n" +
      "\\section{Figures}\n" +
      "All figures generated during modeling, organized by sub-problem.\n\n" +
      "\\section{Source Code}\n" +
      "Complete runnable source code used for modeling and solving (MCM/ICM policy requires including all code).\n\n"
    )
    texContent = (
      preamble +
      abstractBlock +
      bodySections +
      "\n\n\\newpage\n" +
      "\\begin{appendices}\n" +
      "\\section{Figures}\n" +
      "All figures generated during modeling, organized by sub-problem.\n\n" +
      "\\section{Source Code}\n" +
      "Complete runnable source code used for modeling and solving (MCM/ICM policy requires including all code).\n\n" +
      "\\end{appendices}\n" +
      "\\end{document}\n"
    )
    texPreambleBody = preamble + abstractBlock + bodySections
  } else {
    // CUMCM: 使用 skill 模板组装（templates/cumcm-paper.tex + assemble_from_template.py）
    // 模板内置 2026-08 实战经验：摘要 \section*（无 abstract 环境，避免双摘要）、
    // 章节标题居中、参考文献单标题（thebibliography 自带标题）、附录 A/B/C 字母编号、
    // 代码彩色样式 pythonstyle、bm 加粗、支撑材料清单真实模板。
    // 组装在 compile agent 的第 0.5 步执行（提取 cite 键 → 生成参考文献 → 跑组装脚本）。
    abstractBlock = ""   // 由模板组装处理
    appendixHeader = ""  // 由模板组装处理
    texContent = null    // 由 compile agent 调用组装脚本生成（非内联拼接）
    texPreambleBody = "（模板组装：见编译步骤第0.5步）"
  }

  texFilePath = outputDir + "/paper/paper.tex"

  const compileResult = await agent(
    "## LaTeX 排版编译\n\n" +
    (SKILL_DOCS ? "> ⚠️ 规范真源：完整 CUMCM 格式 / 模板要点在 `" + SKILL_DOCS + "` 的「§三 CUMCM 格式」「§四 论文模板要点」，需要完整要求时先 `Read` 对应章节；本 prompt 已列出关键 LaTeX 约束。\n\n" : "") +
    "## 任务\n" +
    "你的任务是将论文写入 .tex 文件并编译，**不要尝试在回复中评估或摘要论文内容**。" +
    "使用 Write 工具分块写入。\n\n" +

    "### 第0步：清理章节内容（写入前必做）\n" +
    "在写入 .tex 之前，检查各章节内容，删除以下不应出现在最终论文中的内容：\n" +
    "- Agent 调试笔记（如「修复完成」「已对…应用以下修改」「P0/P1/P2:」「【P0:…】」等）\n" +
    "- 文件路径引用（如「文件已保存至…」）\n" +
    "- Markdown 表格或对账清单（如「数字修正清单对账」「| 摘要中原值 | 代码 stdout 值 |」等）\n" +
    "- 重复的摘要文本（abstract 之后的正文开头不应再次出现摘要全文）\n" +
    "- 任何看起来像 Agent 间通信内容而非论文正文的文字\n" +
    "- 章节内容中自带的 thebibliography 环境（参考文献统一由组装步骤生成，章节内出现必须删除）\n" +
    "清理后的 body 只保留论文章节内容。\n\n" +
    (isMcm
      ? "### 第1步：写入 preamble + 正文 body（MCM 手动拼接）\n" +
        "先用 `mkdir -p " + outputDir + "/paper` 创建目录，" +
        "然后用 Write 工具将以下 LaTeX 源码写入 `" + texFilePath + "`：\n\n" +
        "```latex\n" + texPreambleBody + "\n```\n" +
        (texPreambleBody.length > 40000
          ? "\n**注意**：内容完整，直接写入文件，不要在上下文中评估全文。确保所有内容都被写入（可以用 Write 分块，或检查文件大小）。\n\n"
          : "\n") +
        "### 第2步：验证 body 完整性\n" +
        "读取 `" + texFilePath + "` 的最后几行，确认最后一段没有在公式中间截断" +
        "（不以 `$`、`\\[`、`\\begin{...}` 等未闭合的环境结尾）。" +
        "如果文件内容完整，继续下一步。\n\n" +
        "### 第3步：追加附录头\n" +
        "用 Bash append 将以下 appendix header 追加到 `" + texFilePath + "`：\n\n" +
        "```bash\ncat >> " + texFilePath + " << 'APPEOF'\n" + appendixHeader + "APPEOF\n```\n\n"
      : "### 第0.5步：用 skill 模板组装（CUMCM，不要手工拼接 preamble）\n" +
        "使用模板组装脚本生成 `" + texFilePath + "`（模板已内置全部规范：摘要节、标题居中、参考文献单标题、附录 A/B/C、代码彩色样式、bm 加粗）：\n" +
        "1. **提取引用键**：`grep -ho '\\\\cite{[^}]*}' " + intermediatesDir + "/05-writing/section-*.json 2>/dev/null | grep -o '{[^}]*}' | tr -d '{}' | tr ',' '\\n' | sort -u`\n" +
        "2. **生成参考文献**：为每个键生成规范 bibitem（中文文献：作者.题名.刊名,年份,卷(期):页码；英文同理；AI 工具键 `ai_tool` 固定用：AI工具使用声明：大语言模型辅助写作工具（Claude, 版本2026, Anthropic公司, 使用日期2026-08）[Z]. 使用详情见支撑材料《AI工具使用详情》。），包进 \\\\begin{thebibliography}{N}...\\\\end{thebibliography}，写入 /tmp/refs.tex\n" +
        "3. **运行组装**：\n" +
        "```bash\nmkdir -p " + outputDir + "/paper\n" +
        "TPL_DIR=\"" + templateDir + "\"\n" +
        "if [ -z \"$TPL_DIR\" ]; then\n" +
        "  TPL_DIR=\"$(ls -d ~/.dsh/skills/math-model/templates ~/.claude/skills/math-model/templates 2>/dev/null | head -1)\"\n" +
        "fi\n" +
        "if [ -z \"$TPL_DIR\" ]; then echo \"ERROR: 找不到 math-model 模板目录，请在 args.templateDir 传入\"; exit 1; fi\n" +
        "python3 \"$TPL_DIR/assemble_from_template.py\" \\\n" +
        "  --template \"$TPL_DIR/cumcm-paper.tex\" \\\n" +
        "  --sections " + intermediatesDir + "/05-writing \\\n" +
        "  --output " + texFilePath + " \\\n" +
        "  --title \\\"" + TITLE + "\\\" \\\n" +
        "  --paper-title \\\"<从题目原文提取的论文题目，如：基于数据的异常行为识别与优化建议>\\\" \\\n" +
        "  --subtitle \\\"<一句话方法名副标题>\\\" \\\n" +
        "  --references \\\"$(cat /tmp/refs.tex)\\\" \\\n" +
        "  --code-dir " + codeDir + " \\\n" +
        "  --materials \\\"\\\\item 求解程序（完整可运行，位于支撑材料 code/ 目录）\\\" \\\n" +
        "  --materials \\\"\\\\item 结果数据（results.json 等，位于 data/ 目录）\\\" \\\n" +
        "  --materials \\\"\\\\item 图表文件（位于 figures/ 目录，均在正文引用）\\\" \\\n" +
        "  --materials \\\"\\\\item AI工具使用详情（AI 工具使用详情.pdf，按《全国大学生数学建模竞赛人工智能工具使用规定》第4(2)条要求）\\\" \\\n" +
        "  --materials \\\"\\\\item 赛题原始数据由竞赛提供，按规范第十一条不包含在支撑材料中；全部结果可由上述源程序直接复算\\\"\n```\n" +
        "   如果存在疑似名单数据（`" + outputDir + "/data/suspect_lists.json`），追加 `--suspect-json " + outputDir + "/data/suspect_lists.json`。\n" +
        "4. **组装后检查**：`grep -n 'section*{摘' " + texFilePath + "` 确认摘要用 `\\\\section*`（无编号）；`grep -c 'begin{thebibliography}' " + texFilePath + "` 必须为 1（单一参考文献）；`grep -n 'appendix' " + texFilePath + "` 确认附录从 \\\\appendix 开始（A/B/C 编号）。\n" +
        "5. **章节名兼容**：若组装脚本报「未找到章节」，用 `ls " + intermediatesDir + "/05-writing/` 核对 section-*.json 的 section 名（脚本按 摘要/问题重述/问题重述与分析/问题分析/模型假设与符号说明/模型假设与符号/数据预处理与探索性分析/模型建立与求解/结果分析与验证/灵敏度与稳健性分析/模型的评价与推广/结论与改进 顺序匹配；不匹配时把 JSON 的 section 字段改为脚本期望名）。\n\n") +

    (isMcm
      ? "### 第3.5步：嵌入图表到附录\n" +
        "在写入源程序代码之前，先嵌入图表。\n" +
        "1. 列出 `" + figuresDir + "` 目录中的所有 .png/.pdf 文件：`ls " + figuresDir + "`\n" +
        "2. 按子问题分类（文件名含 Q1/Q2/Q3/cross），将每个图片用以下格式嵌入附录的 Figures 节：\n" +
        "   ```latex\n" +
        "   \\begin{figure}[H]\n" +
        "     \\centering\n" +
        "     \\includegraphics[width=0.9\\textwidth]{" + figuresDir + "/fig_xxx.png}\n" +
        "     \\caption{图片描述——根据文件名推断内容}\n" +
        "   \\end{figure}\n" +
        "   ```\n" +
        "   ⚠️ **附录图表必须用 `[H]`（强制就位）**，禁止用 `[htbp]`。附录图表数量多（>10张）时连续 `[htbp]` 会导致浮动体堆积丢失。正文图表仍用 `[htbp]`。需要 `\\usepackage{float}`（已在 preamble 中包含）。\n" +
        "   ⚠️ **子问题图表数量 >5 时，每 4-5 张图后插入 `\\clearpage`** 防止同子问题内浮动体堆积。\n" +
        "3. 用 Write 工具将图表 LaTeX 追加到 `" + texFilePath + "`（在 `\\section{Figures}` 之后、`\\section{Source Code}` 之前）。\n" +
        "   ⚠️ **严禁向摘要区域插入图表**：任何自动化编辑 paper.tex 的操作必须验证插入位置不在 `\\begin{abstract}...\\end{abstract}` 范围内。曾因脚本匹配关键词时未做上下文检查，将图表误插入摘要内部→图片出现在论文第一页。\n" +
        "4. 如果 `" + figuresDir + "` 目录为空或不存在，在对应节中写「No figures were used.」\n\n" +
        "### 第4步：嵌入源程序代码（MCM）\n" +
        "从 `" + codeDir + "` 目录读取所有 .py/.m/.jl 源程序文件，" +
        "将其内容嵌入附录 `\\section{Source Code}` 中。" +
        " 每个文件用一个 `\\subsection{文件名}` + `\\begin{lstlisting}...\\end{lstlisting}`。" +
        " 如果目录为空或没有代码文件，在附录中写\"No source code was used in this paper.\"（MCM/ICM 规范要求）。" +
        " 用 Write 工具追加到 `" + texFilePath + "`。\n\n" +
        "### 第5步：结束文件（MCM）\n" +
        "用 Bash 追加末尾标签：\n" +
        "```bash\n" +
        "echo '\\end{appendices}' >> " + texFilePath + "\n" +
        "echo '\\end{document}' >> " + texFilePath + "\n" +
        "```\n\n"
      : "### 第3.5-5步（CUMCM）\n" +
        "跳过：模板组装已包含附录图表、代码附录与结尾标签。若正文需要补充附录图表，直接编辑 `" + texFilePath + "` 在对应附录节内插入 `\\begin{figure}[H]...\\end{figure}`（附录用 [H]，正文用 [htbp]）。\n\n") +

    "### 第6步：编译（两遍 xelatex：第一遍生成交叉引用与目录，第二遍解析；必须两遍都通过）\n" +
    "```bash\ncd " + outputDir + " && xelatex -interaction=nonstopmode -file-line-error paper.tex 2>&1 | tail -60 && xelatex -interaction=nonstopmode -file-line-error paper.tex 2>&1 | tail -60\n```\n\n" +

    "### 第7步：错误修正与重试\n" +
    "如果出现 LaTeX 错误，分析错误原因并修正 .tex 文件，然后重新编译。最多重试 " + cfg.latexMaxRetries + " 次。\n\n" +
    "常见 LaTeX 错误及修复方法：\n" +
    "   - `Undefined control sequence` → 命令拼写错误或缺少 \\usepackage\n" +
    "   - `Missing $ inserted` → 数学符号（_ ^ \\alpha 等）需在数学模式中使用\n" +
    "   - `Missing \\endgroup` → 环境未正确闭合\n" +
    "   - `File not found` → \\includegraphics 引用的图片路径不正确\n" +
    "   - " + (isMcm ? "Special chars in code (_, ^, %, &)" : "中文显示为乱码") + " → " + (isMcm ? "ensure listings basicstyle=\\ttfamily handles special chars" : "确保使用 ctexart 文档类，用 xelatex 编译") + "\n" +
    "   - 附录中代码含特殊字符（_ ^ % & 等）→ 用 listings 的 `basicstyle=\\ttfamily` 可避免大部分问题\n\n" +

    "### 第8步：输出\n" +
    "返回：最终编译状态、PDF 是否成功生成、如有残留 warning 也列出来。" + ctx.saveToFile("08-compile-result.txt"),
    { label: "compile", phase: "终审" }
  )

  pdfFilePath = outputDir + "/paper/paper.pdf"
  log("[Phase 8/8] 终审完成 ✓ — 摘要数字验证通过, 代码数字对账完成, LaTeX 编译完成 → " + pdfFilePath)

  finalTex = texContent

  return {
    paper: finalTex,
    texPath: texFilePath,
    pdfPath: pdfFilePath,
    compileResult: typeof compileResult === "string" ? compileResult : "",
    metadata: buildMetadata("latex"),
    details: buildDetails(),
    stats: buildStats(),
  }
}


// ═══════════════════════════════════════════════════════════════
// INLINED: math-model.js main body (cfg onward)
// ═══════════════════════════════════════════════════════════════

// ═══ Strategy config ═══
const cfg = {
  searchAngles: 4, maxFetch: 8,
  dryThreshold: QUICK_MODE ? 1 : 3, maxIterations: QUICK_MODE ? 3 : 6,
  sectionPreset: "full",  // 仅 full 生效（compact/standard 已移除）
  latexMaxRetries: 5,
  rethinkThreshold: 3,
  contextBudget: 30000,
}

// ═══ Innovation threshold mapping ═══
const _hasArgs = typeof args === "object";  // MOVED UP to fix TDZ bug
const INNOVATION_STRICTNESS = (_hasArgs && args.innovationStrictness) || 'standard' // 'strict' | 'standard' | 'loose'
const INNOVATION_STRICTNESS_THRESHOLDS = {
  strict:  { threshold: 0.10, label: 'strict',  desc: '≥10% 才算有意义创新' },
  standard: { threshold: 0.05, label: 'standard', desc: '≥5% 才算有意义创新' },
  loose:   { threshold: 0.02, label: 'loose',   desc: '≥2% 就算有意义创新' },
}
const innovationThresholds = INNOVATION_STRICTNESS_THRESHOLDS[INNOVATION_STRICTNESS] || INNOVATION_STRICTNESS_THRESHOLDS.standard
log("创新必要性阈值: " + innovationThresholds.desc + " (innovationStrictness=" + INNOVATION_STRICTNESS + ")")

// ═══ Parse args ═══
const hasArgs = _hasArgs
const outputDir = (hasArgs && args?.outputDir) || "./math-model-output"
const templateDir = (hasArgs && args?.templateDir) || ""   // 模板目录（assemble 脚本 + cumcm-paper.tex）；空则编译 agent 自动探测
// 内部 agent 规范唯一真源：skill 自带的 docs/writing-and-format.md（templateDir 是 <skill>/templates，取其父级）
const SKILL_DOCS = templateDir ? templateDir.replace(/\/templates\/?$/, '') + '/docs/writing-and-format.md' : ''
const codeDir = outputDir + "/code"
const figuresDir = outputDir + "/figures"
let attachments = (hasArgs && args?.attachments) || []
const intermediatesDir = outputDir + "/intermediates"
const isPreSelected = !!(hasArgs && args?.selectedProblem)
const currentYear = 2026
const COMPETITION = (hasArgs && args.competition) || 'cumcm' // 'cumcm' | 'mcm'
const USER_INTERVENTION = hasArgs && args.userIntervention === true
const userFeedback = (hasArgs && args.userFeedback) || ""
// skipPhases: 字符串数组，跳过指定 phase（必须已有 checkpoint）
//   'literature' → 跳过 Phase 3（文献调研）
//   'modeling'   → 跳过 Phase 4（建模方案）
//   'baseline'   → 跳过 Phase 5-6 中的 baseline 对比部分
//   示例: { skipPhases: ['literature', 'modeling'] } 跳过文献和建模阶段
//   注意: 跳过的 phase 必须有对应 checkpoint，否则报错
const skipPhases = (hasArgs && Array.isArray(args.skipPhases)) ? args.skipPhases : []
const DRY_RUN = hasArgs && args.dryRun === true
if (DRY_RUN) {
  log("Dry-run 模式: 仅执行审题+选题阶段，输出执行计划后退出")
}

log("竞赛模式: " + (COMPETITION === 'mcm' ? 'MCM/ICM（美赛）' : 'CUMCM（国赛）') + (QUICK_MODE ? " [quick 模式：评审1轮/求解dry=1/写作1轮]" : " [full 模式]"))
log("输出: " + outputDir)

// resumeFrom: 断点续跑 — 传入已完成的 phase 名（如 'phase4-modeling'），
// 所有在该 phase 之前的 phase 将被跳过（必须已有对应 checkpoint）。
// 恢复点会自动检测 checkpoint 的存在，没有则报错提示先完整运行。
const resumeFrom = (hasArgs && args?.resumeFrom) || null
if (resumeFrom) {
  log("恢复模式: resumeFrom=" + resumeFrom + " — 将跳过已完成 phase 的检测，从指定 phase 开始")
}
if (USER_INTERVENTION) {
  log("用户干预模式: 每个 phase 完成后将产出摘要写入 intermediates/ 目录")
}
if (userFeedback) {
  log("用户反馈: 已注入——" + userFeedback.slice(0, 100) + (userFeedback.length > 100 ? "…" : ""))
}
if (skipPhases.length > 0) {
  log("跳过 phase: " + skipPhases.join(", ") + " — 必须已有对应 checkpoint")
}

// ── 输出目录结构（重试 2 次，失败才 FATAL）──
const ALL_DIRS = [
  outputDir + "/paper", outputDir + "/code", outputDir + "/figures",
  outputDir + "/data", outputDir + "/data/external", outputDir + "/logs",
  intermediatesDir,
  intermediatesDir + "/05-writing", intermediatesDir + "/06-final",
];
{
  let mkdirOk = false
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      await agent("创建所有输出目录: `mkdir -p " + ALL_DIRS.join(" ") + " && ls -d " + ALL_DIRS.join(" ") + "`", { label: "mkdir-dirs", phase: "初始化" })
      mkdirOk = true
      break
    } catch (err) {
      logError(ErrorLevel.WARNING, "初始化", "目录创建失败(attempt " + attempt + "/2): " + err.message)
      if (attempt === 2) {
        logError(ErrorLevel.FATAL, "初始化", "目录创建彻底失败，无法继续")
        throw err
      }
    }
  }
}

// ═══ S1 — 环境快速自检 ═══
const envHas = { pdftotext: false, python3: false, xelatex: false }
{
  log("--- 环境快速自检 ---")
  const envCheck = await agent(
    "运行以下三条命令检查环境并输出原始结果（不要修改格式）：\n" +
    "1. `command -v pdftotext && echo 'OK' || echo 'MISSING'`\n" +
    "2. `command -v python3 && python3 --version || echo 'MISSING'`\n" +
    "3. `command -v xelatex && echo 'OK' || echo 'MISSING'`",
    { label: "env-check", phase: "初始化" }
  )
  if (envCheck) {
    const lines = String(envCheck).trim().split('\n')
    for (const line of lines) {
      const cleaned = line.replace(/^[0-9]+\.\s*/, '').trim()
      log("  " + cleaned)
      if (cleaned.includes('pdftotext') && cleaned.includes('OK')) envHas.pdftotext = true
      if (cleaned.includes('python3') && !cleaned.includes('MISSING')) envHas.python3 = true
      if (cleaned.includes('xelatex') && cleaned.includes('OK')) envHas.xelatex = true
    }
    const allText = String(envCheck)
    if (allText.includes('MISSING')) {
      logError(ErrorLevel.WARNING, "初始化", "部分依赖缺失 — 对应功能可能受限（xelatex 缺→无 PDF；pdftotext 缺→需手动贴题；python3 缺→无法求解）")
    } else {
      log("环境检测 ✓ — 所有关键依赖就绪")
    }
  }
}

// ═══ M6 — 中文字体预检（国赛必须） ═══
if (COMPETITION === 'cumcm') {
  const fontCheck = await agent(
    "运行以下命令检查中文字体并输出原始结果：\n" +
    "`fc-list :lang=zh 2>/dev/null | head -3 || echo 'NO_FONT'`",
    { label: "font-check", phase: "初始化" }
  )
  const fontOut = String(fontCheck || '').trim()
  if (fontOut.includes('NO_FONT') || fontOut === '') {
    logError(ErrorLevel.WARNING, "初始化", "未检测到中文字体 — 国赛论文需中文字体支持。尝试自动安装...")
    const installOut = await agent(
      "尝试安装中文字体：`apt-get install -y fonts-noto-cjk 2>&1 | tail -3 || echo 'NEED_SUDO'`",
      { label: "font-install", phase: "初始化" }
    )
    if (String(installOut || '').includes('NEED_SUDO')) {
      log("  需要手动安装: sudo apt install fonts-noto-cjk")
    }
  } else {
    log("中文字体检测 ✓ — 已安装")
  }
}

// ═══════════════════════════════════════════
// Phase 1-2: 审题 + 选题 (skip if pre-selected)
// ═══════════════════════════════════════════

let chosenAnalysis, selection, analyses

if (isPreSelected) {
  // Pre-selected by skill — use the provided analysis directly
  phase("审题+选题")
  log("[Phase 1-2/8] 审题+选题开始 — 使用预选结果")

  // 文档即共享：Stage 1（提纯/审题/选题）产物优先从落盘的 intermediates/00-problem.json 读取，
  // 文件是唯一权威（主 agent 按 SKILL.md Step 5 提前落盘，可预先审查）；读不到才 fallback args.problem
  // （兼容旧调用；且后续 ensure-stage1-doc 会机制性补写，保证文件最终一定存在）。
  let presel = args
  let stage1Source = "args"   // 'args' | 'file'
  const stage1File = intermediatesDir + "/00-problem.json"
  try {
    const fileResult = await agent(
      `Read the file at ${stage1File}. If it exists, output its content exactly as-is. If it doesn't exist, output exactly "NOT_FOUND".`,
      { label: "load-stage1", phase: "初始化" }
    )
    if (fileResult && String(fileResult).trim() !== 'NOT_FOUND') {
      const parsed = typeof fileResult === 'string' ? JSON.parse(fileResult) : fileResult
      if (parsed && parsed.selectedProblem && parsed.problem) {
        presel = {
          selectedProblem: parsed.selectedProblem,
          problem: parsed.problem,
          attachments: parsed.attachments || [],
        }
        if (Array.isArray(parsed.attachments) && parsed.attachments.length > 0) {
          attachments = parsed.attachments   // 文件中的附件清单为权威
        }
        stage1Source = "file"
        log("从文件读取 Stage 1 产物: " + stage1File)
      } else {
        logError(ErrorLevel.WARNING, "初始化", "00-problem.json 格式不符（缺 selectedProblem/problem 字段），回退 args.problem")
      }
    } else {
      logError(ErrorLevel.WARNING, "初始化", "未找到 00-problem.json——使用 args.problem 作为 Stage 1 产物（随后 ensure-stage1-doc 会补写文件）")
    }
  } catch (err) {
    logError(ErrorLevel.WARNING, "初始化", "读取 00-problem.json 失败（" + err.message + "），回退 args.problem")
  }
  log("Stage 1 产物来源: " + (stage1Source === "file" ? "intermediates/00-problem.json（主 agent 提前落盘）" : "args.problem（未提前落盘，将由 workflow 补写）"))

  chosenAnalysis = presel.problem?.analysis || {}
  if (!chosenAnalysis.domain || !chosenAnalysis.objectives) {
    return { error: "预选题目缺少分析数据——请提供 problem.analysis (含 domain, objectives 等字段) 或 intermediates/00-problem.json" }
  }
  chosenAnalysis.problemId = presel.selectedProblem
  chosenAnalysis._rawDescription = presel.problem?.description || ""
  chosenAnalysis._dataProfile = presel.problem?.dataProfile || ""
  chosenAnalysis._paperRules = presel.problem?.paperRules || ""
  selection = {
    selected: presel.selectedProblem,
    reason: "用户在阶段一中选定",
    fallback: null,
    approachHint: (chosenAnalysis.mathType || []).join(", "),
    riskAssessment: (chosenAnalysis.keyChallenges || []).join("; "),
  }
  analyses = [chosenAnalysis]
  log("使用阶段一审题结果: " + presel.selectedProblem + " — " + (chosenAnalysis.domain || ""))
} else {
  // Full auto: run Phase 1+2 inside workflow
  const problemsInput = typeof args === "string" ? args : (args?.problems || [])
  if (!problemsInput || (Array.isArray(problemsInput) && problemsInput.length === 0)) {
    return { error: "未提供题目。传入格式: /math-model <题目文本> 或 {mode, problems:[...]} 或 {mode, selectedProblem, problem:{id,description,analysis}}" }
  }
  const problems = Array.isArray(problemsInput)
    ? problemsInput
    : [{ id: "A", raw: problemsInput }]

  // Phase 1: 审题
  phase("审题")
  log("[Phase 1/8] 审题开始 — 预计 3-5 分钟")

  const ANALYZE_PROMPT = (p, i) =>
    "## 题目" + (p.id || ("#" + (i + 1))) + "\n\n" +
    (p.raw || p.description || JSON.stringify(p)) + "\n\n" +
    "## 任务\n" +
    "你是数学建模竞赛的审题专家。仔细阅读题目，提取结构化信息：\n" +
    "1. **domain**: 问题所属领域\n" +
    "2. **background**: 1-2句话总结背景\n" +
    "3. **objectives**: 要优化/预测/求解的具体目标\n" +
    "4. **constraints**: 所有约束条件（显式+隐式）\n" +
    "5. **dataAvailable**: 提供了什么数据？数据量和维度？\n" +
    "6. **mathType**: 可能涉及的数学类型（可多选）\n" +
    "7. **difficulty**: low/medium/high\n" +
    "8. **keyChallenges**: 预判的主要难点\n" +
    "9. **subQuestions**: 识别题目中的所有子问题（如「问题一」「问题二」或以编号列表出现的独立问题）。每个子问题提取：id(Q1/Q2...)、label(完整标签)、summary(一句话概括要做什么)、objectives、constraints、dataRequired(需要哪些附件/数据)、mathType、keyChallenges、dependsOn(是否依赖前序问题，如Q2依赖Q1则填[Q1])。如果题目不分小问，返回空数组[]。\n\nStructured output only."

  analyses = safeFilter(await parallel(
    problems.map((p, i) => () =>
      agent(ANALYZE_PROMPT(p, i), {
        label: "审题:" + (p.id || ("#" + (i + 1))),
        schema: PROBLEM_ANALYSIS_SCHEMA,
      })
    )
  ), "审题")

  if (analyses.length === 0) {
    return { error: "审题阶段失败——所有 agent 均未返回结果", resumeSuggestion: "请检查 agent 调用是否正确后重试。" }
  }
  log("[Phase 1/8] 审题完成 ✓ — " + analyses.length + "/" + problems.length + " 道题目分析完成")

  // Phase 2: 选题
  phase("选题")
  log("[Phase 2/8] 选题开始 — 预计 2-4 分钟")

  const saveToFile = createSaveToFile(intermediatesDir, userFeedback)

  selection = problems.length === 1
    ? {
        selected: problems[0].id || "A",
        reason: "仅一道题目",
        fallback: null,
        approachHint: (analyses[0]?.mathType || []).join(", "),
        riskAssessment: (analyses[0]?.keyChallenges || []).join("; "),
      }
    : await agent(
      "## 选题决策\n\n" +
      "你是数学建模竞赛教练。根据以下题目分析，帮助选择最优题目。\n\n" +
      "## 题目分析\n" + JSON.stringify(analyses, null, 2) + "\n\n" +
      "## 选题维度\n" +
      "1. **模型匹配度**: 是否有成熟的数学框架？\n" +
      "2. **数据优势**: 附件数据是否足够？\n" +
      "3. **求解可行性**: 算法复杂度可控？代码实现难度？\n" +
      "4. **创新空间**: 能否在标准解法外做出亮点？\n" +
      "5. **风险**: 是否有数据陷阱或模型坑？\n\n" +
      "推荐题目 + 理由 + 备选 + 方向提示 + 风险评估。\n\nStructured output only." + saveToFile("02-selection.json"),
      { label: "选题", schema: SELECTION_SCHEMA }
    )

  if (!selection) {
    return { error: "选题阶段失败。", analyses }
  }
  log("[Phase 2/8] 选题完成 ✓ — 选定: " + selection.selected + " — " + (selection.reason || "").slice(0, 80))

  // Inject raw problem text into chosen analysis for downstream phases
  const p = problems.find(p => (p.id || "A") === selection.selected) || problems[0]
  if (p) {
    const a = analyses.find(a => a.problemId === selection.selected) || analyses[0]
    if (a) {
      a._rawDescription = p.raw || p.description || ""
      a._dataProfile = p.dataProfile || ""
      a._paperRules = p.paperRules || ""
    }
  }
}

// From here on, Phase 3-8 uses chosenAnalysis (set above)
chosenAnalysis = analyses.find(a => a.problemId === selection.selected) || analyses[0]

// ═══ 题面落盘（文档即共享：题目原文/数据画像/论文规则唯一真源）═══
// 三个"输入"是阶段一提取的逐字原文，被 19+ 处 agent prompt 引用。
// 旧做法：每处都内联完整原文（占每处 context 预算 ~8%，且 data-collector 处被截断）。
// 现在：启动时一次性写入 intermediates/00-problem.md（唯一一次全文注入），
// 之后所有 agent 需要时 `Read` 该文件，prompt 只给路径提示。
const PROBLEM_DOC = intermediatesDir + "/00-problem.md"
const PROBLEM_READ_HINT =
  "题目原文 / 附件数据画像 / 论文规则已落盘到 `" + PROBLEM_DOC + "`。**凡任务涉及题目细节（题意/数据/规则/结论依据），开写前必须 `Read` 该文件获取完整内容**；本 prompt 不内联全文，省上下文预算。"
if (!DRY_RUN) {
  await agent(
    "## 题面落盘（文档即共享——唯一一次全文传递，此后所有 agent 从磁盘 `Read`）\n\n" +
    "将以下三段内容**原样、逐字**写入 `" + PROBLEM_DOC + "`（用 Write 工具，不得改写/概括/删节/加标题）：\n\n" +
    "### 题目原文\n" + (chosenAnalysis._rawDescription || "（无）") + "\n\n" +
    "### 附件数据画像\n" + (chosenAnalysis._dataProfile || "（无）") + "\n\n" +
    "### 论文规则\n" + (chosenAnalysis._paperRules || "（无）") + "\n\n" +
    "写入后验证：`ls -la " + PROBLEM_DOC + "` 确认文件存在且非空（`wc -c` > 0）；若失败重试一次，仍失败在回复中标记 SAVE_FAILED。",
    { label: "write-problem-doc", phase: "初始化" }
  )
  log("[Phase 1-2/8] 题面已落盘: " + PROBLEM_DOC)
}

// ═══ Stage 1 产物机制性兜底：00-problem.json 一定存在 ═══
// 主 agent 按 SKILL.md Step 5 在 workflow 前落盘 00-problem.json（可选增强，可预先审查）；
// 但主 agent 可能忘记/失败——这里由 workflow 机制保证：文件不存在就从当前内存状态补写，
// 使「Stage 1 产物有文件记录」成为确定事实，不依赖主 agent 的自觉。
if (!DRY_RUN) {
  const stage1Analysis = { ...chosenAnalysis }
  delete stage1Analysis._rawDescription
  delete stage1Analysis._dataProfile
  delete stage1Analysis._paperRules
  const stage1Json = JSON.stringify({
    selectedProblem: selection.selected,
    problem: {
      id: selection.selected,
      description: chosenAnalysis._rawDescription || "",
      dataProfile: chosenAnalysis._dataProfile || "",
      paperRules: chosenAnalysis._paperRules || "",
      analysis: stage1Analysis,
    },
    attachments: attachments || [],
  }, null, 2)
  await agent(
    "## Stage 1 产物落盘（机制性兜底）\n\n" +
    "检查 `" + intermediatesDir + "/00-problem.json` 是否存在（`ls -la " + intermediatesDir + "/00-problem.json`）。\n" +
    "1. **若已存在**（主 agent 已在 workflow 前落盘）→ 直接确认输出「ALREADY_EXISTS」，不要修改。\n" +
    "2. **若不存在** → 用 Write 工具创建（`mkdir -p " + intermediatesDir + "` 后）写入以下 JSON（原样，不要改写/省略字段）：\n\n" +
    "```json\n" + stage1Json + "\n```\n\n" +
    "写入后验证：`ls -la " + intermediatesDir + "/00-problem.json && wc -c " + intermediatesDir + "/00-problem.json` 确认存在且非空；若失败重试一次。",
    { label: "ensure-stage1-doc", phase: "初始化" }
  )
  log("[Phase 1-2/8] Stage 1 产物已确认落盘: " + intermediatesDir + "/00-problem.json")
}

// ═══ 子问题提取 ═══
const subQuestions = (chosenAnalysis?.subQuestions?.length > 0)
  ? chosenAnalysis.subQuestions : []

// ═══ 初始化共享上下文 ═══
const ctx = {
  cfg,
  chosenAnalysis,
  selection,
  analyses,
  subQuestions,
  intermediatesDir,
  outputDir,
  codeDir,
  figuresDir,
  attachments,
  isPreSelected,
  currentYear,
  competition: COMPETITION,
  USER_INTERVENTION,
  userFeedback,
  innovationStrictness: INNOVATION_STRICTNESS,
  innovationThresholds,
  runFingerprint: JSON.stringify({
    competition: COMPETITION, outputDir,
    innovationStrictness: INNOVATION_STRICTNESS,
    selectedProblem: args?.selectedProblem || null,
  }),
  _envHasPdftotext: envHas.pdftotext,
  _envHasPython3: envHas.python3,
  _envHasXelatex: envHas.xelatex,
  saveToFile: createSaveToFile(intermediatesDir, userFeedback),
}

// ═══ Dry-run: 审题+选题完成后生成执行计划并退出 ═══
if (DRY_RUN) {
  log("--- Dry-run: 生成执行计划 ---")
  const planLines = [
    "# 数学建模执行计划（Dry-run）",
    "",
    "## 选定题目",
    "- 题号: " + (selection?.selected || '?'),
    "- 理由: " + (selection?.reason || '').slice(0, 200),
    "- 方向提示: " + (selection?.approachHint || ''),
    "- 风险评估: " + (selection?.riskAssessment || ''),
    "",
    "## 题目分析摘要",
    "- 领域: " + (chosenAnalysis?.domain || '?'),
    "- 目标: " + ((chosenAnalysis?.objectives || []).join('; ')),
    "- 约束: " + ((chosenAnalysis?.constraints || []).join('; ')),
    "- 数学类型: " + ((chosenAnalysis?.mathType || []).join(', ')),
    "- 难度: " + (chosenAnalysis?.difficulty || '?'),
    "- 数据充分性: " + (chosenAnalysis?.dataAvailable || '未评估'),
    "- 关键挑战: " + ((chosenAnalysis?.keyChallenges || []).join('; ')),
    "",
    "## 执行计划（Phase 3-8）",
    "",
    "| Phase | 内容 | 预计耗时 | 关键机制 |",
    "|-------|------|----------|----------|",
    "| 3. 文献调研 | 多角度搜索 → 精读 → 局限分析 | 5-10 min | 找出标准方法共同局限 |",
    "| 4. 建模方案 | 数据需求评估→(外部数据收集)→问题分析→EDA→Gap分析→单一建模方案(三维自查)→评审团⇄修订(max 6轮)→适配性预检 | 10-15 min | 正确性第一,低于阈值打回;数据真实不编造 |",
    "| 5⇄6. 求解⇄验证 | 算法→实现→baseline对比→5维验证→迭代修复→趋势退出 | 15-30 min | 数据说话;趋势恶化自动退出 |",
    "| 7. 写作 | 事实源表→叙事大纲→风格指南→顺序主编撰写→交叉审查⇄统一修复(max 3轮) | 15-25 min | 质量门:章节/摘要数字/图表引用/数字纪律 |",
    "| 8. 终审 | 摘要数字溯源→验证→LaTeX编译→评委自评 | 5-10 min | 摘要数字须有正文出处 |",
    "",
    "### 配置参数",
    "- 竞赛模式: " + COMPETITION,
    "- 创新必要性阈值: " + INNOVATION_STRICTNESS + " (" + innovationThresholds.desc + ")",
    "- 输出目录: " + outputDir,
    "- 附件: " + (attachments.length > 0 ? attachments.join(', ') : '无'),
    "",
    "### 依赖检查结果",
    "- pdftotext: " + (ctx._envHasPdftotext ? 'OK' : 'MISSING'),
    "- python3: " + (ctx._envHasPython3 ? 'OK' : 'MISSING'),
    "- xelatex: " + (ctx._envHasXelatex ? 'OK' : 'MISSING'),
    "",
    "## 模式说明",
    "| 模式 | Agent 用量 | 适用场景 |",
    "|------|-----------|----------|",
    "| quick | ~30-40 | 快速练习,熟悉流程 |",
    "| full | ~110-160 | 完整模式(默认),评委评审/求解/写作全迭代 |",
    ""
  ].join('\n')
  await agent("将以下内容写入文件: cat > " + intermediatesDir + "/execution-plan.md << 'PLANEOF'\n" + planLines + "PLANEOF", { label: "dry-run-exec-plan", phase: "dry-run" })
  log("--- 执行计划已写入: " + intermediatesDir + "/execution-plan.md ---")
  log("Dry-run 完成。审查执行计划后，去掉 dryRun 参数正式运行。")
  return { dryRun: true, executionPlan: intermediatesDir + "/execution-plan.md", message: "Dry-run 完成。审查执行计划后，去掉 dryRun 参数正式运行。" }
}

// ═══════════════════════════════════════════
// Phase 3: 文献调研（带 checkpoint 恢复）
// ═══════════════════════════════════════════
if (shouldSkipPhaseByName(skipPhases, 'literature')) {
  const cp = await loadCheckpoint(ctx, 'phase3-literature')
  if (!cp) {
    return buildErrorReport(ctx, 'phase3-literature', '无法跳过 literature：未找到 checkpoint。请先不带 skipPhases 完整运行一次。')
  }
  Object.assign(ctx, cp)
  log("[Phase 3/8] 文献调研 — 已从 checkpoint 恢复（skipPhases 跳过）")
} else {
  const litPhase = await runPhaseWithCheckpoint(ctx, 'phase3-literature', phase3_literature,
    // checkpoint 瘦身：allSources 曾占 300k+ 字符（含每篇文献完整抓取内容，写作只用数量+模型/claim 摘要）。
    // 只存精简后的来源列表 + 模型/claim 摘要 + 局限分析 + directionContext。
    ctx => ({
      allSources: (ctx.allSources || []).slice(0, 6).map(s => ({ url: s.url, title: s.title, sourceQuality: s.sourceQuality })),
      allModels: (ctx.allModels || []).slice(0, 10),
      allClaims: (ctx.allClaims || []).slice(0, 15),
      limitationAnalysis: ctx.limitationAnalysis,
      directionContext: ctx.directionContext,
    }),
    resumeFrom)
  if (litPhase?.error) {
    return buildErrorReport(ctx, 'phase3-literature', litPhase.error)
  }
}
if (USER_INTERVENTION && ctx.allSources) {
  await writeIntermediateSummary(ctx, 'phase3-literature', '文献调研摘要',
    '- 搜索角度: ' + cfg.searchAngles + ' 个\n' +
    '- 获取文献: ' + (ctx.allSources?.length || 0) + ' 篇\n' +
    '- 提取模型: ' + (ctx.allModels?.length || 0) + ' 个\n' +
    '- 关键信息: ' + (ctx.allClaims?.length || 0) + ' 条\n' +
    '- 局限分析: ' + (ctx.limitationAnalysis ? '完成' : '跳过（文献不足）'))
}

// ═══════════════════════════════════════════
// Phase 4: 建模方案（带 checkpoint 恢复）
// ═══════════════════════════════════════════
if (shouldSkipPhaseByName(skipPhases, 'modeling')) {
  const cp = await loadCheckpoint(ctx, 'phase4-modeling')
  if (!cp) {
    return buildErrorReport(ctx, 'phase4-modeling', '无法跳过 modeling：未找到 checkpoint。请先不带 skipPhases 完整运行一次。')
  }
  Object.assign(ctx, cp)
  log("[Phase 4/8] 建模方案 — 已从 checkpoint 恢复（skipPhases 跳过）")
} else {
  const modelPhase = await runPhaseWithCheckpoint(ctx, 'phase4-modeling', phase4_modeling,
    // checkpoint 瘦身：finalModel/problemAnalysis/edaReport 保留（写作与求解需要），
    // 提案/评审/适配性检查只留摘要与计数。
    ctx => ({
      finalModel: ctx.finalModel,
      gapAnalysis: typeof ctx.gapAnalysis === "string" ? ctx.gapAnalysis.slice(0, 2000) : ctx.gapAnalysis,
      innovationProposals: (ctx.innovationProposals || []).map(p => p && ({ approach: (p.approach || "").slice(0, 200) })),
      fitnessCheck: ctx.fitnessCheck,
      earlyJudgeReview: typeof ctx.earlyJudgeReview === "string" ? ctx.earlyJudgeReview.slice(0, 2000) : null,
      problemAnalysis: ctx.problemAnalysis,
      edaReport: ctx.edaReport,
      externalData: ctx.externalData ? { needsExternalData: ctx.externalData.needsExternalData, dataNeeds: ctx.externalData.dataNeeds, sources: (ctx.externalData.sources || []).map(s => ({ id: s.id, purpose: s.purpose, status: s.status, filePath: s.filePath, sourceUrl: s.sourceUrl, sourceTitle: s.sourceTitle, fetchedAt: s.fetchedAt, fields: s.fields, notes: s.notes })) } : null,
    }),
    resumeFrom)
  if (modelPhase?.error) {
    return buildErrorReport(ctx, 'phase4-modeling', modelPhase.error)
  }
}
if (USER_INTERVENTION && ctx.finalModel) {
  const fitScore = ctx.fitnessCheck?.totalScore ?? '?'
  const extSummary = ctx.externalData
    ? (ctx.externalData.needsExternalData
        ? ('外部数据: ' + (ctx.externalData.sources || []).filter(s => s.status === 'OK').length + ' 份成功 / ' + (ctx.externalData.sources || []).filter(s => s.status === 'NOT_FOUND').length + ' 份未找到')
        : '外部数据: 无需')
    : '外部数据: 未评估'
  await writeIntermediateSummary(ctx, 'phase4-modeling', '建模方案摘要',
    '- 问题分析: ' + (ctx.problemAnalysis ? '完成' : '跳过') + '\n' +
    '- EDA 数据探索: ' + (ctx.edaReport ? (ctx.edaReport.findings?.length || 0) + ' 条发现' : '无附件，跳过') + '\n' +
    '- ' + extSummary + '\n' +
    '- Gap 分析: ' + (ctx.gapAnalysis ? '完成' : '跳过') + '\n' +
    '- 建模方案: ' + (ctx.innovationProposals?.length || 0) + ' 个方案\n' +
    '- 最终方案: ' + ((ctx.finalModel?.approach || '').slice(0, 100)) + '\n' +
    '- 评审团审查: ' + (ctx.earlyJudgeReview ? '完成' : '未通过') + '\n' +
    '- 适配性评分: ' + fitScore + '/12')
}

// ═══════════════════════════════════════════
// Phase 5-6: 求解 ⇄ 验证（带 checkpoint 恢复）
// ═══════════════════════════════════════════
if (skipPhases.includes('baseline')) {
  ctx.skipBaseline = true
  log("[skipPhases] baseline 对比将在求解阶段跳过 — 复用已有基线结果")
}
const solvePhase = await runPhaseWithCheckpoint(ctx, 'phase5_6_solve_verify', phase5_6_solve_verify,
  // checkpoint 瘦身：currentSolution/baselineResult/robustnessReport 保留（写作需要）；
  // allIssues 截断 top 40、对抗/反思/重设计只留近期几条（曾占 120k+ 字符）。
  ctx => ({
    currentSolution: ctx.currentSolution,
    baselineResult: ctx.baselineResult,
    allIssues: (ctx.allIssues || []).slice(-40),
    iterationLog: (ctx.iterationLog || []).slice(-5),
    allAdversarialFindings: (ctx.allAdversarialFindings || []).slice(-10),
    allRethinkResults: (ctx.allRethinkResults || []).slice(-5),
    redesignHistory: (ctx.redesignHistory || []).slice(-3),
    overallRobustness: ctx.overallRobustness,
    robustnessReport: ctx.robustnessReport,
  }),
  resumeFrom)
if (solvePhase?.error) {
  return buildErrorReport(ctx, 'phase5_6_solve_verify', solvePhase.error)
}

// Guard: need a solution for writing
if (!ctx.currentSolution) {
  return buildErrorReport(ctx, 'phase5_6_solve_verify', '求解阶段未产生有效解。')
}
if (!ctx.finalModel) {
  return buildErrorReport(ctx, 'phase4-modeling', '建模阶段未产生有效方案。')
}

if (USER_INTERVENTION) {
  const baselineText = ctx.baselineResult
    ? '基线对比: ' + ((ctx.baselineResult.summary || '').slice(0, 80))
    : '基线对比: 无'
  await writeIntermediateSummary(ctx, 'phase5_6_solve_verify', '求解⇄验证摘要',
    '- 迭代轮数: ' + (ctx.iterationLog?.length || 0) + ' 轮\n' +
    '- 累计问题: ' + (ctx.allIssues?.length || 0) + ' 个\n' +
    '- 严重问题: ' + (ctx.allIssues ? ctx.allIssues.filter(i => i.severity === 'critical').length : 0) + ' 个\n' +
    '- 鲁棒性: ' + (ctx.overallRobustness || '?') + '\n' +
    '- 模型重设计: ' + (ctx.redesignHistory?.length || 0) + ' 次\n' +
    '- ' + baselineText)
}

// ═══════════════════════════════════════════
// Phase 7: 写作（带 checkpoint 恢复）
// ═══════════════════════════════════════════
const writePhase = await runPhaseWithCheckpoint(ctx, 'phase7-writing', phase7_writing,
  // checkpoint 极小化：全文（旧版 ~200k 字符）经 LLM 读写必然超限。
  // 写作 agent 已把每节落盘到 intermediates/05-writing/section-*.json，phase8 从磁盘重建即可。
  ctx => ({ writingDone: true, sectionIds: (ctx.paperSections || []).map(s => s.section) }),
  resumeFrom)
if (writePhase?.error) {
  return buildErrorReport(ctx, 'phase7-writing', writePhase.error)
}

if (USER_INTERVENTION && ctx.paperSections) {
  await writeIntermediateSummary(ctx, 'phase7-writing', '写作摘要',
    '- 叙事大纲: ' + (ctx.narrativeOutline ? '完成' : '跳过') + '\n' +
    '- 章节: ' + ctx.paperSections.length + ' 个\n' +
    '- 创新矩阵: ' + (ctx.innovationMatrix ? '完成' : '跳过') + '\n' +
    '- 交叉审查: ' + (ctx.crossSectionReview ? '完成' : '跳过'))
}

// ═══════════════════════════════════════════
// Phase 8: 终审
// ═══════════════════════════════════════════
const finalResult = await phase8_final(ctx)

return finalResult
